(window.JCPA_DATA=window.JCPA_DATA||{})["exams"]={"papers":[{"id":"2023-06","year":2023,"month":6,"label":"دورة حزيران 2023","session":"حزيران","src":"e281a5f2.json","questions":[{"num":1,"type":"mcq","q":"موظف دخله السنوي من الرواتب للعام 2022 بواقع 36,000 دينار ولديه دخل سنوي من الإيجارات بقيمة 12,000 دينار ومصاريف المجاري المدفوعة 500 دينار والمسقفات المدفوعة بقيمة 1,500 دينار وهو متزوج وزوجته لا تعمل، ولديه 3 أولاد الأول يدرس في الجامعة قيمة القسط السنوي 3,000 دينار والثاني يدرس في مدرسة خاصة قسطها السنوي 2,000 دينار؛ إن الضريبة المستحقة:","o":["3,090 دينار.","3,280 دينار.","3,990 دينار.","لا شيء مما ذكر."],"answer":1,"orig_answer":null,"law":"income","article":"9","status":"valid","explanation":"المادتان (9) و(18/ب): الدخل 48,000 − المجاري 500 = 47,500؛ الإعفاءات 9,000+9,000+1,000 لكل ولد عن التعليم (2,000) ⇒ خاضع 27,500 وضريبته 4,375؛ يُقاص من المسقفات بحدود نسبة دخل الإيجار (≈1,094) ⇒ ≈3,280 دينار. (حل تقديري)"},{"num":2,"type":"mcq","q":"وفقاً لقانون ضريبة الدخل فإن العبارة التالية صحيحة لنسبة ضريبة الدخل والمساهمة الوطنية:","o":["شركات التأجير التمويلي تخضع لنسبة 24% و 3% مساهمة وطنية.","شركات الاتصالات تخضع لنسبة 24% و 4% مساهمة وطنية.","شركات التأمين تخضع لنسبة 24% ضريبة دخل و 2% مساهمة وطنية.","جميع ما ذكر صحيح."],"answer":2,"orig_answer":null,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ب و/و): شركات التأمين 24% ومساهمة وطنية 2%؛ التأجير التمويلي 24%+4%، والاتصالات 24%+2%."},{"num":3,"type":"mcq","q":"شركة صناعة الكرتون المحدودة أعلنت في قائمة الدخل لسنة 2022 دخل صافٍ بقيمة 100,000 دينار وعليه فإن ضريبة الدخل المستحقة:","o":["19,000 دينار","17,000 دينار.","18,000 دينار.","16,000 دينار."],"answer":2,"orig_answer":null,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ب/1 و/ج/1): نسبة 20% مع تخفيض 10% لسنة 2022 للنشاط الصناعي ⇒ 20,000×90% = 18,000 (تُضاف مساهمة وطنية 1% = 1,000 بشكل منفصل)."},{"num":4,"type":"mcq","q":"إن نشاط صناعة الأدوية والملابس في السنة المالية 2023 خاضعة لضريبة الدخل بنسبة:","o":["20%.","18%.","19%.","17%."],"answer":2,"orig_answer":null,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ج/2): تخفيض الأدوية والملابس لسنة 2023 هو 5% من ضريبة 20% ⇒ 19%. (انتهت مدة التخفيضات الخمس سنوات بعد 2023)."},{"num":5,"type":"mcq","q":"حسب المادة 49 من قانون ضريبة الدخل يستوفى عن الدعوى رسم بنسبة:","o":["3% من الفرق بين مقدار الضريبة أو المطالبة والمقدار الذي يسلم به المدعي من تلك الضريبة أو المطالبة على أن لا يقل الرسم عن ثلاثين دينار بما في ذلك حالة عدم وجود ضريبة أو مطالبة لوقوع المدعي في خسارة وأن لا تزيد على ثلاثمائة دينار لكل فترة ضريبية عن جميع درجات التقاضي.","3% من الفرق بين مقدار الضريبة أو المطالبة والمقدار الذي يسلم به المدعي من تلك الضريبة أو المطالبة على أن لا يقل الرسم عن عشرين دينار بما في ذلك حالة عدم وجود ضريبة أو مطالبة لوقوع المدعي في خسارة وأن لا تزيد على مئتين دينار لكل فترة ضريبية عن كل درجة من درجات التقاضي.","3% من الفرق بين مقدار الضريبة أو المطالبة والمقدار الذي يسلم به المدعي من تلك الضريبة أو المطالبة على أن لا يقل الرسم عن ثلاثين دينار بما في ذلك حالة عدم وجود ضريبة أو مطالبة لوقوع المدعي في خسارة وأن لا تزيد على ثلاثمائة دينار لكل فترة ضريبية عن كل درجة من درجات التقاضي.","3% من الفرق بين مقدار الضريبة أو المطالبة والمقدار الذي يسلم به المدعي من تلك الضريبة أو المطالبة على أن لا يقل الرسم عن عشرين دينار بما في ذلك حالة عدم وجود ضريبة أو مطالبة لوقوع المدعي في خسارة وأن لا تزيد على مئتين دينار لكل فترة ضريبية عن جميع درجات التقاضي."],"answer":2,"orig_answer":null,"law":"income","article":"49","status":"valid","explanation":"المادة (49/أ): 3% من الفرق، حد أدنى 30 ديناراً وأعلى 300 دينار لكل فترة ضريبية عن كل درجة من درجات التقاضي."},{"num":6,"type":"mcq","q":"حسب قانون ضريبة الدخل رقم 38 لسنة 2018 وحسب المادة 72 فإن العبارة التالية صحيحة:","o":["يجوز للمدير أو الموظف المفوض منه أو المدقق حسب مقتضى الحال وفي أي وقت أن يصحح بناء على طلب المكلف الأخطاء الكتابية والحسابية التي تقع في القرارات والإشعارات عن طريق السهو العرضي تكون إجراءات التصحيح خاضعة للطعن.","يجوز للمدير أو الموظف المفوض منه أو المدقق حسب مقتضى الحال وفي أي وقت أن يصحح من تلقاء ذاته أو بناء على طلب المكلف الأخطاء الكتابية والحسابية التي تقع في القرارات والإشعارات عن طريق السهو العرضي ولا تكون إجراءات التصحيح خاضعة للطعن.","يجوز للمدير أو الموظف المفوض منه أو المدقق حسب مقتضى الحال وفي أي وقت أن يصحح من تلقاء ذاته الأخطاء الكتابية والحسابية التي تقع في القرارات والإشعارات عن طريق السهو العرضي وتكون إجراءات التصحيح خاضعة للطعن.","يجوز للمدير أو الموظف المفوض منه أو المدقق حسب مقتضى الحال وفي أي وقت أن يصحح من تلقاء ذاته أو بناء على طلب المكلف الأخطاء الكتابية والحسابية التي تقع في القرارات والإشعارات عن طريق السهو العرضي وتكون إجراءات التصحيح خاضعة للطعن."],"answer":1,"orig_answer":null,"law":"income","article":"72","status":"valid","explanation":"المادة (72): التصحيح من تلقاء ذاته أو بناءً على طلب المكلف ولا تكون إجراءات التصحيح خاضعة للطعن."},{"num":7,"type":"mcq","q":"أبرمت شركة الاتحاد عقد تأمين على مكتبها في عمان مع شركة ما وراء البحار ولمدة سنة كاملة يبدأ العقد بتاريخ 2022/3/1 وينتهي بتاريخ 2023/2/28 حيث بلغت قيمة عقد التأمين 200 ألف دينار، وقامت شركة التأمين بإعادة تأمين 75% من قيمة العقد لدى شركة جنيف السويسرية. وعليه قيمة مخصص الأقساط غير المكتسبة الواجب تنزيله في 2022/12/31 هو:","o":["32,328 دينار.","8,082 دينار.","24,246 دينار.","لا شيء مما ذكر."],"answer":1,"orig_answer":null,"law":"income","article":"6","status":"valid","explanation":"المادة (6/د): تُنزل مخصصات الأقساط غير المكتسبة بعد خصم حصة معيدي التأمين: 200,000×59/365 = 32,328 × 25% (المحتفظ به) = 8,082."},{"num":8,"type":"mcq","q":"وفق تعليمات احتساب حوافز ضريبية للقطاع الصناعي وفقاً لأحكام المادة 81 من قانون ضريبة الدخل حسب المعادلة التالية: (الدخل الصافي للنشاط الصناعي المستهدف ÷ مجموع الأرباح الصافية للمكلف من جميع الأنشطة والمصادر الأخرى) × الدخل الخاضع للضريبة للمكلف من جميع الأنشطة. وتسري هذه المعادلة على:","o":["للأنشطة الصناعية صناعة الأدوية والملابس وفقاً للجدول الملحق بالتعليمات.","إذا كان النشاط الصناعي مؤسسة مسجلة في المناطق التنموية.","إذا كان من الأنشطة الصناعية المستفيدة فعلياً من نظام تخفيض ضريبة الدخل في المناطق الأقل نمواً رقم (44) لسنة 2016","جميع ما ذكر خطأ."],"answer":null,"orig_answer":null,"law":"income","article":"","status":"unverified","explanation":"تعليمات حوافز القطاع الصناعي غير موجودة في نص القانون؛ لم يُتحقق من نطاق تطبيق المعادلة."},{"num":9,"type":"mcq","q":"أحد العبارات التالية ليست صحيحة؛ باستثناء الشركات المساهمة العامة والشركات المساهمة الخاصة المتداولة لغايات احتساب ضريبة الدخل على أرباح بيع أسهم أو حصص الشركات أو أرباح بيع أسهم أو حصص للشخص الطبيعي المقيم أو غير المقيم أو الشركات يتم:","o":["احتساب نسبة (1%) من قيمة البيع إذا كانت تزيد عن (500) ألف دينار ولا تتجاوز مليون دينار.","احتساب نسبة (0.75%) من قيمة البيع إذا كانت لا تزيد (250) ألف دينار وبما لا يقل عن (500) دينار.","احتساب نسبة (1.5%) من قيمة البيع إذا كانت تزيد عن مليون دينار ولا تتجاوز (3) مليون دينار.","احتساب نسبة (0.75%) من قيمة البيع إذا كانت لا تتجاوز (250) ألف دينار وبما لا يقل عن (100) دينار."],"answer":1,"orig_answer":null,"law":"income","article":"","status":"unverified","explanation":"نِسب ضريبة بيع الأسهم والحصص مصدرها تعليمات تنفيذية غير متوفرة في نص القانون؛ الإجابة تقديرية."},{"num":10,"type":"mcq","q":"وفقاً لقانون الضريبة العامة على المبيعات إحدى العبارات التالية صحيحة:","o":["تطبق محكمة البداية الضريبية ومحكمة الاستئناف الضريبية قانون الضريبة العامة على المبيعات بما لا يتعارض مع أصول المحاكمات المدنية.","تطبق محكمة البداية الضريبية قانون الضريبة العامة على المبيعات بما لا يتعارض مع أصول المحاكمات المدنية.","تطبق محكمة الاستئناف الضريبية الأصول المنصوص عليها في قانون أصول المحاكمات الجزائية بالقدر الذي لا يتعارض فيه مع أحكام قانون الضريبة العامة على المبيعات.","جميع ما ذكر خطأ."],"answer":2,"orig_answer":null,"law":"sales","article":"59","status":"valid","explanation":"المادة (59): تطبق محكمتا البداية والاستئناف الضريبيتان أصول المحاكمات الجزائية بالقدر الذي لا يتعارض مع أحكام القانون، وكذلك أصول المحاكمات المدنية."},{"num":11,"type":"mcq","q":"في حال إسقاط القضية بسبب الغياب لدى المحكمة فإن الجهات الملزمة بتبليغ الإسقاط هي:","o":["قرارات قضايا الدخل (محكمة الضريبة) وقرارات المبيعات (دائرة الضريبة).","قرارات الإسقاط لقضايا الدخل والمبيعات (محكمة الضريبة).","قرارات الإسقاط لقضايا الدخل والمبيعات (دائرة ضريبة الدخل).","كل ما ذكر غير صحيح."],"answer":1,"orig_answer":null,"law":"income","article":"46","status":"valid","explanation":"المادة (46/ج) من قانون الدخل: المحكمة هي من تبلغ قرار الإسقاط للمكلف أو وكيله، والمحكمة الضريبية نفسها تنظر قضايا الدخل والمبيعات."},{"num":12,"type":"mcq","q":"يجوز الاعتراض على قرار التغريم بمقتضى أحكام المادة 28 من قانون الضريبة العامة على المبيعات:","o":["لدى المحكمة خلال 30 يوم من تبلغ المكلف قرار التغريم.","لدى المدير خلال 30 يوم من تبلغ المكلف قرار التغريم.","لدى الوزير خلال 30 يوم من تبلغ المكلف قرار التغريم.","لدى هيئة الاعتراض المشكلة لهذه الغاية خلال 30 يوم من تبلغ المكلف قرار التغريم."],"answer":2,"orig_answer":null,"law":"sales","article":"29","status":"valid","explanation":"المادة (29/ب): يجوز الاعتراض لدى الوزير على قرارات التغريم الصادرة بموجب المادة (28) خلال 30 يوماً من التبلغ."},{"num":13,"type":"mcq","q":"أي من العبارات التالية تعتبر صحيحة فيما يتعلق بتأجيل توريد ضريبة المبيعات على السلع عند الاستيراد حسب المادة 14 من التعليمات رقم (1) لسنة 2010:","o":["للمدير تأجيل دفع الضريبة المترتبة على السلع والخدمات عند الاستيراد للمسجل حتى تتحقق واقعة البيع الواردة في الفقرة أ من المادة (4) من القانون وتكون موافقة المدير على التأجيل لا تزيد مدتها على سنة واحدة على أن لا يكون مستورد لحساب الغير.","للمدير تأجيل دفع الضريبة المترتبة على السلع عند الاستيراد للمسجل حتى تتحقق واقعة البيع الواردة في الفقرة أ من المادة (4) من القانون وتكون موافقة المدير على التأجيل لا تزيد مدتها على سنتين.","للمدير تأجيل دفع الضريبة المترتبة على السلع عند الاستيراد للمسجل حتى تتحقق واقعة البيع الواردة في الفقرة أ من المادة (4) من القانون أو التوريد وتكون موافقة المدير على التأجيل لا تزيد مدتها على سنة واحدة.","للمدير تأجيل دفع الضريبة المترتبة على السلع عند الاستيراد للمسجل حتى تتحقق واقعة البيع الواردة في الفقرة أ من المادة (4) من القانون وتكون موافقة المدير على التأجيل لا تزيد مدتها على سنة واحدة."],"answer":3,"orig_answer":null,"law":"sales","article":"26","status":"unverified","explanation":"المادة (26/د) تجيز للمدير تأجيل دفع الضريبة على الاستيراد للمسجل وفق التعليمات؛ مدة السنة الواحدة واردة في التعليمات رقم (1) لسنة 2010 وليست في القانون."},{"num":14,"type":"mcq","q":"حسب المادة 46 من قانون ضريبة الدخل إذا تم إسقاط الدعوى بسبب الغياب أو لأي سبب آخر ولم يتم تجديدها يعتبر القرار المطعون فيه قطعياً بعد مرور:","o":["ثلاثون يوماً من تاريخ تبليغ المحكمة قرار الإسقاط للمكلف أو وكيله وفي جميع الأحوال لا يجوز تجديد الدعوى المسقطة للسبب نفسه لأكثر من مرتين وبسبب مبرر.","ثلاثون يوماً من تاريخ تبليغ المحكمة قرار الإسقاط للمكلف أو وكيله وفي جميع الأحوال لا يجوز تجديد الدعوى المسقطة للسبب نفسه لأكثر من مرة وبسبب مبرر.","ثلاثون يوماً من تاريخ إسقاط الدعوى وفي جميع الأحوال لا يجوز تجديد الدعوى المسقطة للسبب نفسه لأكثر من مرتين وبسبب مبرر.","ثلاثون يوماً من تاريخ إسقاط الدعوى وفي جميع الأحوال لا يجوز تجديد الدعوى المسقطة للسبب نفسه لأكثر من مرة وبسبب مبرر."],"answer":0,"orig_answer":null,"law":"income","article":"46","status":"valid","explanation":"المادة (46/ج): ثلاثون يوماً من تاريخ تبليغ المحكمة قرار الإسقاط، ولا يجوز التجديد لأكثر من مرتين وبسبب مبرر."},{"num":15,"type":"mcq","q":"مصنع (أ) ينتج سلع خاضعة لضريبة المبيعات بنسبة 16% قام ببيع بضاعة بقيمة 10,000 دينار إلى الشركة (ب) بموجب بيان جمركي إدخال المنطقة الحرة بناءً على طلب الشركة (ب) علماً بأن الشركة (ب) ليست مسجلة بالمنطقة الحرة: - إن ضريبة المبيعات المستحقة على المصنع (أ) هي:","o":["700 دينار.","500 دينار.","1,600 دينار.","لا شيء مما ذكر."],"answer":2,"orig_answer":null,"law":"sales","article":"","status":"unverified","explanation":"البيع لشركة غير مسجلة في المنطقة الحرة لا يعامل كتصدير بنسبة الصفر وفق التعليمات ⇒ 10,000×16% = 1,600 (تقديري؛ الحكم في التعليمات)."},{"num":16,"type":"mcq","q":"بلغت قيمة مبيعات الشقق لشركة إسكانات البناء الحديث لسنة 2020 بقيمة 150,000 دينار، إن ضريبة الدخل المستحقة على الشركة حسب تعليمات نسب الأرباح:","o":["3,000 دينار.","4,500 دينار.","5,250 دينار.","3,750 دينار."],"answer":1,"orig_answer":null,"law":"income","article":"","status":"unverified","explanation":"يعتمد على تعليمات نسب الأرباح لشركات الإسكان (غير متوفرة في نص القانون)؛ الإجابة تقديرية."},{"num":17,"type":"mcq","q":"قدمت الشركة المتحدة إقرار ضريبة الدخل لسنة 2019 بتاريخ 2020/3/31 وأعلنت عن ضريبة دخل بقيمة 10,000 دينار لم تقم بدفعها. بتاريخ 2021/5/31 وافقت الشركة على قرار المدقق الضريبي بتعديل الإقرار لتصبح الضريبة المستحقة 12,000 دينار، إن غرامة تأخير دفع الضريبة على الشركة بتاريخ 2021/5/31 هي:","o":["2,736 دينار.","2,928 دينار.","2,440 دينار.","لا شيء مما ذكر."],"answer":0,"orig_answer":null,"law":"income","article":"36","status":"valid","explanation":"المادة (36/أ): لم تُدفع الضريبة المصرح بها ⇒ غرامة 4 بالألف أسبوعياً على كامل 12,000 من 2020/5/1 حتى 2021/5/31 (57 أسبوعاً) = 2,736."},{"num":18,"type":"mcq","q":"قامت شركة باستيراد خدمة بتاريخ 2022/1/1 وسجلت الخدمة بالمصاريف بتاريخ الفاتورة في 2022/1/1، قامت الشركة بدفع قيمة الفاتورة بتاريخ 2022/5/1، إذا علمت أن قيمة الخدمة 1,000 دينار وأن الشركة قامت بدفع ضريبة المبيعات على الخدمة المستوردة بتاريخ 2022/6/12 فإن قيمة الضريبة والغرامات المستحقة هي:","o":["160 دينار + 320 مثلي الضريبة + غرامة 12.60 دينار غرامة 4 بالألف + 200-1000 دينار غرامة جزائية.","160 دينار + غرامة 12.60 دينار غرامة 4 بالألف + 100-500 دينار غرامة جزائية.","160 دينار + غرامة 1.28 دينار غرامة 4 بالألف.","160 دينار + غرامة 1.28 دينار غرامة 4 بالألف + 100-500 دينار غرامة جزائية."],"answer":2,"orig_answer":null,"law":"sales","article":"26","status":"valid","explanation":"المادة (26/ج/1) و(51): تُدفع ضريبة الخدمة المستوردة خلال شهر من دفع البدل (حتى 2022/6/1)؛ التأخير أسبوعان ⇒ 160×0.004×2 = 1.28 دينار."},{"num":19,"type":"mcq","q":"حسب المادة 30 من قانون الضريبة العامة على المبيعات أي من العبارات التالية صحيحة ويعتبر من جرائم التهرب الضريبي:","o":["تطبيق نسب أو فئات ضريبية على السلع أو الخدمات الخاضعة للضريبة بصورة مخالفة لأحكام هذا القانون إذا أدى ذلك إلى نقص في مقدار الضريبة المستحقة يتجاوز مئتين دينار.","استيفاء ضريبة غير مستحقة وتوريدها خلال المدة التي يحددها القانون لتوريد الضريبة.","التخلف عن تقديم طلب التسجيل لدى الدائرة في الموعد المحدد للتسجيل بموجب هذا القانون.","جميع ما ذكر غير صحيح."],"answer":3,"orig_answer":null,"law":"sales","article":"30","status":"valid","explanation":"المادة (30): التهرب يتطلب نقصاً يتجاوز 500 دينار (لا 200)، واستيفاء ضريبة غير مستحقة ليس تهرباً إذا وُردت خلال المدة، والتخلف عن التسجيل تهرب إذا زاد على 60 يوماً."},{"num":20,"type":"mcq","q":"أي من الحالات الآتية لا تستوجب فرض غرامة لا تقل عن 100 دينار ولا تتجاوز 500 دينار:","o":["عدم إعلام الدائرة بالتغييرات التي طرأت على البيانات الواردة في طلب التسجيل خلال الموعد المحدد.","عدم خصم الضريبة أو ردها بصورة مخالفة للقانون إذا ظهرت زيادة في الخصم أو الرد يتجاوز 500 دينار.","عدم تمكين موظفي الدائرة من ممارسة صلاحياتهم في التفتيش والرقابة.","التخلف عن تقديم الإقرارات الضريبية مدة لا تزيد عن (60) يوماً."],"answer":1,"orig_answer":null,"law":"sales","article":"28","status":"valid","explanation":"المادتان (28/ط) و(30/ز): زيادة الخصم أو الرد بما يتجاوز 500 دينار تعد تهرباً لا مخالفة غرامتها 100-500."},{"num":21,"type":"mcq","q":"قامت شركة بشراء أثاث بفواتير ضريبية بقيمة 5,000 دينار وضريبة مبيعات 800 دينار عند بداية عملها في 2022/1/1، بتاريخ 2022/4/1 قامت الشركة بالتسجيل في الشبكة العامة لضريبة المبيعات وأرفقت كشوفات جرد المستودعات الذي ظهرت فيها قيمة البضاعة 15,312 دينار وبفواتير ضريبية وجرد الموجودات الثابتة والضرائب المدفوعة، تستهلك الشركة موجوداتها الثابتة بنسبة 10% سنوياً، إن ضريبة المبيعات واجبة التخصيم:","o":["2,892 دينار.","3,250 دينار.","3,170 دينار.","3,230 دينار."],"answer":0,"orig_answer":null,"law":"sales","article":"19","status":"unverified","explanation":"ضريبة البضاعة: 15,312×16/116 = 2,112؛ الأثاث 800 بعد استهلاك 3 أشهر (2.5%) = 780 ⇒ 2,892. الأسلوب وفق تعليمات الخصم عند التسجيل."},{"num":22,"type":"mcq","q":"حسب قانون الضريبة العامة على المبيعات أي من العبارات التالية غير صحيحة:","o":["لا تخضع للضريبة السلع والخدمات المهربة.","تستحق الضريبة العامة والخاصة على السلع المستوردة في مرحلة التخليص عليها حسب نسبة الضريبة أو فئتها في تاريخ تسجيل البيان.","لا يخضع للضريبة العامة على المبيعات بيع الأموال غير المنقولة.","تستحق الضريبة على بيع الخدمة عند إصدار فاتورة ضريبية وعند تسلم بدل الخدمة كلياً أو جزئياً أيهما أسبق."],"answer":0,"orig_answer":null,"law":"sales","article":"15","status":"valid","explanation":"السلع والخدمات المهربة تخضع للضريبة (المادة 15/هـ)؛ ولا تخضع بيوع الأموال غير المنقولة (المادة 10/ب)."},{"num":23,"type":"mcq","q":"يجوز لأي شركة أن تعترض خطياً لدى الوزير بتسجيل شركة أخرى لإلغاء تسجيل تلك الشركة الأخرى إذا كان الاسم الذي سجلت به مماثلاً لاسمها أو يشبهه إلى درجة قد تؤدي إلى اللبس أو الغش وذلك:","o":["لا يوجد مدة محددة.","خلال ستين يوماً من تاريخ نشر القرار في الجريدة الرسمية.","خلال تسعين يوماً من تاريخ نشر القرار في الجريدة الرسمية.","خلال ثلاثون يوماً من تاريخ نشر القرار في الجريدة الرسمية."],"answer":1,"orig_answer":null,"law":"companies","article":"5","status":"valid","explanation":"المادة (5/ب): الاعتراض لدى الوزير خلال ستين يوماً من تاريخ نشر قرار التسجيل في الجريدة الرسمية."},{"num":24,"type":"mcq","q":"سنداً لأحكام نظام تصفية الشركات، لمراقب عام الشركات أثناء السير في إجراءات التصفية الاختيارية إحالة الشركة للمحكمة لتستمر التصفية تحت إشرافها أو لتصفية الشركة تصفية إجبارية للأسباب التي يضمنها طلبه وذلك:","o":["بعد مدة أقصاها ثلاث سنوات.","بأي وقت أثناء السير بإجراءات التصفية.","بعد مدة أقصاها سنتين.","بعد مدة أقصاها سنة من تاريخ التصفية."],"answer":1,"orig_answer":null,"law":"other:نظام تصفية الشركات","article":"","status":"unverified","explanation":"حكم وارد في نظام تصفية الشركات (غير متوفر)؛ الإجابة تقديرية."},{"num":25,"type":"mcq","q":"سنداً لأحكام نظام تصفية الشركات، لا يجوز في أي حال من الأحوال أن يتجاوز مجموع أتعاب المصفي نسبة:","o":["30% من واردات أموال التصفية.","10% من واردات أموال التصفية.","20% من واردات أموال التصفية.","5% من واردات أموال التصفية"],"answer":1,"orig_answer":null,"law":"other:نظام تصفية الشركات","article":"","status":"unverified","explanation":"حكم وارد في نظام تصفية الشركات (غير متوفر)؛ الإجابة تقديرية."},{"num":26,"type":"mcq","q":"تعتبر أي عوائد إضافية تحققها الشركات التي لا تهدف إلى تحقيق الربح وفراً لها ولا يجوز استخدامها:","o":["يجوز استخدام تلك العوائد وفقاً لما يراه مجلس الإدارة مناسب.","إلا للشركاء.","إلا لتحقيق غاياتها والأهداف التي أنشئت من أجلها.","إلا للجهات المانحة."],"answer":2,"orig_answer":null,"law":"companies","article":"7","status":"valid","explanation":"المادة (7/د) ونظام الشركات غير الربحية: لا تستخدم العوائد إلا لتحقيق غاياتها وأهدافها."},{"num":27,"type":"mcq","q":"يحق للمساهمين الطلب من مراقب عام الشركات إجراء تدقيق على أعمال الشركة بعد تقديمهم كفالة لتغطية نفقات التدقيق:","o":["مساهمين يملكون 40% من رأسمال الشركة.","مساهمين يملكون 5% من رأسمال الشركة.","مساهمين يملكون 10% من رأسمال الشركة.","مساهمين يملكون 1% من رأسمال الشركة."],"answer":2,"orig_answer":null,"law":"companies","article":"275","status":"valid","explanation":"المادة (275): مساهمون يملكون 10% على الأقل من رأس المال مع كفالة بنكية لتغطية نفقات التدقيق."},{"num":28,"type":"mcq","q":"تحدد بدلات الانتقال والسفر لرئيس وأعضاء مجلس الإدارة بموجب:","o":["بموجب نظام خاص تصدره الشركة لهذه الغاية.","قرار يتخذه مراقب عام الشركات.","قرار يتخذه المراقب ومجلس الإدارة.","قرار يتخذه مجلس إدارة الشركة."],"answer":0,"orig_answer":null,"law":"companies","article":"162","status":"valid","explanation":"المادة (162/د): تحدد بدلات الانتقال والسفر بموجب نظام خاص تصدره الشركة."},{"num":29,"type":"mcq","q":"سنداً لتعليمات الأسهم القابلة للاسترداد، عند قيام الشركة باسترداد الأسهم القابلة للاسترداد يترتب على الشركة تقديم كتاب من مدقق الحسابات:","o":["يبين المعالجة المحاسبية لاسترداد هذه الأسهم.","يبين عدد هذه الأسهم.","يبين آلية نشوء هذه الأسهم.","يبين نوع هذه الأسهم."],"answer":0,"orig_answer":null,"law":"companies","article":"","status":"unverified","explanation":"تعليمات الأسهم القابلة للاسترداد غير متوفرة في نص القانون؛ الإجابة تقديرية."},{"num":30,"type":"mcq","q":"تصدر القرارات في اجتماع الهيئة العامة غير العادي للشركة المساهمة العامة بأكثرية:","o":["75% من مجموع الأسهم الممثلة في الاجتماع.","50% من مجموع الأسهم الممثلة في الاجتماع.","(50%+1) من مجموع الأسهم الممثلة في الاجتماع.","40% من مجموع الأسهم الممثلة في الاجتماع."],"answer":0,"orig_answer":null,"law":"companies","article":"175","status":"valid","explanation":"المادة (175/ب): أكثرية 75% من الأسهم الممثلة في الاجتماع غير العادي."},{"num":31,"type":"mcq","q":"يعتبر أي اجتماع تعقده الهيئة العامة للشركة المساهمة العامة المحدودة باطلاً:","o":["إذا لم يحضر الوزير أو من ينتدبه خطياً.","إذا لم يحضر مراقب عام الشركات أو من ينتدبه خطياً من موظفي الدائرة ومدقق حسابات الشركة.","إذا لم يحضر مدقق حسابات الشركة.","إذا لم يحضر مراقب عام الشركات أو من ينتدبه خطياً من موظفي الدائرة."],"answer":3,"orig_answer":null,"law":"companies","article":"182","status":"valid","explanation":"المادة (182): يعتبر الاجتماع باطلاً إذا لم يحضره المراقب أو من ينتدبه خطياً من موظفي الدائرة."},{"num":32,"type":"mcq","q":"تتكون هيئة مالكي إسناد القرض من:","o":["مالكي إسناد القرض.","مجلس الإدارة ومساهمي الشركة.","مالكي إسناد القرض ومجلس الإدارة.","مساهمي الشركة."],"answer":0,"orig_answer":null,"law":"companies","article":"126","status":"valid","explanation":"المادة (126/أ): تتكون حكماً من مالكي إسناد القرض في كل إصدار."},{"num":33,"type":"mcq","q":"إذا تخلفت الهيئة العامة للشركة عن انتخاب مدقق الحسابات أو اعتذر المدقق الذي انتخبه عن العمل أو امتنع عن القيام به لأي سبب من الأسباب أو توفي:","o":["يبقى شاغراً تعيين مدقق لحين اجتماع هيئة عامة قادم.","يعين مراقب عام الشركات من تلقاء نفسه مدقق حسابات.","يعين مجلس الإدارة مدقق حسابات.","على مجلس الإدارة أن ينسب للمراقب ثلاثة من مدققي الحسابات على الأقل وذلك خلال أربعة عشر يوماً من تاريخ شغور هذا المركز ليختار أحدهم."],"answer":3,"orig_answer":null,"law":"companies","article":"192","status":"valid","explanation":"المادة (192/ب): ينسب المجلس للمراقب ثلاثة مدققين على الأقل خلال 14 يوماً من الشغور ليختار أحدهم."},{"num":34,"type":"mcq","q":"إحدى العبارات التالية الصحيحة:","o":["للشركة ذات المسؤولية المحدودة أن تخفض رأسمالها بدون أي سبب.","للشركة ذات المسؤولية المحدودة أن تخفض رأسمالها إذا لحقت بها خسائر فقط.","للشركة ذات المسؤولية المحدودة أن تخفض رأسمالها إذا زاد عن حاجتها أو لحقت بها خسائر تزيد عن نصف رأسمالها.","للشركة ذات المسؤولية المحدودة أن تخفض رأسمالها إذا زاد عن حاجتها فقط."],"answer":2,"orig_answer":null,"law":"companies","article":"68","status":"valid","explanation":"المادة (68/أ): للمحدودة المسؤولية تخفيض رأسمالها إذا زاد عن حاجتها أو لحقت بها خسائر تزيد على نصف رأسمالها."},{"num":35,"type":"mcq","q":"أي من العبارات التالية تعتبر غير صحيحة بموجب قانون التجارة رقم (12) لعام 1966.","o":["يجوز إعادة الاعتبار للمفلس بعد وفاته.","تخضع الشركات المدنية والشركات المرخصة أو المسجلة بمقتضى قانون الشركات الساري المفعول إلى إجراءات التصفية الفسخ الواردة فيه.","لا يجوز إعادة الاعتبار إلى المفلسين الذين حكم عليهم بالإفلاس الاحتيالي أو بسرقة أو احتيال أو إساءة أمانة إلا إذا كانوا قد حصلوا على إعادة الاعتبار الجزائي.","جميع العبارات صحيحة."],"answer":1,"orig_answer":null,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة 1966 غير متوفر في قاعدة النصوص؛ الإجابة تقديرية."},{"num":36,"type":"mcq","q":"أي من العبارات التالية تعتبر صحيحة فيما يتعلق بالسندات بالمادة (97) من قانون التجارة رقم (12) لعام 1966.","o":["إذا تعددت سندات الرجوع يجوز مطالبة آخر مظهر للسند بنفقات سند رجوع واحد.","إذا تعددت سندات الرجوع يجوز مطالبة ساحب السند الأصلي وكل مظهر له بنفقات كل سند رجوع.","إذا تعددت سندات الرجوع فلا يجوز مطالبة ساحب السند الأصلي وكل مظهر له إلا بنفقات سند رجوع واحد.","جميع العبارات غير صحيحة."],"answer":2,"orig_answer":null,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة 1966 غير متوفر؛ المقرر أنه لا يطالب الساحب والمظهرون إلا بنفقات سند رجوع واحد."},{"num":37,"type":"mcq","q":"أي من العبارات التالية تعتبر غير صحيحة فيما يتعلق بالعقود التجارية حسب قانون التجارة:","o":["كل التزام تجاري يقصد به القيام بعمل أو بخدمة لا يعد معقوداً على وجه مجاني وإذا لم يعين الفريقين أجرة أو عمولة أو سمسرة فيستحق الدائن الأجر المعروف في المهنة.","يعتمد في إثبات العدل والثمن الدارج على أسعار البورصة والتسعيرات إن وجدت ما لم يوجد اتفاق مخالف.","يخضع إثبات العقود التجارية مبدئياً للقواعد الحصرية الموضوعة للعقود المدنية.","أ+ب غير صحيح."],"answer":2,"orig_answer":null,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة 1966 غير متوفر؛ الإثبات في المواد التجارية حر ولا يخضع مبدئياً للقواعد الحصرية للعقود المدنية."},{"num":38,"type":"mcq","q":"بموجب قانون التجارة فيما يتعلق بالوكالة التجارية فإن إحدى العبارات التالية غير صحيحة:","o":["الوكيل الذي لم يتلق تعليمات إلا في شأن جزء من العمل لا يعد مطلق اليد في الجزء الباقي.","الوكالة التجارية وإن احتوت على توكيل مطلق لا تجيز الأعمال غير التجارية إلا بنص صريح.","عندما يعمل الوكيل باسم موكله تكون حقوقه والتزاماته خاضعة للأحكام الواردة بهذا الشأن في القانون المدني.","يسمى هذا العقد وكالة بالعمولة ويجب على الوكيل أن يعمل باسمه الخاص أو تحت عنوان تجاري لحساب من وكله."],"answer":0,"orig_answer":null,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة 1966 غير متوفر؛ الوكيل الذي لم يتلق تعليمات إلا بشأن جزء من العمل يعد مطلق اليد في الجزء الباقي."},{"num":39,"type":"mcq","q":"حسب المادة (211) من قانون التجارة رقم 12 لعام 1966 جميع العبارات التالية صحيحة ماعدا:","o":["يكون لهذه الصورة ما للأصل من أحكام.","لا يجوز أن يُظهر الصورة وضمانها احتياطياً على الوجه الذي يجري عليه الأصل.","لحامل السند أن يحرر صوراً منه.","جميع العبارات غير صحيحة."],"answer":1,"orig_answer":null,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة 1966 غير متوفر؛ يجوز تظهير الصورة وضمانها احتياطياً كالأصل."},{"num":40,"type":"mcq","q":"على المحاسب القانوني المسجل في سجل غير المزاولين والراغب في العودة إلى التسجيل في سجل المزاولين للمهنة أن يقدم للمجلس شهادة تعليم مستمر قبل نقل اسمه إلى سجل المزاولين بعدد ساعات هي:","o":["40 ساعة.","30 ساعة.","20 ساعة.","لا شيء مما ذكر."],"answer":null,"orig_answer":null,"law":"accounting","article":"","status":"unverified","explanation":"ساعات التعليم المستمر للعودة لسجل المزاولين ترد في النظام/التعليمات لا في القانون؛ لم يتحقق منها."},{"num":41,"type":"mcq","q":"تتولى الجمعية في سبيل تحقيق أهدافها المهام والصلاحيات التالية ماعدا:","o":["تطوير التشريعات ذات العلاقة بالمهنة.","الانضمام إلى عضوية الهيئات العربية والدولية ذات العلاقة بالمهنة إذا رأت ذلك مناسباً.","التعاون في مجال المهنة مع الجامعات والمؤسسات التعليمية.","توثيق العلاقات المهنية والاجتماعية بين مزاولي المهنة محلياً وعربياً ودولياً."],"answer":0,"orig_answer":null,"law":"accounting","article":"9","status":"valid","explanation":"المادة (9/هـ): مهمة الجمعية «اقتراح» تطوير التشريعات لا تطويرها؛ باقي الخيارات واردة نصاً."},{"num":42,"type":"mcq","q":"كل من خالف أحكام المادة (21) من قانون تنظيم مهنة المحاسبة القانونية لسنة 2003 والتي تحظر على أي شخص غير حاصل على إجازة المزاولة وغير مسجل في سجل المزاولين وقام بمزاولة أعمال التدقيق بالعقوبة التالية:","o":["يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على ثلاث سنوات أو بغرامة لا تقل عن خمسة آلاف دينار ولا تزيد على عشرين ألف دينار أو بكلتا العقوبتين.","يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على ثلاث سنوات أو بغرامة لا تقل عن أربعة آلاف دينار ولا تزيد على عشرة آلاف دينار أو بكلتا العقوبتين.","يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على أربع سنوات أو بغرامة لا تقل عن خمسة آلاف دينار ولا تزيد على عشرين ألف دينار أو بكلتا العقوبتين.","يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على أربع سنوات أو بغرامة لا تقل عن خمسة آلاف دينار ولا تزيد على عشرة آلاف دينار أو بكلتا العقوبتين."],"answer":0,"orig_answer":null,"law":"accounting","article":"43","status":"valid","explanation":"المادة (43/أ/1): حبس سنة إلى ثلاث سنوات أو غرامة 5,000-20,000 دينار أو كلتاهما."},{"num":43,"type":"mcq","q":"أي من العبارات التالية غير صحيحة فيما يتعلق بضمانات المسؤولية المدنية المنصوص عليها في المادة (56) من القانون على وكيل الإعسار:","o":["على وكيل الإعسار تقديم ضمانات كافية أو استصدار بوليصة تأمين ضد المسؤولية المهنية وفقاً للشروط التي ينص عليها النظام الذي يصدر بموجب أحكام هذا القانون.","يسقط حق المطالبة بالتعويض المنصوص عليه في الفقرة أ بمرور ثلاث سنوات على تاريخ علم المضرور بالضرر وبالشخص المسؤول عنه أو بمرور ثلاث سنوات على تاريخ استكمال إجراءات الإعسار أيهما يقع أولاً.","يكون وكيل الإعسار مسؤولاً عن أي ضرر يلحق بذمة الإعسار أو بالأشخاص الذين اشتركوا في إجراءات الإعسار نشأ عن إهماله أو إهمال ممثليه أو تابعيه في أداء مهامهم أو إخلالهم بالواجبات المنوطة بهم.","جميع العبارات صحيحة."],"answer":1,"orig_answer":null,"law":"insolvency","article":"56","status":"valid","explanation":"المادة (56/ب): يسقط الحق بمرور ثلاث سنوات أيهما يقع «لاحقاً» لا أولاً."},{"num":44,"type":"mcq","q":"حسب المادة (51) من قانون الإعسار إن العبارة التالية صحيحة:","o":["على وكيل الإعسار أن يؤدي واجباته بنفسه وبالدقة والأمانة المطلوبة وأن يلتزم الحياد مع جميع الجهات التي تتأثر بإجراءات الإعسار.","يحظر على وكيل الإعسار تفويض مهامه للغير إلا في ظروف استثنائية على أن يكون التفويض محدداً من حيث المدة والمهام وبموافقة المحكمة على أن يكون وكيل الإعسار مسؤولاً عن أعمال المفوض.","لوكيل الإعسار الاستعانة بخبراء يختارهم لتنفيذ مهامه على أن يبقى مسؤولاً عن تنفيذ تلك المهام ويتحمل أتعاب الخبراء ما لم يقرر الدائنين غير ذلك.","جميع العبارات غير صحيحة."],"answer":0,"orig_answer":null,"law":"insolvency","article":"51","status":"valid","explanation":"المادة (51): الدقة والأمانة والحياد (أ)؛ أتعاب الخبراء ما لم تقرر «المحكمة» لا الدائنون، والمفوض ووكيل الإعسار مسؤولان بالتكافل والتضامن. (كلمة «بنفسه» غير واردة في النص)."},{"num":45,"type":"mcq","q":"حسب قانون الإعسار فإن العبارة التالية غير صحيحة:","o":["لدائني هذه الديون الحق في تقديم دفوعهم واعتراضاتهم على طلب المدين بالإبراء خلال مدة سبعة أيام من تاريخ تبلغهم الطلب.","تعلن المحكمة انتهاء إجراءات الإعسار بعد إتمام التوزيع النهائي أو إذا تم سداد كامل الديون أثناء السير في إجراءات الإعسار ويتم إشهار قرار المحكمة وسبب انتهاء الإجراءات.","للمدين حسن النية تقديم طلب للمحكمة بالإبراء من الديون غير المسددة وعلى المحكمة تبليغ هذا الطلب إلى دائني هذه الديون ووكيل الإعسار خلال أسبوع من وروده إليها.","إذا كان المدين شخصاً اعتبارياً، تنتهي شخصيته الاعتبارية باستكمال توزيع العوائد ما لم يتم سداد ديونه بالكامل وعلى وكيل الإعسار تبليغ الجهة التي تم تسجيل الشخص الاعتباري لديها بقرار المحكمة لغايات شطب تسجيله وفقاً للتشريعات ذات العلاقة."],"answer":2,"orig_answer":null,"law":"insolvency","article":"108","status":"valid","explanation":"المادة (108/أ): تبلغ المحكمة طلب الإبراء «فور وروده» لا خلال أسبوع."},{"num":46,"type":"mcq","q":"حسب قانون البيئة الاستثمارية رقم (21) لسنة 2022 أي من العبارات التالية تعتبر غير صحيحة:","o":["إذا لم يقم المطور الرئيسي بإنجاز أعمال التطوير في المنطقة التنموية على الوزارة مطالبته بغرامة نسبتها (2%) من قيمة الأرض السوقية التي لم يتم تطويرها وذلك عن كل سنة تأخير عن الجدول الزمني المحدد في اتفاقية التطوير.","على الرغم مما ورد في أي تشريع آخر، لا تطبق في المنطقة التنموية أي قيود متعلقة بنسبة رأس المال الأجنبي.","على الرغم مما ورد في أي تشريع آخر، تعتبر الرخصة الممنوحة في المنطقة التنموية لممارسة النشاط الاقتصادي في المنطقة بمثابة رخصة مهن.","لا شيء مما ذكر غير صحيح."],"answer":3,"orig_answer":null,"law":"investment","article":"19","status":"valid","explanation":"المواد (19/د) غرامة 2% سنوياً، (27/أ) لا قيود على رأس المال الأجنبي، (26) الرخصة بمثابة رخصة مهن ⇒ جميعها صحيحة."},{"num":47,"type":"mcq","q":"حسب قانون التأجير التمويلي رقم 45 لسنة 2008 أي من العبارات التالية غير صحيحة:","o":["لا يترتب على تأجير المأجور من الباطن أي مساس في حقوق المستأجر والتزاماته المحددة في عقد التأجير في مواجهة المؤجر.","إذا كان المستأجر أجنبياً أو شخص اعتباري فيجب عليه الحصول على أي موافقات رسمية لاستئجار العقار أو تملكه وفق أحكام التشريعات النافذة المفعول.","للمستأجر الحق في تأجير المأجور من الباطن ويعتبر المؤجر من الباطن والمستأجر من الباطن بمثابة مؤجر ومستأجر وفق أحكام هذا القانون ويتمتعان بحقوق أطراف عقد التأجير ويتحملان التزاماتهم.","يحق للمستأجر تملك المأجور مقابل تسديد كامل ما تبقى من بدل الإيجار قبل انتهاء عقد التأجير."],"answer":2,"orig_answer":null,"law":"leasing","article":"9","status":"valid","explanation":"المادة (9/أ): التأجير من الباطن يتطلب موافقة خطية من المؤجر، والعبارة أغفلت هذا الشرط."},{"num":48,"type":"mcq","q":"إحدى العبارات التالية غير صحيحة بموجب قانون رسوم الطوابع والواردات لسنة 2001:","o":["يعتبر تجديد أي معاملة واردة في جدول المعاملات الخاضعة للرسوم الملحق بالقانون أو تمديدها بمثابة معاملة جديدة تخضع للرسوم المنصوص عليها في هذا الجدول.","تفرض غرامة على المكلف بدفع الرسم المقرر إذا تأخر عن دفعه في الموعد المحدد بواقع مثل الرسم المستحق أو مقدار النقص فيه إذا كان التأخير لمدة تزيد على ثلاثين يوماً ولا تتجاوز ستين يوماً وبحد أدنى مقداره دينار واحد.","تفرض على الموظف الذي لم يبطل الطوابع على المعاملة بالصورة التي حددها القانون غرامة تعادل مثلا مقدار الرسم المقرر وبحد أدنى مقداره دينار واحد.","إذا تداخلت أكثر من معاملة خاضعة للرسم في معاملة واحدة فيستوفى عن كل منها الرسم المقرر باعتبارها معاملة مستقلة."],"answer":2,"orig_answer":null,"law":"stamp","article":"12","status":"valid","explanation":"المادة (12/ب/2): غرامة الموظف الذي لم يبطل الطوابع «مثل» الرسم لا مثلاه."},{"num":49,"type":"mcq","q":"أي من العبارات التالية تعتبر غير صحيحة بموجب قانون ديوان المحاسبة رقم 28 لسنة 1952 وتعديلاته:","o":["على أي جهة من الجهات الخاضعة لرقابة ديوان المحاسبة الإجابة على أي استيضاح يوجهه إليها الديوان ضمن نطاق مهامه وذلك خلال مدة لا تتجاوز ستين يوماً اعتباراً من تاريخ وصوله إلى تلك الجهة.","إذا وقع خلاف بالرأي بين الديوان وإحدى الوزارات أو الدوائر يعرض موضوع الخلاف على مجلس الوزراء للفصل فيه.","يتولى ديوان المحاسبة التدقيق اللاحق على النفقات إلا أنه يجوز لرئيس ديوان المحاسبة في حالات خاصة أن يقرر التدقيق في النفقات قبل الصرف.","على وزارة المالية أن تقدم لديوان المحاسبة الحساب الختامي عن كل سنة مالية خلال مدة لا تزيد على ستة أشهر من تاريخ انتهاء تلك السنة."],"answer":0,"orig_answer":null,"law":"audit","article":"16","status":"valid","explanation":"المادة (16): مدة الإجابة على الاستيضاح 30 يوماً داخل المملكة و60 يوماً خارجها. (وتشترط المادة 25 موافقة رئيس الوزراء للتدقيق قبل الصرف)."},{"num":50,"type":"mcq","q":"أي من العبارات تعتبر غير صحيحة وفقاً لقانون المنافسة لسنة 2004 وتعديلاته.","o":["تشكل لجنة شؤون المنافسة برئاسة وزير الصناعة والتجارة والتموين تجتمع بدعوة من رئيسها أو نائبه عند غيابه مرة واحدة شهرياً ويكون اجتماعها قانونياً بحضور ما لا يقل عن ثلثي أعضائها على أن يكون من بينهم الرئيس أو نائبه.","يحظر على أي مؤسسة لها وضع مهيمن في السوق إذا تجاوزت حصتها السوقية (40%) أو جزء هام منه إساءة استغلال هذا الوضع التمييز بين العملاء في العقود المتشابهة بالنسبة لأسعار السلع والخدمات أو شروط بيعها وشرائها.","يختص للنظر في قضايا الممارسات المخلة بالمنافسة ضمن محكمة البداية قاضٍ أو أكثر من ذوي الاختصاص ممن تلقوا تدريباً خاصاً على أن يتم تعيينهم بقرار من المجلس القضائي.","تحدد أسعار السلع والخدمات وفقاً لقواعد السوق ومبادئ المنافسة الحرة باستثناء أسعار الخدمات التي يتم تحديدها وفقاً لأحكام قانون الصناعة والتجارة والتموين أو أي قانون آخر."],"answer":0,"orig_answer":null,"law":"competition","article":"15","status":"valid","explanation":"المادة (15/أ): تجتمع اللجنة مرة كل ستة أشهر على الأقل لا شهرياً. (نسبة 40% في الخيار ب غير واردة في المادة 6 أيضاً)."},{"num":51,"type":"mcq","q":"أي من العبارات التالية لا تعتبر صحيحة بموجب قانون مكافحة غسل الأموال وتمويل الإرهاب رقم (20) لسنة 2021:","o":["تمارس النيابة العامة أو المحكمة المختصة اختصاصاتها في الجرائم المنصوص عليها في هذا القانون وفق أصول المحاكمات الجزائية ولها حجز ممتلكات اختلطت فيها المتحصلات مع أموال من مصادر مشروعة إلى أن تحدد قيمة المتحصلات غير المشروعة ونواتج استغلالها.","لغايات هذا القانون تشمل متحصلات الجريمة أي متحصلات ناجمة عن أي فعل يعتبر جريمة بمقتضى اتفاقيات دولية.","يعد مرتكباً لجريمة الإرهاب كل شخص يقوم بتمويل سفر الأشخاص إلى دول غير دول إقاماتهم لغايات التخطيط لارتكاب الأعمال الإرهابية حتى لو [لم] يقع العمل الإرهابي.","تنتفي المسؤولية الجزائية عن كل شخص طبيعي أو معنوي عند قيامه بحسن نية بواجب الإخطار عن أي من العمليات التي يشتبه بأنها مرتبطة بجريمة غسل الأموال أو بتمويل الإرهاب."],"answer":1,"orig_answer":null,"law":"aml","article":"3","status":"valid","explanation":"المادة (3/ج/2): يشترط أن تكون الاتفاقية الدولية قد صادقت عليها المملكة وأن يكون الفعل معاقباً عليه في القانون الأردني."},{"num":52,"type":"mcq","q":"أي من العبارات التالية لا تعتبر صحيحة بموجب قانون النزاهة ومكافحة الفساد رقم (13) لسنة 2016:","o":["على الرغم مما ورد في أي تشريع آخر تلتزم الهيئة بإصدار قراراتها في موعد لا يتجاوز ثلاثة شهر من تاريخ بدء إجراءات التحقيق والتحري في الشكوى وللمجلس إذا اقتضت الضرورة تمديد ذلك الموعد لمدة إضافية مماثلة.","لمرتكب أي من جرائم الفساد المنصوص عليها في هذا القانون بطلب للهيئة لإجراء مصالحة معه إذا أعاد كلياً الأموال والمنافع المرتبطة بها التي حصل عليها نتيجة ارتكاب جريمة فساد أو أجرى تسوية عليها.","لمجلس الوزراء بناء على تنسيب مجلس الهيئة إنهاء خدمة أي عضو من أعضائه خلال مدة المجلس إذا تغيب عن اجتماعات المجلس ثلاث جلسات متتالية أو ست جلسات متفرقة خلال السنة الواحدة دون عذر يقبله المجلس.","تمارس الهيئة مهامها وأعمالها بحرية واستقلال دون تأثير أو تدخل من أي جهة فلا يجوز تفتيش مقر هيئة النزاهة ومكافحة الفساد إلا بأمر قضائي وبحضور المدعي العام المختص على أن يتم تبليغ رئيس المجلس بذلك ودعوة من يمثل الهيئة لحضور التفتيش."],"answer":0,"orig_answer":null,"law":"integrity","article":"21","status":"valid","explanation":"المادة (21): مدة إصدار القرارات ستة أشهر لا ثلاثة."},{"num":53,"type":"mcq","q":"الجهة الوحيدة المخول لها تسجيل ملكية الأوراق المالية هي:","o":["دائرة مراقبة الشركات.","بورصة عمان.","مركز إيداع الأوراق المالية.","هيئة الأوراق المالية."],"answer":2,"orig_answer":null,"law":"securities","article":"75","status":"valid","explanation":"المادة (75): مركز إيداع الأوراق المالية هو الجهة الوحيدة المخولة بالتسجيل والحفظ ونقل الملكية."},{"num":54,"type":"mcq","q":"يتم تأسيس صناديق الاستثمار المشترك من قبل:","o":["شركة الاستثمار المشترك.","مدير الاستثمار.","أمين الاستثمار.","مدير الإصدار."],"answer":1,"orig_answer":null,"law":"securities","article":"92","status":"valid","explanation":"المادة (92/أ): تنشأ الصناديق من قبل الشركات المرخصة لممارسة أعمال إدارة الاستثمار (مدير الاستثمار)."},{"num":55,"type":"mcq","q":"على المصدر تزويد الهيئة بالتقرير السنوي خلال:","o":["90 يوم من نهاية السنة المالية.","30 يوم من نهاية السنة المالية.","60 يوم من نهاية السنة المالية.","45 يوم من نهاية السنة المالية."],"answer":0,"orig_answer":null,"law":"securities","article":"43","status":"valid","explanation":"المادة (43/أ/1): التقرير السنوي خلال تسعين يوماً من انتهاء السنة المالية."},{"num":56,"type":"mcq","q":"يكون الحق بالأسهم المجانية:","o":["بتاريخ قرار وزير الصناعة والتجارة بالموافقة على قرار الهيئة العامة المتعلق بزيادة رأس المال عن طريق الأسهم المجانية.","بتاريخ اجتماع الهيئة العامة التي تقرر فيه زيادة رأس المال عن طريق توزيع الأسهم المجانية.","بتاريخ قرار مجلس مفوضي الهيئة بالموافقة على تسجيل الأسهم.","للمساهمين كما هم بنهاية اليوم الخامس عشر من تاريخ موافقة مجلس مفوضي الهيئة على تسجيل الأسهم."],"answer":3,"orig_answer":null,"law":"securities","article":"","status":"unverified","explanation":"تحدد التعليمات (لا القانون) تاريخ الاستحقاق في الأسهم المجانية؛ الإجابة وفق العرف التطبيقي."},{"num":57,"type":"mcq","q":"يتطلب إعداد نشرة إصدار لعرض الأوراق المالية إذا كان عرض الأوراق المالية موجه لـ:","o":["لجميع مساهمي الشركة.","(200) شخص فأكثر.","أكثر من (30) شخص.","(100) شخص فأكثر."],"answer":2,"orig_answer":null,"law":"securities","article":"2","status":"valid","explanation":"المادة (2): العرض العام عرض لأكثر من ثلاثين شخصاً، ويتطلب نشرة إصدار (المادة 34)."},{"num":58,"type":"mcq","q":"على الشركة المصدرة إعلام الهيئة عند توافر أي معلومة جوهرية:","o":["خلال (10) أيام عمل من تاريخ حدوثها.","قبل تداول يوم العمل التالي لتاريخ حدوثها.","خلال أسبوع من تاريخ حدوثها.","خلال (3) أيام عمل من تاريخ حدوثها."],"answer":1,"orig_answer":null,"law":"securities","article":"43","status":"unverified","explanation":"المادة (43/د) توجب الإفصاح «فور العلم»؛ تحديد ما قبل تداول يوم العمل التالي وارد في تعليمات الإفصاح."},{"num":59,"type":"mcq","q":"يقصد بعرض التملك العام:","o":["العرض المقدم من المؤسسات الرسمية العامة لتملك جميع أسهم مساهمي الشركة.","عرض تملك أو مبادلة (40%) فأكثر من الأوراق المالية للمصدر.","عرض تملك جميع أسهم مساهمي الشركة.","عرض الأوراق المالية للجمهور عن طريق العرض العام."],"answer":1,"orig_answer":null,"law":"securities","article":"45","status":"valid","explanation":"المادة (45/أ): عرض التملك العام لشراء أو مبادلة 40% فأكثر من الأوراق المالية للمصدر."},{"num":60,"type":"mcq","q":"يقرر المرجع الطبي حاجة المصاب مجدداً للعلاج واستحقاقه للبدل اليومي إذا حصلت الانتكاسة و/أو مضاعفات خلال:","o":["سنتان من تاريخ وقوع الإصابة.","ستة أشهر من تاريخ استقرار الحالة.","سنة من تاريخ استقرار الحالة.","لا شيء مما ذكر."],"answer":2,"orig_answer":null,"law":"social","article":"28","status":"valid","explanation":"المادة (28/ج): خلال سنة من تاريخ استقرار الحالة."},{"num":61,"type":"mcq","q":"من شروط انتفاع المؤمن عليها من تأمين الأمومة أن تكون مشمولة بأحكام هذا التأمين خلال:","o":["اثني عشر شهراً تسبق استحقاقها لإجازة الأمومة.","ستة أشهر متصلة أو متقطعة في تأمين الأمومة في الاثني عشر شهراً التي تسبق استحقاقها لإجازة الأمومة.","الستة أشهر الأخيرة التي تسبق استحقاقها لإجازة الأمومة.","ب+ج."],"answer":2,"orig_answer":null,"law":"social","article":"44","status":"valid","explanation":"المادة (44/أ) بعد تعديل 2019: مشمولة خلال الأشهر الستة الأخيرة التي تسبق استحقاق إجازة الأمومة."},{"num":62,"type":"mcq","q":"يجوز للمؤمن عليه أن يتقدم بطلب لفحصه وهو على رأس عمله لبيان ما إذا كان ينطبق عليه مفهوم العجز الكلي الطبيعي الدائم إذا كان لديه:","o":["60 اشتراكاً منها 24 اشتراكاً متصلاً.","اشتراكاً منها 12 اشتراكاً متصلاً.","60 اشتراكاً.","لا شيء مما ذكر."],"answer":0,"orig_answer":null,"law":"social","article":"67","status":"valid","explanation":"المادة (67/ز): من يزيد عدد اشتراكاته على 60 اشتراكاً منها 24 متصلاً."},{"num":63,"type":"mcq","q":"يتم ربط راتب التقاعد وراتب الاعتلال بـ:","o":["معدل النمو السنوي أو التضخم أيهما أقل.","التضخم.","معدل النمو السنوي والتضخم معاً.","معدل النمو السنوي فقط."],"answer":0,"orig_answer":null,"law":"social","article":"90","status":"valid","explanation":"المادة (90/ب): بالتضخم أو بمعدل النمو السنوي لمتوسط الأجور أيهما أقل."},{"num":64,"type":"mcq","q":"إذا تأخرت المنشأة عن تزويد المؤسسة بالبيانات بأسماء العاملين لديها الذين انتهت خدماتهم لديها تلتزم بدفع غرامة قدرها:","o":["5% من الاشتراكات المستحقة.","30% من الاشتراكات المستحقة.","9% من الاشتراكات المستحقة.","1% من الاشتراكات المستحقة."],"answer":3,"orig_answer":null,"law":"social","article":"22","status":"valid","explanation":"المادة (22/ب): غرامة 1% من الاشتراكات المستحقة عن كل شهر تأخير."},{"num":65,"type":"mcq","q":"إذا نشأ عن إصابة العمل عجز جزئي دائم بنسبة لا تقل عن 30% فيستحق المصاب:","o":["تعويض دفعة واحدة أو راتب اعتلال حسب طلب المصاب.","راتب اعتلال شهري.","تعويض الدفعة الواحدة.","لا شيء مما ذكر."],"answer":1,"orig_answer":null,"law":"social","article":"30","status":"valid","explanation":"المادة (30/ج): يستحق راتب اعتلال شهري بنسبة العجز."},{"num":66,"type":"mcq","q":"في حال ترك صاحب راتب التقاعد المبكر العمل تضاف مدة اشتراكه السابقة إلى اللاحقة:","o":["لا تضاف المدة أبداً ويصرف عنها تعويض الدفعة الواحدة.","عند إكماله سن الستين للذكر أو للخامسة والخمسين للأنثى.","بعد تركه للعمل مباشرة.","أ + ج."],"answer":1,"orig_answer":null,"law":"social","article":"85","status":"valid","explanation":"المادة (85/د/1/ز): لا تضاف المدة اللاحقة إلا عند إكمال سن 60 للذكر أو 55 للأنثى أو الوفاة."},{"num":67,"type":"mcq","q":"يتولى إدارة شؤون البنك المركزي الأردني العامة:","o":["مجلس إدارة مكون من محافظ ونواب اثنين وخمسة أعضاء.","مجلس إدارة مكون من محافظ ونواب اثنين وستة أعضاء.","مجلس إدارة مكون من محافظ ونواب اثنين وسبعة أعضاء.","لا شيء مما ذكر."],"answer":0,"orig_answer":null,"law":"other:قانون البنك المركزي الأردني رقم (23) لسنة 1971","article":"","status":"unverified","explanation":"قانون البنك المركزي غير متوفر في قاعدة النصوص؛ الإجابة تقديرية."},{"num":68,"type":"mcq","q":"تعتبر الموافقة على ترخيص المؤسسات المالية وسحب ترخيصها من صلاحيات:","o":["مجلس الوزراء بناء على تنسيب مجلس إدارة البنك المركزي.","مجلس إدارة البنك المركزي الأردني.","جمعية البنوك الأردنية.","محافظ البنك المركزي."],"answer":1,"orig_answer":null,"law":"other:قانون البنك المركزي الأردني رقم (23) لسنة 1971","article":"","status":"unverified","explanation":"قانون البنك المركزي غير متوفر؛ الترخيص وسحبه من صلاحيات مجلس الإدارة (تقديري)."},{"num":69,"type":"mcq","q":"ينطبق تعريف الأوراق المالية الحكومية الوارد في قانون البنك المركزي الأردني رقم (23) لسنة 1971 وتعديلاته على كل مما يلي باستثناء:","o":["الأوراق المالية المكفولة من الحكومة.","الأوراق المالية المصدرة من المؤسسات الرسمية العامة.","الأوراق المالية المصدرة من شركات الخدمات المالية.","الأوراق المالية المصدرة من الحكومة."],"answer":2,"orig_answer":null,"law":"other:قانون البنك المركزي الأردني رقم (23) لسنة 1971","article":"","status":"unverified","explanation":"قانون البنك المركزي غير متوفر؛ تعريف الأوراق المالية الحكومية لا يشمل أوراق شركات الخدمات المالية."},{"num":70,"type":"mcq","q":"الدائرة المسؤولة عن ضبط النقد والأدوات القابلة للتداول لحاملها التي يتم الاشتباه بارتباطها بغسل الأموال أو أي من الجرائم الأصلية المرتبطة بها أو تمويل الإرهاب هي:","o":["دائرة الجمارك.","دائرة التنفيذ القضائي.","وحدة مكافحة غسل الأموال وتمويل الإرهاب.","دائرة المخابرات العامة."],"answer":0,"orig_answer":null,"law":"aml","article":"24","status":"valid","explanation":"المادة (24/أ): على دائرة الجمارك ضبط النقد والأدوات القابلة للتداول لحاملها عند الاشتباه."},{"num":71,"type":"essay","q":"البيانات التالية تخص شركة تجارية للعام 2019: قرض ممنوح من طرف ذو علاقة بقيمة 120,000 دينار، بلغ رأسمال الشركة 10,000 دينار، بلغ متوسط حقوق الملكية 20,000 دينار، بلغت الفوائد المطالب بها من قبل الشركة بواقع 15,000 دينار. المطلوب: احتساب قيمة الفوائد المقبولة ضريبياً.","law":"income","article":"6","status":"valid","model_answer":"• المادة (6/ب/2): تقبل فوائد الأطراف ذوي العلاقة بنسبة 3:1 للدين إلى رأس المال المدفوع أو متوسط حقوق الملكية أيهما أكبر.\n• الأكبر = 20,000 ⇒ الدين المسموح = 60,000.\n• الفوائد المقبولة = 15,000 × 60,000 ÷ 120,000 = 7,500 دينار، ولا يجوز تدوير الزيادة (7,500)."},{"num":72,"type":"essay","q":"قام شخص باستيراد سيارة بلغت قيمتها 10,000 دينار وقيمتها التخمينية 12,000 دينار وضريبة خاصة 2,500 دينار وجمارك بنسبة 30% ورسوم ترخيص 250 دينار. المطلوب: احتساب قيمة ضريبة المبيعات.","law":"sales","article":"15","status":"valid","model_answer":"• المادة (15/ج): الأساس هو القيمة المعتمدة للرسوم الجمركية (التخمينية 12,000) مضافاً إليها الرسوم والضرائب المستحقة قبل التخليص بما فيها الضريبة الخاصة.\n• الجمارك 30%×12,000 = 3,600.\n• الأساس = 12,000 + 3,600 + 2,500 = 18,100 (رسوم الترخيص لاحقة للتخليص ولا تدخل).\n• الضريبة العامة = 18,100 × 16% = 2,896 دينار."},{"num":73,"type":"essay","q":"البيانات التالية مستخرجة من سجلات الشركة الأردنية للأعلاف والدواجن عن الفترة 5+6/2022 تحليل مبيعات الشركة خلال الفترة الضريبية: بيض المائدة 1% مبيعات 1,000,000 دينار؛ صوص لاحم صفر 3,000,000؛ أعلاف 5% 1,500,000؛ أدوية بيطرية 16% 800,000؛ مبيعات أعلاف إلى جهات معفاة صفر 600,000. إذا علمت أن استيراد الشركة مؤجل توريد ضريبة المبيعات على الاستيراد حيث بلغ إجمالي المستوردات خلال الفترة الضريبية 20,000,000 دينار أردني وأن هامش الربح للأعلاف 10% وبلغت إجمالي ضريبة المصاريف المشتركة 100,000 دينار، ولا يوجد مشتريات محلية خلال الفترة الضريبية. المطلوب: احتساب قيمة ضريبة المبيعات واجبة الدفع خلال الفترة الضريبية 5+6/2022.","law":"sales","article":"26","status":"valid","model_answer":"• ضريبة المخرجات: بيض 10,000 + أعلاف 75,000 + أدوية بيطرية 128,000 + صوص وأعلاف لجهات معفاة صفر = 213,000 دينار.\n• الضريبة المؤجلة على الاستيراد (المادة 26/د) تستحق عند تحقق واقعة البيع بقدر كلفة الكميات المباعة: كلفة الأعلاف المباعة = (1,500,000+600,000)÷1.1 = 1,909,091 تُدفع ضريبتها المؤجلة وتُخصم في الوقت ذاته كمدخلات.\n• ضريبة المصاريف المشتركة 100,000 قابلة للخصم كاملة لأن جميع المبيعات خاضعة (بما فيها نسبة الصفر) (المادة 19 وما بعدها).\n• الواجب الدفع (بعد تقاص المؤجل) ≈ 213,000 − 100,000 = 113,000 دينار. (حل مقترح؛ تفاصيل التأجيل في التعليمات)"},{"num":74,"type":"essay","q":"أردني أعزب يعمل موظفاً لدى بنك الكويت الوطني في الكويت بلغت رواتبه من البنك خلال 12 شهراً لعام 36,000 دينار، يتقاضى راتباً تقاعدياً من الضمان الاجتماعي بواقع 3,500 دينار، قدم خدمات استشارات لشركة في الأردن بقيمة 10,000 دينار وقامت الشركة باقتطاع مبلغ 1,000 دينار تحت حساب الضريبة وتحويل مبلغ 9,000 دينار له بموجب حوالة بنكية. - يملك عقاراً في الأردن مؤجراً بقيمة 50,000 دينار، بلغت مصاريف الصيانة للعقار المقبولة 10,000 دينار، بلغت قيمة مصاريف المجاري المدفوعة 1,920 دينار والمسقفات المدفوعة 9,600 دينار. المطلوب: احتساب قيمة الضريبة المستحقة.","law":"income","article":"3","status":"valid","model_answer":"• رواتب الكويت غير خاضعة لأنها لم تتأت في المملكة (المادة 3/أ).\n• الراتب التقاعدي معفى (المادة 4: أول 2,500 دينار شهرياً).\n• الدخل: استشارات 10,000 + إيجار صافٍ (50,000−10,000) = 40,000 ⇒ 50,000.\n• الإعفاء الشخصي 9,000 (المادة 9) ⇒ خاضع 41,000؛ الضريبة (المادة 11): 2,500 + 21,000×25% = 7,750.\n• تقاص المسقفات (المادة 18/ب) بحد ضريبة دخل الإيجار: 7,750×40,000/50,000 = 6,200 (أقل من 9,600).\n• الضريبة 1,550 − المقتطع 1,000 (دفعة على الحساب، المادة 12/ج) = 550 دينار. (المجاري قد تُعامل كمصروف إيجار فتنخفض النتيجة قليلاً)"},{"num":75,"type":"essay","q":"استوردت شركة القمر ذ.م.م خدمة من الخارج بتاريخ 2022/3/1 بموجب فاتورة بذلك التاريخ بلغت قيمة الخدمة الموردة للشركة بما يعادل 10,000 دينار. بتاريخ 2022/6/1 قامت شركة القمر بتحويل مبلغ 5,000 دينار للشركة الموردة للخدمة بموجب حوالة بنكية. بتاريخ 2022/7/1 قامت الشركة بتحويل مبلغ 5,000 دينار الرصيد المستحق عن الخدمة المستوردة. بتاريخ 2022/12/1 قامت الشركة بدفع ضريبة المبيعات عن الخدمة المستوردة البالغ 1,600 دينار. المطلوب: احتساب الغرامات المستحقة عند دفع الضريبة.","law":"sales","article":"26","status":"valid","model_answer":"• المادة (26/ج): تدفع الضريبة خلال شهر من دفع كل جزء: 800 تستحق في 2022/7/1، و800 في 2022/8/1.\n• غرامة التأخير 4 بالألف أسبوعياً (المادة 51): 800×0.004×22 أسبوعاً = 70.4؛ 800×0.004×18 أسبوعاً = 57.6 ⇒ 128 دينار.\n• التأخير تجاوز ثلاثة أشهر لكلا الجزأين ⇒ تهرب (المادة 30/ل): تعويض مدني من مثلي إلى ثلاثة أمثال الضريبة (3,200–4,800) وغرامة جزائية 200–1,000 دينار (المادة 31)، ويجوز التصالح (المادة 32)."},{"num":76,"type":"essay","q":"اذكر القرارات الواجب اتخاذها في الاجتماع التأسيسي للشركة المساهمة الخاصة.","law":"companies","article":"71 مكرر","status":"valid","model_answer":"• المادة (71 مكرر) خلال شهر من صدور شهادة التسجيل:\n• انتخاب مجلس الإدارة الأول.\n• اتخاذ القرار بشأن مصاريف التأسيس وأي التزامات تمت من المؤسسين قبل التأسيس.\n• انتخاب مدقق حسابات وتحديد أتعابه أو تفويض المجلس بتحديدها."},{"num":77,"type":"essay","q":"تنظم الأمور المالية والمحاسبية والإدارية للشركة المساهمة العامة بموجب أنظمة داخلية خاصة يعدها مجلس إدارة الشركة؛ بين ما هي الأمور الواجب تحديدها بصورة مفصلة في هذه الأنظمة؟","law":"companies","article":"151","status":"valid","model_answer":"• المادة (151/ب) بعد تعديل 2023: تحدد بصورة مفصلة واجبات مجلس الإدارة وصلاحياته ومسؤولياته وعلاقته بالإدارة التنفيذية.\n• وتبين اللجان الواجب تأليفها بما يتماشى ودليل قواعد الحوكمة.\n• تحتفظ الشركة بنسخة منها وتزود المراقب بها عند طلبه (151/ج)."},{"num":78,"type":"essay","q":"بين ما يحظر ولا يجوز لمدقق الحسابات القيام به تجاه الشركات المساهمة العامة.","law":"companies","article":"197","status":"valid","model_answer":"• المادة (197) تحت طائلة البطلان، لا يجوز للمدقق:\n• الاشتراك في تأسيس الشركة التي يدقق حساباتها.\n• أن يكون عضواً في مجلس إدارتها.\n• الاشتغال بصفة دائمة في أي عمل فني أو إداري أو استشاري فيها.\n• أن يكون شريكاً لأي عضو من أعضاء مجلس إدارتها أو موظفاً لديه."},{"num":79,"type":"essay","q":"اذكر ما يترتب على الشخص المفوض بإدارة شركة التضامن أن يقدم للشركاء فيها خلال مدة لا تزيد عن ثلاثة أشهر من انتهاء عمله في إدارة الشركة.","law":"companies","article":"19","status":"valid","model_answer":"• المادة (19/أ) سواء طلبوا ذلك أم لا:\n• حساباً عن كل منفعة نقدية أو عينية أو حقوق حصل عليها من أي عمل يتعلق بالشركة واحتفظ بها لنفسه (بما فيها استغلال اسمها أو علاماتها أو شهرتها) وردها وضمان الضرر.\n• حساباً عن أي أموال أو موجودات للشركة وضعها تحت حيازته أو استعملها لمنفعته وإعادتها وضمان التلف والتعويض عن العطل والضرر وما فات من ربح.\n• لا يسري عليها سقوط المسؤولية (19/ب)."},{"num":80,"type":"essay","q":"إذا تقدم أكثر من شريك في الشركة ذات المسؤولية المحدودة لشراء الحصة أو الحصص المراد التنازل عنها بالسعر المعروض، في حالة الاختلاف على السعر بين الإجراء القانوني الذي يقوم به مراقب عام الشركات.","law":"companies","article":"73","status":"valid","model_answer":"• المادة (73/ب): تقسم الحصص بين الراغبين كل بنسبة حصته في رأس المال.\n• عند الاختلاف على السعر يعين المراقب مدقق حسابات قانونياً على نفقة البائع والمشتري لتحديد السعر ويعتبر تقديره نهائياً.\n• من لا يلتزم بإتمام البيع بعد التقرير يتحمل النفقات تجاه الشركة."},{"num":81,"type":"essay","q":"حسب المادة (290) من أحكام قانون التجارة رقم 12 لسنة 1966 يحق لكل تاجر قبل توقفه عن الوفاء أو خلال الأيام العشرة التي تلي هذا التوقف أن يتقدم إلى المحكمة البدائية في المنطقة التي يكون فيها مركزه الرئيسي ويطلب إليها أن تدعو دائنيه ليعرض عليهم صلحاً واقياً من الإفلاس على أن يقدم ويوضح عدة أمور، اذكر اثنين منها.","law":"other:قانون التجارة رقم (12) لسنة 1966","article":"290","status":"unverified","model_answer":"• (قانون التجارة 1966 غير متوفر في قاعدة النصوص) من المتطلبات المعروفة:\n• بيان أسباب توقفه عن الدفع وعرض الصلح المقترح والضمانات.\n• تقديم الدفاتر التجارية وبيان تفصيلي بأمواله المنقولة وغير المنقولة وقيمتها، وقائمة بأسماء الدائنين والمدينين وعناوينهم ومقدار حقوقهم."},{"num":82,"type":"essay","q":"حسب المادة (386) من أحكام قانون التجارة رقم 12 لسنة 1966 لا يجوز للدائنين الحاضرين في اجتماع هيئة المصالحة أن يقبلوا عقد الصلح بعد التفليسة ما لم تتوفر شرطين اذكرهما.","law":"other:قانون التجارة رقم (12) لسنة 1966","article":"386","status":"unverified","model_answer":"• (قانون التجارة 1966 غير متوفر) الشرطان المعروفان للصلح القضائي:\n• موافقة أكثرية الدائنين عدداً.\n• أن يمثلوا ثلثي الديون المحققة أو المقبولة مؤقتاً (أي أكثرية مزدوجة)."},{"num":83,"type":"essay","q":"تتولى الهيئة العليا لتنظيم مهنة المحاسبة القانونية المهام والصلاحيات المنصوص عليها بالمادة 5 من القانون، اذكر أربعاً منها.","law":"accounting","article":"5","status":"valid","model_answer":"• المادة (5): اعتماد معايير المحاسبة والتدقيق بتنسيب من المجلس.\n• تشكيل لجنة ترخيص المهنة ووضع تعليماتها وكيفية إجراء الامتحانات.\n• المصادقة على منح إجازة المزاولة بتنسيب لجنة الترخيص وإلغائها بتنسيب المجلس.\n• النظر في الاعتراضات على قرارات المجلس.\n• تشكيل اللجان، إصدار التعليمات، إعداد مشروعات التشريعات، اعتماد المعاهد المهنية."},{"num":84,"type":"essay","q":"متى يتولى وكيل الإعسار إدارة أعمال الإعسار؟","law":"insolvency","article":"17","status":"valid","model_answer":"• المادة (17): إذا قُدم طلب الإشهار من المدين يحتفظ المدين بإدارة أعماله المعتادة تحت إشراف وكيل الإعسار.\n• إذا قُدم من الدائنين أو المراقب تعلق صلاحيات المدين ويمارسها وكيل الإعسار في حدود تسيير الأعمال المعتادة."},{"num":85,"type":"essay","q":"لأي رقابة يخضع وكيل الإعسار؟","law":"insolvency","article":"52","status":"valid","model_answer":"• المادة (52/أ): يخضع عمل وكيل الإعسار لإشراف المحكمة ورقابة الدائنين أو من يمثلهم (لجنة الدائنين).\n• وللمحكمة ولجنة الدائنين تكليفه بتقديم معلومات أو تقارير عن سير الإجراءات (52/ب)."},{"num":86,"type":"essay","q":"يحق للمؤمن له أو المستفيد من عقد التأمين الانتفاع من شرط الاختراق ولا يجوز لأي جهة الاعتراض على تفعيله، فما هو شرط الاختراق؟","law":"insurance","article":"71","status":"valid","model_answer":"• المادة (71/ب): الشرط الوارد في عقد إعادة التأمين الذي يقضي بمسؤولية معيد التأمين في حدود حصته من الخسارة المعاد تأمينها لديه تجاه المؤمن له والمستفيد مباشرة في الحالات التي يتعذر فيها على المؤمن الوفاء بالتزاماته."},{"num":87,"type":"essay","q":"حسب المادة (18) من قانون التأجير التمويلي يحق للمستأجر في حالة تصفية المؤجر خيارين، اذكرهما.","law":"leasing","article":"18","status":"valid","model_answer":"• المادة (18/أ): الاستمرار في تنفيذ عقد التأجير طبقاً لشروطه وأحكامه.\n• أو تسليم المأجور للمصفي والدخول مع باقي الدائنين في تحصيل ما دفعه للمؤجر بعد خصم أجر المثل.\n• ويلتزم المالك الجديد بالاستمرار بالعقد إذا رغب المستأجر (18/ب)."},{"num":88,"type":"essay","q":"ما هي الجهات التي تخضع لرقابة هيئة الأوراق المالية؟","law":"securities","article":"15","status":"valid","model_answer":"• المادة (15/أ): المصدرون.\n• المرخص لهم.\n• المعتمدون.\n• السوق المالي.\n• مركز إيداع الأوراق المالية.\n• صناديق الاستثمار المشترك وشركات الاستثمار.\n• (وكذلك صندوق حماية المستثمرين وصندوق ضمان التسوية وفق المادتين 33 و88)."},{"num":89,"type":"essay","q":"تحدث عن نسبة الاشتراكات الشهرية لمنشآت القطاع الخاص من حيث النسبة المقتطعة من المنشأة وعن المؤمن عليه؟","law":"social","article":"59","status":"valid","model_answer":"• الشيخوخة والعجز والوفاة (المادة 59): المنشأة 11%، المؤمن عليه 6.5% (بعد اكتمال الزيادات التدريجية).\n• إصابات العمل: المنشأة 2% (المادة 24).\n• الأمومة: المنشأة 0.75% (المادة 42).\n• التعطل عن العمل: المنشأة 0.5% والمؤمن عليه 1%.\n• المجموع: المنشأة 14.25% والمؤمن عليه 7.5% = 21.75% من الأجر."},{"num":90,"type":"essay","q":"تحدث عن شروط الجمع بين راتب التقاعد المبكر والأجر من أي عمل مشمول بأحكام القانون؟","law":"social","article":"85","status":"valid","model_answer":"• المادة (85/د/1) لصاحب التقاعد المبكر الأردني:\n• أن يكون قد انقطع عن العمل مدة لا تقل عن 24 شهراً من تاريخ استحقاق الراتب.\n• ألا يعود للعمل في أي منشأة عمل بها خلال آخر 36 اشتراكاً سابقة للاستحقاق.\n• ألا يعود من تقاعد مبكراً بسبب المهنة الخطرة (64/ج) للعمل في مهنة خطرة.\n• أن يعود للشمول بأحكام الضمان؛ ويصرف له نسبة من الراتب وفق الجدول (7).\n• غير الأردني لا يجوز له الجمع (85/د/2)."}]},{"id":"2022-12","year":2022,"month":12,"label":"دورة كانون الأول 2022","session":"كانون الأول","src":"c1054cc4.json","questions":[{"num":1,"type":"mcq","q":"موظف دخله السنوي من الرواتب للعام 2020 بواقع 21,400 دينار ولديه دخل سنوي من الايجارات بقيمة 12,000 دينار ومصاريف المجاري المدفوعة 300 دينار والمسقفات المدفوعة بقيمة 1,200 دينار وهو متزوج وزوجته تعمل براتب شهري قدره 1,000 دينار اذا علمت تم تقديم اقرار ضريبي مشترك، ولديهم 3 اولاد الاول يدرس في الجامعة قيمة القسط السنوي 2,000 دينار والثاني يدرس في مدرسة خاصة قسطها السنوي 1,500 دينار، إن الضريبة المستحقة:","o":["3,775 دينار.","2,575 دينار.","2,777 دينار.","لاشيء مما ذكر."],"answer":3,"orig_answer":null,"law":"income","article":"9","status":"valid","explanation":"المادة (9) والمادة (11): مجموع الدخل المشترك = رواتب 21,400 + راتب الزوجة 12,000 + صافي الإيجار (12,000 − 300 مجاري − 1,200 مسقفات = 10,500) = 43,900؛ الإعفاءات لسنة 2020: 9,000 شخصي + 9,000 معالين + 2,000 تعليم للولدين (1,000 لكل ولد) = 20,000؛ الخاضع 23,900 والضريبة 2,500 + (3,900×25%) = 3,475 دينار، فلا يطابق أياً من الخيارات (أ–ج)."},{"num":2,"type":"mcq","q":"وفقاً لقانون ضريبة الدخل فان العبارة التالية صحيحة لنسبة ضريبة والمساهمة الوطنية:","o":["شركات التاجير التمويلي تخضع لنسبة 24% و 4% مساهمة وطنية","شركات التامين تخضع لنسبة 24% ضريبة دخل و 4% مساهمة وطنية.","شركات الاتصالات تخضع لنسبة 24% و4% مساهمة وطنية.","جميع ماذكر غير صحيح."],"answer":0,"orig_answer":null,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ب/2) و(11/و): شركات التأجير التمويلي 24% ضريبة و4% مساهمة وطنية، أما التأمين والاتصالات فـ24% و2% مساهمة وطنية."},{"num":3,"type":"mcq","q":"شركة صناعة الكرتون المحدودة اعلنت في قائمة الدخل لسنة 2021 دخل صافي بقيمة 100000 دينار وعليه فان ضريبة الدخل المستحقة:","o":["19,000 دينار.","18,000 دينار.","17,000 دينار.","16,000 دينار."],"answer":2,"orig_answer":null,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ب/1) و(11/ج/1): نسبة الشخص الاعتباري 20% (20,000) تخفض للنشاط الصناعي لسنة 2021 بنسبة 15% فتصبح الضريبة 17,000 دينار (إضافة لمساهمة وطنية 1%)."},{"num":4,"type":"mcq","q":"شركة صناعة الادوية الاردنية في قائمة الدخل لسنة 2020 دخل صافي بقيمة 120000 دينار وعليه فان ضريبة الدخل المستحقة:","o":["24,000 دينار.","19,200 دينار.","18,000 دينار.","16,800 دينار."],"answer":3,"orig_answer":null,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ج/2): صناعة الأدوية لسنة 2020 تخفض ضريبتها 30%: 120,000×20% = 24,000 × 70% = 16,800 دينار."},{"num":5,"type":"mcq","q":"أحد العبارات التالية ليست صحيحة، ضريبة الدخل على أرباح المتاجرة بالأسهم عن كل عملية هي:","o":["8 بالعشرة الاف من الشخص الطبيعي والشخص غير المقيم .","8 بالعشرة الاف من الشخص الطبيعي والشخص غير المقيم وشركات التضامن.","8 بالعشرة الاف من الشخص الطبيعي وشركات التضامن.","8 بالعشرة الاف من الشخص الطبيعي عدا الشركات."],"answer":null,"orig_answer":null,"law":"other:نظام الضريبة على أرباح المتاجرة بالأسهم","article":"","status":"unverified","explanation":"تحكمها أنظمة/تعليمات الضريبة على أرباح المتاجرة بالأسهم الصادرة بمقتضى قانون ضريبة الدخل وليست نصاً في القانون؛ لم يتم التحقق من النص."},{"num":6,"type":"mcq","q":"وفق تعليمات إحتساب حوافز ضريبية للقطاع الصناعي وفقاً لإحكام المادة 81 من قانون ضريبة الدخل حسب المعادلة التالية: (الدخل الصافي للنشاط الصناعي المستهدف ÷ مجموع الارباح الصافية للمكلف من جميع الانشطة والمصادر الاخرى) X الدخل الخاضع للضريبة للمكلف من جميع الانشطة. وتسري هذه المعادلة على:","o":["للإنشطة الصناعية صناعة الادوية والملابس وفقاً للجدول الملحق بالتعليمات.","إذا كان من الانشطة الصناعية المستفيدة فعلياً من نظام تخفيض ضريبة الدخل في المناطق الاقل نمواً رقم (44) لسنة 2016.","إذا كان النشاط الصناعي مؤسسة مسجلة في المناطق التنموية.","جميع ما ذكر خطأ."],"answer":null,"orig_answer":null,"law":"other:تعليمات احتساب الحوافز الضريبية للقطاع الصناعي","article":"81","status":"unverified","explanation":"المادة (81) تجيز منح حوافز ضريبية لقطاعات محددة بنظام؛ أما المعادلة فوردت في تعليمات احتساب الحوافز للقطاع الصناعي ولم يتم التحقق من نصها."},{"num":7,"type":"mcq","q":"وفقاً لقانون الضريبة العامة على المبيعات إحدى العبارات التالية صحيحة:","o":["تطبق محكمة البداية الضريبية ومحكمة الاستئناف الضريبية قانون الضريبة العامة على المبيعات بما لا يتعارض مع اصول المحاكمات المدنية.","تطبق محكمة الاستئناف الضريبية الاصول المنصوص عليها في قانون أصول المحاكمات الجزائية بالقدر الذي لا يتعارض فيه مع احكام قانون الضريبة العامة على المبيعات.","تطبق محكمة البداية الضريبيه قانون الضريبة العامة على المبيعات بما لا يتعارض مع أصول المحاكمات المدنية.","جميع ما ذكر خطأ."],"answer":1,"orig_answer":null,"law":"sales","article":"59","status":"valid","explanation":"المادة (59): تطبق محكمة البداية الضريبية ومحكمة الاستئناف الضريبية أصول المحاكمات الجزائية وكذلك أصول المحاكمات المدنية بالقدر الذي لا يتعارض مع أحكام القانون، فالخيار (ب) هو الصحيح."},{"num":8,"type":"mcq","q":"في حال إسقاط القضية بسبب الغياب لدى المحكمة فإن الجهات الملزمة بتبليغ الاسقاط هي:","o":["قرارات قضايا الدخل ( محكمة الضريبة) وقرارات المبيعات (دائرة الضريبة).","قرارات الإسقاط لقضايا الدخل والمبيعات ( دائرة ضريبة الدخل).","قرارات الإسقاط لقضايا الدخل والمبيعات (محكمة الضريبة).","كل ما ذكر غير صحيح."],"answer":0,"orig_answer":null,"law":"income","article":"46","status":"valid","explanation":"في الدخل: المادة (46/ج) تبليغ المحكمة قرار الإسقاط للمكلف؛ وفي المبيعات: المادة (57/ط) من قانون الضريبة العامة على المبيعات تبليغ الدائرة للمكلف إشعاراً بقرار الإسقاط."},{"num":9,"type":"mcq","q":"البيانات التالية تخص شركة تجارية للعام 2019: قرض ممنوح من طرف ذو علاقة بقيمة 100,000 دينار، بلغ راسمال الشركة 10,000 دينار، بلغ متوسط حقوق الملكية 20,000 دينار، بلغت الفوائد المطالب بها من قبل الشركة بواقع 15,000 دينار. وعليه فأن قيمة الفوائد المقبوله ضريبياً بواقع:","o":["12,000 دينار.","3,750 دينار.","9,000 دينار.","3,000 دينار."],"answer":2,"orig_answer":null,"law":"income","article":"6","status":"valid","explanation":"المادة (6/ب/2): الفوائد لذوي العلاقة تقبل بنسبة 3:1 من رأس المال المدفوع أو متوسط حقوق الملكية أيهما أكبر: 3×20,000 = 60,000 ÷ 100,000 × 15,000 = 9,000 دينار."},{"num":10,"type":"mcq","q":"تنفيذاً لاحكام قانون الضريبة العامة على المبيعات، يُعتمد لإغراض تحديد مسميات الخدمات:","o":["التصنيفات الصادره بموجب التصنيف المحلي للمهن الصادر بموجب احكام قانون الشركات وفق التشريعات النافذة.","التصنيفات الدولية الصادرة عن الامانة العامة للامم المتحدة.","جداول التعرفة وشروحاتها النافذة وفق لقرارات مجلس الوزراء.","جداول التعرفة وشروحاتها النافذة وفق أحكام قانون الجمارك."],"answer":1,"orig_answer":null,"law":"sales","article":"5","status":"valid","explanation":"المادة (5/أ): مسميات السلع وفق جداول التعرفة وقانون الجمارك، أما مسميات الخدمات فتعتمد التصنيفات الدولية الصادرة عن الأمانة العامة للأمم المتحدة."},{"num":11,"type":"mcq","q":"يترتب ضريبة خاصة مقدارها .......... دينار على كل تذكرة سفر بالجو إلى خارج المملكة وعلى كل مسافر ضمن الرحلات العادية أو غير المنتظمه أو الاضافية أو العارضة أو الخاصة والتي تتضمن مقطع مغادرة في اي من مطارات المملكة:","o":["40 دينار.","30 دينار.","20 دينار.","10 دنانير."],"answer":0,"orig_answer":null,"law":"sales","article":"","status":"unverified","explanation":"الضريبة الخاصة على تذاكر السفر جواً مقررة في جداول الضريبة الخاصة/قرارات مجلس الوزراء وليست في نص القانون المتوفر؛ الإجابة الشائعة 40 ديناراً ولم يتم التحقق منها."},{"num":12,"type":"mcq","q":"حسب المادة 46 من قانون ضريبة الدخل اذا تم اسقاط الدعوى بسبب الغياب أو لإي سبب آخر ولم يتم تجديدها يعتبر القرار المطعون فيه قطعياً بعد مرور:","o":["ثلاثون يوماً من تاريخ تبليغ المحكمة قرار الاسقاط للمكلف أو وكيله وفي جميع الاحوال لا يجوز تجديد الدعوى المسقطة للسبب نفسه لاكثر من مرتين وبسبب مبرر.","ثلاثون يوماً من تاريخ إسقاط الدعوى وفي جميع الاحوال لا يجوز تجديد الدعوى المسقطة للسبب نفسه لاكثر من مرتين وبسبب مبرر.","ثلاثون يوماً من تاريخ تبليغ المحكمة قرار الاسقاط للمكلف أو وكيله وفي جميع الاحوال لا يجوز تجديد الدعوى المسقطة للسبب نفسه لاكثر من مرة وبسبب مبرر.","ثلاثون يوماً من تاريخ إسقاط الدعوى وفي جميع الاحوال لا يجوز تجديد الدعوى المسقطة للسبب نفسه لاكثر من مره وبسبب مبرر."],"answer":0,"orig_answer":null,"law":"income","article":"46","status":"valid","explanation":"المادة (46/ج): ثلاثون يوماً من تاريخ تبليغ المحكمة قرار الإسقاط للمكلف أو وكيله، ولا يجوز التجديد للسبب نفسه لأكثر من مرتين وبسبب مبرر."},{"num":13,"type":"mcq","q":"حسب المادة 49 من قانون ضريبة الدخل يستوفى عن الدعوى رسم بنسبة:","o":["3% من الفرق بين مقدار الضريبة أو المطالبة والمقدار الذي يسلم به المدعي من تلك الضريبة او المطالبة على ان لايقل الرسم عن ثلاثين دينار بما في ذلك حالة عدم وجود ضريبة او مطالبة لوقوع المدعي في خسارة وان لاتزيد على ثلاثماية دينار لكل فترة ضريبية عن جميع درجات التقاضي.","3% من الفرق بين مقدار الضريبة أو المطالبة والمقدار الذي يسلم به المدعي من تلك الضريبة او المطالبة على ان لايقل الرسم عن ثلاثين دينار بما في ذلك حالة عدم وجود ضريبة او مطالبة لوقوع المدعي في خسارة وان لاتزيد على ثلاثماية دينار لكل فترة ضريبية عن كل درجة من درجات التقاضي.","3% من الفرق بين مقدار الضريبة أو المطالبة والمقدار الذي يسلم به المدعي من تلك الضريبة او المطالبة على ان لايقل الرسم عن عشرين دينار بما في ذلك حالة عدم وجود ضريبة او مطالبة لوقوع المدعي في خسارة وان لاتزيد على مئتين دينار لكل فترة ضريبية عن كل درجة من درجات التقاضي.","3% من الفرق بين مقدار الضريبة أو المطالبة والمقدار الذي يسلم به المدعي من تلك الضريبة او المطالبة على ان لايقل الرسم عن عشرين دينار بما في ذلك حالة عدم وجود ضريبة او مطالبة لوقوع المدعي في خسارة وان لاتزيد مئتين دينار لكل فترة ضريبية عن جميع درجات التقاضي."],"answer":1,"orig_answer":null,"law":"income","article":"49","status":"valid","explanation":"المادة (49/أ): 3% من الفرق بحد أدنى ثلاثين ديناراً وحد أعلى ثلاثمائة دينار لكل فترة ضريبية عن كل درجة من درجات التقاضي."},{"num":14,"type":"mcq","q":"حسب المادة 67 من قانون ضريبة الدخل يتحمل المحاسب القانوني المسؤولية عن المصادقة على بيانات مالية غير مطابقة للواقع بشكل جوهري أو تخالف أحكام هذا القانون أو معايير المحاسبة الدولية والقوانين والانظمة سواء كان ذلك ناجم عن خطأ متعمد او عمل جرمي او عن اهمال جسيم يعتبر المحاسب القانوني مرتكب لجرم ويعاقب:","o":["غرامة تعويضية لا تقل عن مثلي فرق الضريبة ولا يزيد عن ثلاثة أمثالها وبغرامة جزائية لا تقل عن مئة دينار ولا تزيد عن خمسماية دينار.","غرامة تعويضية لا تقل عن مثلي فرق الضريبة ولا يزيد عن ثلاثة أمثالها وبغرامة جزائية لا تقل عن مئة دينار ولا تزيد عن مئتي دينار.","غرامة تعويضية لا تقل عن مثلي فرق الضريبة ولا يزيد عن ثلاثة أمثالها وبغرامة جزائية لا تقل عن مئتي دينار ولا تزيد عن خمسماية دينار.","بغرامة تعويضية تعادل مثل الفرق الضريبي."],"answer":3,"orig_answer":null,"law":"income","article":"67","status":"valid","explanation":"المادة (67/أ) تحيل إلى عقوبة المادة (66): غرامة تعويضية تعادل مثل الفرق الضريبي."},{"num":15,"type":"mcq","q":"أصدر المدقق قرار التدقيق الاولي وتم بموجبه فرض فرق ضريبي وغرامات مثلي وغرامات جزائية وغرامات المادة (28) وقام بإصدار اشعار مطالبة بالفرق الضريبي وتم الاعتراض على قرار التدقيق وصدر قرار هيئة الاعتراض برد الاعتراض وتم تبليغه للمكلف بموجب إشعار فإنه يحق للمكلف الاعتراض على الاشعار الصادر من هيئة الاعتراض لدى المحكمة على:","o":["غرامة المادة(28).","الغرامات الجزائية.","غرامة المثلي.","الفرق الضريبي."],"answer":3,"orig_answer":null,"law":"income","article":"42","status":"unverified","explanation":"المادة (42/أ) تجعل لمحكمة البداية الضريبية النظر في الطعن بقرار هيئة الاعتراض (الضريبة والغرامات المتعلقة بها)؛ لم يتم العثور على نص يحدد البند المقصود بدقة والإجابة المرجحة الفرق الضريبي."},{"num":16,"type":"mcq","q":"حسب قانون ضريبة الدخل رقم 38 لسنة 2018 وحسب المادة 72 فان العبارة التالية صحيحة:","o":["يجوز للمدير او الموظف المفوض منه او المدقق حسب مقتضى الحال وفي اي وقت ان يصحح بناء على طلب المكلف الاخطاء الكتابية والحسابية التي تقع في القرارات والاشعارات عن طريق السهو العرضي تكون اجراءات التصحيح خاضعة للطعن.","يجوز للمدير او الموظف المفوض منه او المدقق حسب مقتضى الحال وفي اي وقت ان يصحح من تلقاء ذاته الاخطاء الكتابية والحسابية التي تقع في القرارات والاشعارات عن طريق السهو العرضي و تكون اجراءات التصحيح خاضعة للطعن.","يجوز للمدير او الموظف المفوض منه او المدقق حسب مقتضى الحال وفي اي وقت ان يصحح من تلقاء ذاته او بناء على طلب المكلف الاخطاء الكتابية والحسابية التي تقع في القرارات والاشعارات عن طريق السهو العرضي ولا تكون اجراءات التصحيح خاضعة للطعن.","يجوز للمدير او الموظف المفوض منه او المدقق حسب مقتضى الحال وفي اي وقت ان يصحح من تلقاء ذاته او بناء على طلب المكلف الاخطاء الكتابية والحسابية التي تقع في القرارات والاشعارات عن طريق السهو العرضي وتكون اجراءات التصحيح خاضعة للطعن."],"answer":2,"orig_answer":null,"law":"income","article":"72","status":"valid","explanation":"المادة (72): التصحيح من تلقاء ذاته أو بناءً على طلب المكلف للأخطاء الكتابية والحسابية الناتجة عن السهو العرضي، ولا تكون إجراءات التصحيح خاضعة للطعن."},{"num":17,"type":"mcq","q":"قامت شركة بشراء اثاث بفواتير ضريبية بقيمة 5,000 دينار وضريبة مبيعات 800 دينار عند بداية عملها في 2022/1/1، بتاريخ 2022/4/1 قامت الشركة بالتسجيل في الشبكة العامة لضريبة المبيعات وارفقت كشوفات جرد المستودعات وجرد الموجودات الثابتة والضرائب المدفوعه، تستهلك الشركة موجوداتها الثابتة بنسبة 10% سنوياً، ان الضريبة واجبة التخصيم على الاصول:","o":["780 دينار.","720 دينار.","800 دينار.","لا يجوز تخصيم الضريبة على شراء الاصول كون تواريخ الشراء قبل التسجيل في ضريبة المبيعات."],"answer":0,"orig_answer":null,"law":"sales","article":"19","status":"valid","explanation":"المادة (19/د): يخصم المسجل الضريبة التي تحملها قبل التسجيل على السلع التي في حوزته عند التسجيل؛ وللأصول الثابتة تحتسب على صافي القيمة بعد الاستهلاك: 5,000 − (5,000×10%×3/12=125) = 4,875 × 16% = 780 ديناراً."},{"num":18,"type":"mcq","q":"قام شخص بإستيراد سيارة بلغت قيمتها 10,000 دينار وقيمتها التخمينية 12,000 دينار وضريبة خاصة 2,500 دينار وجمارك بنسبة 30% ورسوم ترخيص 250 دينار وعليه فان قيمة ضريبة المبيعات تكون:","o":["2,936 دينار.","2,080 دينار.","2,896 دينار.","2,176 دينار."],"answer":2,"orig_answer":null,"law":"sales","article":"15","status":"valid","explanation":"المادة (15/ج): الأساس هو القيمة الجمركية (12,000) + الرسوم الجمركية (3,600) + الضريبة الخاصة (2,500) = 18,100 × 16% = 2,896 ديناراً؛ ورسوم الترخيص لا تدخل لأنها ليست مستحقة قبل التخليص."},{"num":19,"type":"mcq","q":"قامت شركة بإستيراد خدمة بتاريخ 2022/1/1 وسجلت الخدمة بالمصاريف بتاريخ الفاتورة في 2022/1/1، قامت الشركة بدفع قيمة الفاتورة بتاريخ 2022/5/1، اذا علمت ان قيمة الخدمة 1,000 دينار وان الشركة قامت بدفع ضريبة المبيعات على الخدمة المستوردة بتاريخ 2022/6/12 فإن قيمة الضريبة والغرامات المستحقة هي:","o":["160 دينار+ 320 مثلي الضريبة +غرامة 12.60 دينار غرامة 4 بالالف +200- 1,000 دينار غرامة جزائية.","160 دينار+ غرامة 1.28 دينار غرامة 4 بالالف.","160 دينار+ غرامة 12.60 دينار غرامة 4 بالالف +100- 500 دينار غرامة جزائية.","160 دينار+ غرامة 1.28 دينار غرامة 4 بالالف +100- 500 دينار غرامة جزائية."],"answer":1,"orig_answer":null,"law":"sales","article":"26","status":"valid","explanation":"المادة (26/ج): تدفع ضريبة الخدمة المستوردة خلال شهر من دفع بدلها (حتى 2022/6/1)؛ التأخير 11 يوماً = أسبوعان، وغرامة التأخير وفق المادة (51) 4 بالألف أسبوعياً: 160×0.004×2 = 1.28 دينار، ولا تهرب لأن التأخير أقل من ثلاثة أشهر (المادة 30/ل)."},{"num":20,"type":"mcq","q":"إبرمت شركة البحار عقد تأمين على مكتبها في عمان مع شركة التأمين العامة ولمدة سنة كاملة يبدأ العقد بتاريخ 2022/3/1 وينتهي بتاريخ 2023/2/28 حيث بلغت قيمة عقد التأمين 100 الف دينار، وقامت شركة التأمين بإعادة تأمين 75% من قيمة العقد لدى شركة ليدز البريطانية. وعليه قيمة مخصص الاقساط غير المكتسبة الواجب تنزيله في 2022/12/31 هو:","o":["16,164 دينار.","12,123 دينار.","4,041 دينار.","لا شيء مما ذكر."],"answer":2,"orig_answer":null,"law":"income","article":"6","status":"valid","explanation":"المادة (6/د): مخصص الأقساط غير المكتسبة يحسب بعد خصم حصة معيد التأمين: 25% × 100,000 = 25,000 × 59 يوماً (كانون الثاني وشباط 2023) ÷ 365 = 4,041 ديناراً."},{"num":21,"type":"mcq","q":"حسب المادة 30 من قانون الضريبة العامة على المبيعات اي من العبارات التالية صحيحة ويعتبر من جرائم التهرب الضريبي:","o":["تطبيق نسب او فئات ضريبية على السلع او الخدمات الخاضعة للضريبة بصورة مخالفة لاحكام هذا القانون اذا ادى ذلك الى نقص في مقدار الضريبة المستحقة يتجاوز مئتين دينار .","التخلف عن تقديم طلب التسجيل لدى الدائرة في الموعد المحدد للتسجيل بموجب هذا القانون.","إستيفاء ضريبة غير مستحقة وتوريدها خلال المدة التي يحددها القانون لتوريد الضريبة.","جميع ما ذكر غير صحيح."],"answer":3,"orig_answer":null,"law":"sales","article":"30","status":"valid","explanation":"المادة (30): تطبيق نسب مخالفة يعد تهرباً إذا تجاوز النقص خمسمائة دينار لا مئتين، والتخلف عن التسجيل يعد تهرباً إذا زاد على ستين يوماً، واستيفاء ضريبة غير مستحقة لا يعد تهرباً إذا وردت خلال المدة؛ فجميعها غير صحيحة."},{"num":22,"type":"mcq","q":"تلتزم شركة التضامن بتعيين مدقق حسابات قانوني ينتخب بأكثرية الأعضاء إذا كان رأسمالها يبلغ:","o":["100,000 دينار أو أكثر.","75,000 دينار.","50,000 دينار.","10,000 دينار."],"answer":0,"orig_answer":null,"law":"companies","article":"24","status":"valid","explanation":"المادة (24/ب): تلتزم شركة التضامن التي يبلغ رأسمالها مائة ألف دينار أو أكثر بتعيين مدقق حسابات قانوني ينتخب بأكثرية الشركاء."},{"num":23,"type":"mcq","q":"لا يجوز للشركاء في شركة التضامن اخراج أي من الشركة، إلا ؟","o":["قرار من الوزير.","بقرار من المحكمة بناء على طلب اي منهم.","بقرار من (75%) من حصص الشركاء.","بقرار من المراقب."],"answer":1,"orig_answer":null,"law":"companies","article":"23","status":"valid","explanation":"المادة (23): لا يجوز إخراج أي شريك إلا بقرار من المحكمة بناءً على طلب أي من الشركاء."},{"num":24,"type":"mcq","q":"يحق لشركة التضامن أو التوصية البسيطة الاحتفاظ بإسمها الأصلي في حال؟","o":["لا يجوز الاحتفاظ بالاسم الاصلي اذا تغيرت صفة الشركة.","تم تصفيتها ورغبت بالتسجيل كشركة ذات مسؤولية محدودة.","تم شطب تسجيلها، ورغبت بالتسجيل كشركة ذات مسؤولية محدودة.","رغبت بالتحول إلى شركة ذات مسؤولية محدودة."],"answer":3,"orig_answer":null,"law":"companies","article":"56","status":"valid","explanation":"المادة (56): يحق لشركة التضامن أو التوصية البسيطة الاحتفاظ باسمها الأصلي إذا رغبت بالتحول إلى شركة ذات مسؤولية محدودة."},{"num":25,"type":"mcq","q":"إذا كان رأسمال الشركة ذات المسؤولية المحدودة أو جزء منه حصصاً عينية فعلى مقدمي هذه الحصص المحافظة على هذه المقدمات وعدم التصرف بها إلى حين؟","o":["تسليمها إلى الشركة وتسجيلها بإسمها ونقل ملكيتها إليها.","بيعها وتوزيع حصيلة البيع على الشركات مالكي هذه المقدمات العينية.","بيعها وإيداع حصيلة البيع في حسابات الشركة.","جميع ما ذكر صحيح."],"answer":0,"orig_answer":null,"law":"companies","article":"58","status":"valid","explanation":"المادة (58/أ): على مقدمي الحصص العينية المحافظة عليها وعدم التصرف بها إلى حين تسليمها إلى الشركة وتسجيلها باسمها ونقل ملكيتها إليها."},{"num":26,"type":"mcq","q":"ينشأ حق المساهم في الأرباح السنوية للشركة المساهمة العامة عند:","o":["موافقة الوزير ومراقب عام الشركات.","صدور قرار الهيئة العامة بتوزيع الأرباح.","موافقة هيئة الأوراق المالية.","موافقة مراقب عام الشركات."],"answer":1,"orig_answer":null,"law":"companies","article":"191","status":"valid","explanation":"المادة (191/أ): ينشأ حق المساهم في الأرباح السنوية بصدور قرار الهيئة العامة بتوزيعها."},{"num":27,"type":"mcq","q":"يتطلب موافقة ثلثي دائني الشركة في احدى الحالات التالية:","o":["شطب تسجيل شركة.","تسجيل شركة.","دمج الشركات.","تحويل الصفة القانونية للشركة."],"answer":3,"orig_answer":null,"law":"companies","article":"218","status":"valid","explanation":"المادتان (216/ج) و(218/ب): لا يتم تحويل الصفة القانونية للشركة إلا بموافقة خطية من الدائنين الذين يملكون أكثر من ثلثي ديونها."},{"num":28,"type":"mcq","q":"نصاب الحضور في اجتماع الهيئة العامة غير العادي الثاني (المؤجل) هو:","o":["10%.","75%.","50%.","40%."],"answer":3,"orig_answer":null,"law":"companies","article":"173","status":"valid","explanation":"المادة (173/أ): الاجتماع غير العادي الثاني (المؤجل) قانوني بحضور مساهمين يمثلون (40%) من الأسهم المكتتب بها على الأقل."},{"num":29,"type":"mcq","q":"تستمد الشركة ذات المسؤولية المحدودة اسمها من:","o":["اسم أحد الشركاء ويقترن بكلمة وشركاه.","غاياتها.","أسماء الشركاء.","في جميع الخيارات أعلاه."],"answer":1,"orig_answer":null,"law":"companies","article":"55","status":"valid","explanation":"المادة (55): تستمد الشركة ذات المسؤولية المحدودة اسمها من غاياتها."},{"num":30,"type":"mcq","q":"يتولى إدارة الشركة ذات المسؤولية المحدودة مدير أو هيئة مديرين عددهم:","o":["غير محدد العدد.","لا يقل عن اثنين ولا يزيد على سبعة.","لا يقل عن خمسة ولا يزيد على تسعة أعضاء.","لا يقل عن ثلاثة ولا يزيد على تسعة أعضاء."],"answer":1,"orig_answer":null,"law":"companies","article":"60","status":"valid","explanation":"المادة (60/أ): يتولى إدارتها مدير أو هيئة مديرين لا يقل عددها عن اثنين ولا يزيد على سبعة."},{"num":31,"type":"mcq","q":"لغايات تطبيق أحكام قانون الإعسار يعتبر الشخص الاعتباري ذا صلة بالمدين:","o":["أي شخص يملك (10%) و أكثر من أسهم الشركة المساهمة العامة أو أياً من الشركات الحليفة.","أي شخص يملك (3%) و أكثر من أسهم الشركة المساهمة العامة أو أياً من الشركات الحليفة","أي شخص يملك (5%) و أكثر من أسهم الشركة المساهمة العامة أو أياً من الشركات الحليفة.","أي شخص يملك (19%) و أكثر من أسهم الشركة المساهمة العامة أو أياً من الشركات الحليفة."],"answer":2,"orig_answer":null,"law":"insolvency","article":"4","status":"valid","explanation":"المادة (4/ب/4): أي شخص يمتلك (5%) أو أكثر من أسهم الشركة المساهمة العامة أو أي من الشركات الحليفة يعتبر ذا صلة بالمدين."},{"num":32,"type":"mcq","q":"تعتبر المحكمة قد بدأت في تصفية الشركة المساهمة العامة وذلك من:","o":["بعد شهر من تاريخ تعيين مصفي.","من تاريخ تعيين المحكمة مصفي للشركة.","من تاريخ موافقة مراقب عام الشركات على احالتها للتصفية الاجبارية.","تاريخ تقديم لائحة دعوى التصفية لها."],"answer":3,"orig_answer":null,"law":"companies","article":"267","status":"valid","explanation":"المادة (267/أ): تعتبر المحكمة قد بدأت في التصفية من تاريخ تقديم لائحة دعوى التصفية لها."},{"num":33,"type":"mcq","q":"النسبة المحددة التي تجيز لمساهمين الطلب من مراقب عام الشركات اجراء تدقيق على أعمال الشركة هي:","o":["30%.","20%.","10%.","5%."],"answer":2,"orig_answer":null,"law":"companies","article":"275","status":"valid","explanation":"المادة (275): لمساهمين يملكون ما لا يقل عن (10%) من رأس المال الطلب من المراقب إجراء تدقيق على أعمال الشركة."},{"num":34,"type":"mcq","q":"أي من العبارات التاليه تعتبر غير صحيحة بموجب قانون التجاره رقم (12) لعام 1966.","o":["يجوز اعادة الاعتبار للمفلس بعد وفاته.","لا يجوز إعادة الاعتبار الى المفلسين الذين حكم عليهم بالافلاس الاحتيالي او بسرقة او احتيال او اساءة امانة الا اذا كانوا قد حصلوا على اعادة الاعتبار الجزائي.","تخضع الشركات المدنية والشركات المرخصة او المسجلة بمقتضى قانون الشركات الساري المفعول الى اجراءات التصفية الفسخ الواردة فيه.","جميع العبارات صحيحة."],"answer":null,"orig_answer":null,"law":"other:قانون التجارة رقم 12 لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة لسنة 1966 غير مشمول بالقوانين المتوفرة؛ لم يتم التحقق."},{"num":35,"type":"mcq","q":"أي من العبارات التاليه تعتبر غير صحيحة فيما يتعلق بالسمسره حسب قانون التجاره رقم (12) لعام 1966.","o":["يجب على السمسار ان يحتفظ بالعينة في البيوعات بالعينه الى ان تتم العمليه.","اذا اشترط إرجاع النفقات التي صرفها السمسار فترجع له، وان لم يتم الاتفاق.","تسري قواعد الوكالة بوجه محدد على أعمال السمسره.","تسري قواعد الوكالة بوجه عام على السمسره."],"answer":null,"orig_answer":null,"law":"other:قانون التجارة رقم 12 لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة لسنة 1966 غير مشمول بالقوانين المتوفرة؛ لم يتم التحقق (المرجح أن الخطأ في (ج) لأن قواعد الوكالة تسري بوجه عام على السمسرة)."},{"num":36,"type":"mcq","q":"أي من العبارات التاليه تعتبر غير صحيحة فيما يتعلق بالعقود التجارية حسب قانون التجاره :","o":["كل التزام تجاري يقصد به القيام بعمل او بخدمة لا يعد معقوداً على وجه مجاني واذا لم يعين الفريقين اجرة او عمولة او سمسرة فيستحق الدائن الاجر المعروف في المهنة.","يخضع إثبات العقود التجارية مبدئياً للقواعد الحصرية الموضوعة للعقود المدنية.","يعتمد في اثبات العدل والثمن الدارج على اسعار البورصة والتسعيرات ان وجدت ما لم يوجد اتفاق مخالف.","أ+ج غير صحيح."],"answer":1,"orig_answer":null,"law":"other:قانون التجارة رقم 12 لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة لسنة 1966 غير مشمول؛ المرجح أن العبارة غير الصحيحة (ب) لأن إثبات العقود التجارية لا يخضع مبدئياً للقواعد الحصرية للعقود المدنية."},{"num":37,"type":"mcq","q":"بموجب قانون التجاره فيما يتعلق بالوكالة التجارية فان احدى العبارات التالية غير صحيحة:","o":["الوكيل الذي لم يتلق تعليمات الا في شأن جزء من العمل لا يعد مطلق اليد في الجزء الباقي.","عندما يعمل الوكيل باسم موكله تكون حقوقه والتزاماته خاضعة للاحكام الواردة بهذا الشأن في القانون المدني.","الوكالة التجارية وان احتوت على توكيل مطلق لا تجيز الاعمال غير التجارية الا بنص صريح.","يسمى هذا العقد وكالة بالعمولة ويجب على الوكيل ان يعمل باسمه الخاص او تحت عنوان تجاري لحساب من وكله."],"answer":null,"orig_answer":null,"law":"other:قانون التجارة رقم 12 لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة لسنة 1966 غير مشمول بالقوانين المتوفرة؛ لم يتم التحقق."},{"num":38,"type":"mcq","q":"جميع الامور التاليه صحيحه بخصوص الشيكات حسب قانون التجارة بإستثناء:","o":["تسقط بالتقادم دعاوى رجوع مختلف الملتزمين بوفاء الشيك بعضهم تجاه بعض بمضي خمس سنوات محسوبة من اليوم الذي خوصم فيه بدعوى الرجوع.","تسقط بالتقادم دعاوى رجوع الحامل على المظهرين والساحب والملتزمين الاخرين بمضي ستة شهور محسوبة من تاريخ انقضاء ميعاد التقديم.","تسقط بالتقادم دعوى حامل الشيك تجاه المسحوب عليه بمقتضى خمس سنوات محسوبة من تاريخ انقضاء الميعاد المحدد لتقديم الشيك للوفاء.","لحامل الشيك مطالبة من له حق الرجوع عليه بمبلغ الشيك غير المدفوع والفوائد ابتداء من يوم التقديم محسوبة بسعرها القانوني للشيكات المسحوبة في المملكة الاردنية الهاشمية والمستحقة الوفاء فيها وبسعر 6% بالنسبة للشيكات الاخرى ومصاريف الاحتجاج والاشعارات."],"answer":null,"orig_answer":null,"law":"other:قانون التجارة رقم 12 لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة لسنة 1966 (أحكام الشيك) غير مشمول بالقوانين المتوفرة؛ لم يتم التحقق."},{"num":39,"type":"mcq","q":"يتولى رئيس مجلس إدارة جمعية المحاسبين القانونيين المهام والصلاحيات التالية بإستثناء:","o":["وضع جدول اعمال إجتماعات المجلس.","الاشراف على الموظفين والعاملين في الجمعية.","التوقيع عن الجمعية في الامور المالية.","جميع ما ذكر."],"answer":null,"orig_answer":null,"law":"other:نظام جمعية المحاسبين القانونيين الأردنيين","article":"45","status":"unverified","explanation":"المادة (45) تحيل تحديد صلاحيات الرئيس والمفوضين بالتوقيع إلى نظام يصدر بمقتضى القانون؛ لم يتوفر نص النظام للتحقق."},{"num":40,"type":"mcq","q":"تتولى الجمعية في سبيل تحقيق اهدافها المهام والصلاحيات التالية ماعدا:","o":["اقتراح تطوير التشريعات ذات العلاقة بالمهنة.","التعاون في مجال المهنة مع الجامعات والمؤسسات التعليمية.","ترسيخ قواعد السلوك المهني.","توثيق العلاقات المهنية والاجتماعية بين مزاولي المهنة محلياً وعربياً ودولياً."],"answer":2,"orig_answer":null,"law":"accounting","article":"9","status":"valid","explanation":"المادة (9): مهام الجمعية تشمل اقتراح تطوير التشريعات والتعاون مع الجامعات وتوثيق العلاقات المهنية، وليس من بينها (ترسيخ قواعد السلوك المهني)."},{"num":41,"type":"mcq","q":"كل من خالف احكام المادة (21) من قانون تنظيم مهنة المحاسبة القانونية لسنة 2003 والتي تحظر على اي شخص غير حاصل على إجازة المزاوله وغير مسجل في سجل المزاولين وقام بمزاولة اعمال التدقيق بالعقوبة التالية:","o":["يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على ثلاث سنوات او بغرامه لا تقل عن خمسة الاف دينار ولا تزيد على عشرين الف دينار او بكلتا العقوبتين.","يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على اربع سنوات او بغرامه لا تقل عن خمسة الاف دينار ولا تزيد على عشرين الف دينار او بكلتا العقوبتين.","يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على ثلاث سنوات او بغرامه لا تقل عن أربعة الاف دينار ولا تزيد على عشرة الاف دينار او بكلتا العقوبتين.","يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على اربع سنوات او بغرامه لا تقل عن خمسة الاف دينار ولا تزيد على عشرة الاف دينار او بكلتا العقوبتين."],"answer":0,"orig_answer":null,"law":"accounting","article":"43","status":"valid","explanation":"المادة (43/أ/1): الحبس من سنة إلى ثلاث سنوات أو غرامة من خمسة آلاف إلى عشرين ألف دينار أو كلتاهما."},{"num":42,"type":"mcq","q":"إي من العبارات التالية غير صحيحة فيما يتعلق بضمانات المسؤولية المدنية المنصوص عليها في المادة 56 من القانون على وكيل الاعسار :","o":["على وكيل الاعسار تقديم ضمانات كافية أو استصدار بوليصة تأمين ضد المسؤولية المهنية وفقاً للشروط التي ينص عليها النظام الذي يصدر بموجب احكام هذا القانون.","يكون وكيل الاعسار مسؤولاً عن اي ضرر يلحق بذمة الاعسار أو بالاشخاص الذين اشتركوا في اجراءات الاعسار نشأ عن إهماله او اهمال ممثليه او تابعيه في اداء مهامهم او إخلالهم بالواجبات المنوطة بهم.","يسقط حق المطالبة بالتعويض المنصوص عليه في الفقرة أ بمرور ثلاث سنوات على تاريخ علم المضرور بالضرر وبالشخص المسؤول عنه أو بمرور ثلاث سنوات على تاريخ إستكمال إجراءات الاعسار أيهما يقع اولاً.","جميع العبارات صحيحة."],"answer":2,"orig_answer":null,"law":"insolvency","article":"56","status":"valid","explanation":"المادة (56/ب): يسقط حق المطالبة بمرور ثلاث سنوات على العلم أو ثلاث سنوات على استكمال إجراءات الإعسار أيهما يقع لاحقاً لا أولاً."},{"num":43,"type":"mcq","q":"حسب المادة 51 من قانون الاعسار ان العبارة التالية صحيحة:","o":["على وكيل الاعسار ان يؤدي واجباته بنفسه وبالدقة والامانة المطلوبة وان يلتزم الحياد مع جميع الجهات التي تتاثر باجراءات الإعسار.","لوكيل الاعسار الاستعانة بخبراء يختارهم لتنفيذ مهامه على ان يبقى مسؤولاً عن تنفيذ تلك المهام و يتحمل أتعاب الخبراء ما لم يقرر الدائنين غير ذلك.","يحظر على وكيل الاعسار تفويض مهامه للغير الا في ظروف إستثنائية على ان يكون التفويض محددا من حيث المده والمهام وبموافقة المحكمة على ان يكون وكيل الاعسار مسؤول عن اعمال المفوض.","جميع العبارات غير صحيحة."],"answer":0,"orig_answer":null,"law":"insolvency","article":"51","status":"valid","explanation":"المادة (51): على وكيل الإعسار أداء واجباته بالدقة والأمانة والتزام الحياد (أ)، أما أتعاب الخبراء فما لم تقرر المحكمة (لا الدائنون)، والمفوض ووكيل الإعسار مسؤولان بالتكافل والتضامن."},{"num":44,"type":"mcq","q":"حسب قانون الاعسار فان العبارة التالية غير صحيحة:","o":["لدائني هذه الديون الحق في تقديم دفوعهم واعتراضاتهم على طلب المدين بالابراء خلال مدة سبعة ايام من تاريخ تبلغهم الطلب.","للمدين حسن النية تقديم طلب للمحكمة بالابراء من الديون غير المسددة وعلى المحكمة تبليغ هذا الطلب الى دائني هذه الديون ووكيل الاعسار خلال اسبوع من وروده اليها .","تعلن المحكمة إنتهاء إجراءات الاعسار بعد إتمام التوزيع النهائي او اذا تم سداد كامل الديون اثناء السير في إجراءات الاعسار ويتم اشهار قرار المحكمة وسبب انتهاء الاجراءات.","اذا كان المدين شخصاً إعتبارياً، تنتهي شخصيته الاعتبارية باستكمال توزيع العوائد ما لم يتم سداد ديونه بالكامل وعلى وكيل الاعسار تبليغ الجهة التي تم تسجيل الشخص الاعتباري لديها بقرار المحكمة لغايات شطب تسجيله وفقاً للتشريعات ذات العلاقة."],"answer":1,"orig_answer":null,"law":"insolvency","article":"108","status":"valid","explanation":"المادة (108/أ): على المحكمة تبليغ طلب الإبراء للدائنين ووكيل الإعسار فور وروده إليها لا خلال أسبوع."},{"num":45,"type":"mcq","q":"حسب قانون الإستثمار رقم (30) لسنة 2014 اي من العبارات التالية تعتبر غير صحيحه:","o":["تخضع للضريبة العامة على المبيعات السلع والخدمات التي يكون منشؤها في المنطقة التنموية والتي يتم بيعها إلى باقي مناطق المملكه.","تخفض الضريبة العامة المنصوص عليها في قانون الضريبة العامة على المبيعات على السلع والخدمات التي تقوم المؤسسة المسجله بشرائها او استيرادها لغايات ممارسة النشاط الاقتصادي داخل المناطق التنمويه لنسبة (الصفر) مع إلتزام بتقديم كفالة لدى دائرة ضريبة الدخل والمبيعات بهذا الخصوص.","يتم إستيفاء ضريبة مبيعات بنسبة 7% من قيمة بيع الخدمات التي يتم تحديدها بموجب النظام الصادر لهذه الغاية وذلك عند بيعها للاستهلاك في المنطقة التنموية.","لا شيء مماذكر غير صحيح."],"answer":null,"orig_answer":1,"law":"investment","article":"30","status":"changed","explanation":"قانون الاستثمار رقم 30 لسنة 2014 ألغي بقانون البيئة الاستثمارية رقم 21 لسنة 2022؛ المادة (30) منه تخضع مشتريات المؤسسة المسجلة لنسبة الصفر دون اشتراط كفالة ولم تعد تنص على نسبة 7% على الخدمات، فيصبح (ب) و(ج) غير صحيحين معاً."},{"num":46,"type":"mcq","q":"إحدى العبارات التالية غير صحيحة بموجب قانون رسوم الطوابع والواردات لسنة 2001:","o":["يعتبر تجديد أي معامله واردة في جدول المعاملات الخاضعه للرسوم الملحق بالقانون أو تمديدها بمثابة معاملة جديدة تخضع للرسوم المنصوص عليها في هذا الجدول.","تفرض على الموظف الذي لم يبطل الطوابع على المعامله بالصورة التي حددها القانون غرامة تعادل مثلا مقدار الرسم المقرر وبحد أدنى مقداره دينار واحد.","تفرض غرامة على المكلف بدفع الرسم المقرر إذا تأخر عن دفعه في الموعد المحدد بواقع مثل الرسم المستحق أو مقدار النقص فيه اذا كان التأخير لمدة تزيد على ثلاثين يوماً ولا تتجاوز ستين يوماً وبحد أدنى مقداره دينار واحد.","إذا تداخلت أكثر من معامله خاضعة للرسم في معاملة واحدة فيستوفى عن كل منها الرسم المقرر باعتبارها معاملة مستقلة."],"answer":1,"orig_answer":null,"law":"stamp","article":"12","status":"valid","explanation":"المادة (12/ب/2): غرامة الموظف الذي لم يبطل الطوابع تعادل مثل مقدار الرسم (لا مثليه) وبحد أدنى دينار واحد."},{"num":47,"type":"mcq","q":"أي من العبارات التالية تعتبر غير صحيحه بموجب قانون ديوان المحاسبة رقم 28 لسنة 1952 وتعديلاته:","o":["يتولى ديوان المحاسبة التدقيق اللاحق على النفقات الا انه يجوز لرئيس ديوان المحاسبة في حالات خاصة ان يقرر التدقيق في النفقات قبل الصرف.","على اي جهة من الجهات الخاضعه لرقابة ديوان المحاسبة الاجابة على اي استيضاح يوجهه اليها الديوان ضمن نطاق مهامه وذلك خلال مدة لا تتجاوز ستين يوماً اعتباراً من تاريخ وصوله الى تلك الجهة.","لرئيس ديوان المحاسبة في اي وقت ان يقدم لمجلس النواب تقارير خاصة يلفت نظره الى امور يرى انها من الخطر والاهمية بحيث تستلزم تعجيل النظر فيها.","على أي جهة خاضعه لرقابة ديوان المحاسبة ان تقدم للديوان البيانات المالية للسنة المنتهية خلال ستة اشهر من تاريخ انتهاء تلك السنة."],"answer":1,"orig_answer":null,"law":"audit","article":"16","status":"valid","explanation":"المادة (16): مدة الإجابة على الاستيضاح ثلاثون يوماً إذا كان مركز الجهة داخل المملكة وستون يوماً إذا كان خارجها (ويلاحظ أن المادة 25 تشترط أيضاً موافقة رئيس الوزراء للتدقيق المسبق)."},{"num":48,"type":"mcq","q":"أي من العبارات تعتبر غير صحيحة وفقاً لقانون المنافسة لسنة 2004.","o":["تشكل لجنة شؤون المنافسة برئاسة وزير الصناعة والتجارة تجتمع بدعوة من رئيسها او نائبه عند غيابه مره واحدة شهرياً ويكون اجتماعها قانونياً بحضور ما لايقل عن ثلثي اعضائها على ان يكون من بينهم الرئيس او نائبه.","يختص للنظر في قضايا الممارسات المخله بالمنافسة ضمن محكمة البداية قاض او اكثر من ذوي الاختصاص ممن تلقوا تدريباً خاصا على ان يتم تعيينهم بقرار من المجلس القضائي.","يحظر على اي مؤسسة لها وضع مهيمن في السوق او جزء هام منه اساءة استغلال هذا الوضع التمييز بين العملاء في العقود المتشابهه بالنسبة لاسعار السلع والخدمات او شروط بيعها وشرائها .","تحدد اسعار السلع والخدمات وفقاً لقواعد السوق ومبادئ المنافسة الحرة باستثناء اسعار الخدمات التي يتم تحديدها وفقاً لاحكام قانون الصناعه والتجارة او اي قانون اخر."],"answer":0,"orig_answer":null,"law":"competition","article":"15","status":"valid","explanation":"المادة (15/أ): تجتمع لجنة شؤون المنافسة مرة كل ستة أشهر على الأقل وليس مرة شهرياً."},{"num":49,"type":"mcq","q":"اي من العبارات التالية لا تعتبر صحيحه بموجب قانون مكافحة غسيل الاموال وتمويل الارهاب رقم (20) لسنة 2021:","o":["المتحصلات تشمل اي متحصلات ناجمة عن اي فعل يعتبر جريمة بمقتضى اتفاقيات دولية صادقت عليها المملكة شريطة ان يكون معاقباً عليها في القانون الاردني.","تمارس النيابة العامة او المحكمة المختصة اختصاصاتها في الجرائم المنصوص عليها في هذا القانون وفق اصول المحاكمات الجزائية ولها حجز ممتلكات اختلطت فيها المتحصلات مع اموال من مصادر مشروعة الى ان تحدد قيمة المتحصلات غير المشروعه ونواتج استغلالها.","المستفيد الحقيقي هو الشخص الطبيعي الذي يمتلك او يمارس سيطرة فعلية نهائية على العميل بصورة مباشرة او غير مباشرة او الذي تتم العمليات نيابة عنه او يمارس سيطرة فعلية نهائية على شخص طبيعي او ترتيب قانوني.","كل ما ذكر غير صحيح."],"answer":2,"orig_answer":null,"law":"aml","article":"2","status":"valid","explanation":"المادة (2): المستفيد الحقيقي يمارس سيطرة فعلية نهائية على شخص اعتباري أو ترتيب قانوني (لا شخص طبيعي)."},{"num":50,"type":"mcq","q":"أي من العبارات التالية لا تعتبر صحيحة بموجب قانون النزاهة ومكافحة الفساد رقم (13) لسنة 2016:","o":["لمجلس الوزراء بناء على تنسيب مجلس الهيئة انهاء خدمة اي عضو من اعضائه خلال مدة المجلس اذا تغيب عن اجتماعات المجلس ثلاث جلسات متتالية او ست جلسات متفرقة خلال السنة الواحدة دون عذر يقبله المجلس.","يطبق على الرئيس واعضاء المجلس قانون الكسب غير المشروع.","مدة العضوية في مجلس الهيئة اربع سنوات قابلة للتجديد لمرة واحدة للرئيس او لعضو المجلس.","تمارس الهيئة مهامها واعمالها بحرية واستقلال دون تأثير او تدخل من اي جهة فلا يجوز تفتيش مقر هيئة النزاهة ومكافحة الفساد من اي جهة."],"answer":3,"orig_answer":null,"law":"integrity","article":"5","status":"valid","explanation":"المادة (5/ب): لا يجوز تفتيش مقر الهيئة إلا بأمر قضائي وبحضور المدعي العام المختص، فالقول بعدم جواز التفتيش مطلقاً غير صحيح."},{"num":51,"type":"mcq","q":"يجوز للبنك المركزي في ظروف طارئة قد تهدد الاستقرار النقدي أو المالي في المملكة منح تسهيلات سيولة استثنائية للبنك إذا كانت مؤشرات تقييم الأوضاع المالية الخاصة به تدل على قدرته على الاستمرار في نشاطه وذلك وفقاً لشروط يحددها: (المادة 41/ قانون البنك المركزي الأردني رقم 23 لسنة 1971 وتعديلاته).","o":["وزير المالية.","محافظ البنك المركزي الأردني.","مجلس إدارة البنك المركزي الأردني.","مجلس الوزراء."],"answer":null,"orig_answer":null,"law":"other:قانون البنك المركزي الأردني رقم 23 لسنة 1971","article":"","status":"unverified","explanation":"قانون البنك المركزي الأردني غير مشمول بالقوانين المتوفرة؛ المرجح (ج) مجلس إدارة البنك المركزي."},{"num":52,"type":"mcq","q":"يكون أي تحديد او تغيير في نسبة الاحتياطي النقدي الالزامي نافذ المفعول بعد مضي: (المادة 42 / قانون البنك المركزي الأردني رقم 23 لسنة 1971 وتعديلاته):","o":["ثلاثين يوماً على الأقل من إرسال إشعار خطي للبنوك يعلمها البنك المركزي فيه بهذا التحديد أو التغيير.","خمسة عشر على الأقل من إرسال إشعار خطي للبنوك يعلمها البنك المركزي فيه بهذا التحديد أو التغيير.","عشر أيام على الأقل من إرسال إشعار خطي للبنوك يعلمها البنك المركزي فيه بهذا التحديد أو التغيير.","عشرين يوماً على الأقل من إرسال اشعار خطي للبنوك يعلمها البنك المركزي فيه بهذا التحديد أو التغيير."],"answer":null,"orig_answer":null,"law":"other:قانون البنك المركزي الأردني رقم 23 لسنة 1971","article":"","status":"unverified","explanation":"قانون البنك المركزي الأردني غير مشمول بالقوانين المتوفرة؛ لم يتم التحقق."},{"num":53,"type":"mcq","q":"لا يجوز للبنك المركزي الأردني ان يتعامل بالتجارة الا في حدود ما سمح له به في القانون، ولا يجوز أن يكون له نفع خاص في أي مشروع زراعي أو صناعي أو ما شابه ذلك ما عدا ما اتصل باستيفاء ديون للبنك المركزي شريطة التخلص منه خلال: (المادة 58 / قانون البنك المركزي الأردني رقم 23 لسنة 1971 وتعديلاته).","o":["ثلاث سنوات على الأكثر بعد تملكه له.","سنة على الأكثر بعد تملكه له.","سنتين على الأكثر بعد تملكه له.","لا شيء مما ذكر."],"answer":null,"orig_answer":null,"law":"other:قانون البنك المركزي الأردني رقم 23 لسنة 1971","article":"","status":"unverified","explanation":"قانون البنك المركزي الأردني غير مشمول بالقوانين المتوفرة؛ لم يتم التحقق."},{"num":54,"type":"mcq","q":"عرف قانون الضمان الاجتماعي صاحب العمل بأنه:","o":["الشخص الطبيعي الذي تسري عليه أحكام هذا القانون ذكراً أم أنثى.","كل شخص معنوي يستخدم عاملاً أو أكثر من الخاضعين لأحكام هذا القانون.","كل شخص طبيعي يستخدم عاملاً أو أكثر من الخاضعين لأحكام هذا لقانون.","كل شخص طبيعي أو معنوي يستخدم عاملاً أو أكثر من الخاضعين لأحكام هذا القانون."],"answer":3,"orig_answer":null,"law":"social","article":"2","status":"valid","explanation":"المادة (2): صاحب العمل كل شخص طبيعي أو معنوي يستخدم عاملاً أو أكثر من الخاضعين لأحكام القانون."},{"num":55,"type":"mcq","q":"عرف قانون الضمان الاجتماعي العجز الكلي الاصابي الدائم بأنه:","o":["كل عجز ينشأ عن إصابة العمل ويفقد المؤمن عليه بسببه مقدرته الجسدية على العمل بصفة دائمة بنسبة تقل عن 75%.","كل عجز ينشأ عن إصابة العمل ويفقد المؤمن عليه بسببه مقدرته الجسدية على العمل بصفة دائمة بنسبة لا تقل عن 75%.","كل عجز ينشأ عن إصابة العمل ويفقد المؤمن عليه بسببه مقدرته الجسدية على العمل بصفة دائمة بنسبة لا تقل عن 70%.","كل عجز ينشأ عن إصابة العمل ويفقد المؤمن عليه بسببه مقدرته الجسدية على العمل بصفة دائمة بنسبة تقل عن 70%."],"answer":1,"orig_answer":null,"law":"social","article":"2","status":"valid","explanation":"المادة (2): العجز الكلي الإصابي الدائم بنسبة لا تقل عن (75%)."},{"num":56,"type":"mcq","q":"تسري أحكام قانون الضمان الاجتماعي المتعلقة بتأمين إصابات العمل على المتدربين على العمل الذين لم يكملوا:","o":["تسعة عشرة سنة من أعمارهم.","ثماني عشرة سنة من أعمارهم.","سبعة عشرة سنة من أعمارهم.","ست عشرة سنة من أعمارهم."],"answer":3,"orig_answer":null,"law":"social","article":"5","status":"valid","explanation":"المادة (5/أ): تسري أحكام إصابات العمل على المتدربين الذين لم يكملوا ست عشرة سنة من أعمارهم."},{"num":57,"type":"mcq","q":"إن إصدار التعليمات التنفيذية والتنظيمية الداخلية والمالية والإدارية والفنية والاستثمارية للمؤسسة العامة للضمان الاجتماعي من صلاحيات:","o":["مجلس الإدارة.","مجلس الاستثمار.","مجلس التأمينات.","المدير العام."],"answer":0,"orig_answer":null,"law":"social","article":"11","status":"valid","explanation":"المادة (11/ك): إصدار التعليمات التنفيذية والتنظيمية الداخلية والمالية والإدارية والفنية والاستثمارية من صلاحيات المجلس (مجلس إدارة المؤسسة)."},{"num":58,"type":"mcq","q":"للمؤمن عليها الانتفاع من تأمين الأمومة المنصوص عليه في قانون الضمان الاجتماعي وفقاً للمدد المحددة في قانون العمل النافذ شريطة أن تثبت الولادة بشهادة رسمية وأن تكون مشمولة بأحكام هذا التأمين خلال:","o":["الستة أشهر الأخيرة التي تسبق استحقاقها اجازة الأمومة.","الشهر الأخير الذي يسبق استحقاقها اجازة الأمومة.","الثلاثة أشهر الأخيرة التي تسبق استحقاقها اجازة الأمومة.","لا شيء مما ذكر."],"answer":0,"orig_answer":null,"law":"social","article":"44","status":"valid","explanation":"المادة (44/أ): أن تكون مشمولة بتأمين الأمومة خلال الأشهر الستة الأخيرة التي تسبق استحقاقها إجازة الأمومة."},{"num":59,"type":"mcq","q":"إذا انتهت خدمة الموظف التابع لقانون التقاعد المدني ولم يكمل مدة الخدمات المقبولة للتقاعد المنصوص عليها في ذلك القانون فيجوز بناء على طلب منه إعادة احتساب تلك الخدمات لغايات قانون الضمان الاجتماعي شريطة تحويل العائدات التقاعدية المستحقة عن تلك الخدمات إلى:","o":["المؤسسة العامة للضمان الاجتماعي بنسبة ثلثين وخزينة الدولة نسبة ثلث .","المؤسسة العامة للضمان الاجتماعي بنسبة ثلث وخزينة الدولة نسبة ثلثين .","خزينة الدولة.","المؤسسة العامة للضمان الاجتماعي."],"answer":3,"orig_answer":null,"law":"social","article":"85 مكرر","status":"valid","explanation":"المادة (85 مكرر): تحول العائدات التقاعدية إلى المؤسسة دون أن تتحمل الخزينة أي مبالغ."},{"num":60,"type":"mcq","q":"يسقط حق المؤسسة العامة للضمان الاجتماعي في المطالبة بالمبالغ المستحقة لها بموجب أحكام قانون الضمان الاجتماعي بإنقضاء:","o":["خمس عشرة سنة من تاريخ استحقاقها.","عشر سنوات من تاريخ استحقاقها.","خمس سنوات من تاريخ استحقاقها.","ثلاث سنوات من تاريخ استحقاقها."],"answer":0,"orig_answer":null,"law":"social","article":"95","status":"valid","explanation":"المادة (95/ج): يسقط حق المؤسسة بانقضاء خمس عشرة سنة من تاريخ الاستحقاق."},{"num":61,"type":"mcq","q":"يتم حجز ورهن الأوراق المالية لدى:","o":["المحكمة.","بورصة عمان.","مركز ايداع الأوراق المالية.","هيئة الأوراق المالية."],"answer":2,"orig_answer":null,"law":"securities","article":"79","status":"valid","explanation":"المادة (79/و): الحجز أو أي قيد على الأوراق المالية المودعة يثبت في سجلات مركز إيداع الأوراق المالية."},{"num":62,"type":"mcq","q":"يجب على المصدر تقديم تقرير سنوي للهيئة خلال مدة ...... من تاريخ انتهاء سنته المالية؟","o":["90 يوم.","60 يوم.","45 يوم.","30 يوم."],"answer":0,"orig_answer":null,"law":"securities","article":"43","status":"valid","explanation":"المادة (43/أ/1): التقرير السنوي خلال تسعين يوماً من انتهاء السنة المالية."},{"num":63,"type":"mcq","q":"العرض العام لبيع الأوراق المالية هو العرض الموجه:","o":["لأكثر من 50 شخص.","لأقل من 20 شخص.","لأكثر من 30 شخص.","لا شيء مما ذكر."],"answer":2,"orig_answer":null,"law":"securities","article":"2","status":"valid","explanation":"المادة (2): العرض العام عرض لبيع ورقة مالية لأكثر من ثلاثين شخصاً من الجمهور."},{"num":64,"type":"mcq","q":"وفقاً لتعليمات اصدار الأوراق المالية وتسجيلها فإن الحد الأدنى لعدد الأسهم في طلب الاكتتاب ما بين:","o":["100 إلى 500 سهم.","600 إلى 1000 سهم.","500 إلى 600 سهم.","لا شيء مما ذكر."],"answer":null,"orig_answer":null,"law":"other:تعليمات إصدار الأوراق المالية وتسجيلها","article":"","status":"unverified","explanation":"تعليمات إصدار الأوراق المالية وتسجيلها غير متوفرة؛ لم يتم التحقق."},{"num":65,"type":"mcq","q":"يشترط أن لا يقل رأسمال صندوق الاستثمار المشترك عند التأسيس عن:","o":["أربعة ملايين دينار أردني أو ما يعادل ذلك من العملات الأجنبية.","خمسة ملايين دينار أردني أو ما يعادل ذلك من العملات الأجنبية.","مليوني دينار أردني أو ما يعادل ذلك من العملات الأجنبية.","لا شيء مما ذكر."],"answer":null,"orig_answer":null,"law":"other:تعليمات/نظام صناديق الاستثمار المشترك","article":"","status":"unverified","explanation":"تعليمات/نظام صناديق الاستثمار المشترك غير متوفرة؛ لم يتم التحقق."},{"num":66,"type":"mcq","q":"على الشركة تقديم إفصاح للهيئة عن الفروقات التي تساوي أو تزيد عن (....) بين نتائج الأعمال الأولية والبيانات المالية السنوية وأسبابها معززة من مدقق الحسابات الخارجي:","o":["75%.","50%.","20%.","10%."],"answer":null,"orig_answer":null,"law":"other:تعليمات إفصاح الشركات المصدرة والمعايير المحاسبية ومعايير التدقيق","article":"","status":"unverified","explanation":"تعليمات الإفصاح غير متوفرة؛ لم يتم التحقق."},{"num":67,"type":"mcq","q":"يتولى مدير الاستثمار بصندوق الاستثمار المشترك المهام التالية:","o":["تزويد الهيئة بالبيانات المالية للصندوق.","إعداد نشرة الإصدار والنظام الأساسي للصندوق.","مراقبة الالتزام بالسياسة الاستثمارية للصندوق.","لا شيء مما ذكر."],"answer":null,"orig_answer":null,"law":"other:تعليمات/نظام صناديق الاستثمار المشترك","article":"","status":"unverified","explanation":"تعليمات صناديق الاستثمار المشترك غير متوفرة؛ لم يتم التحقق."},{"num":68,"type":"mcq","q":"أي من الحالات التالية التي يجوز فسخ عقد التاجير بقرار من المحكمة المختصه او باشعار من المستأجر (اذا اجاز له العقد ذلك) حسب المادة 20 من قانون التأجير التمويلي رقم (45) لسنة 2008:","o":["أي حالة أخرى تشكل مخالفة جوهرية لعقد التأجير او التشريعات النافذة.","عدم تمكين المؤجر للمستأجر من الانتفاع بالمأجور وفقاً لاحكام القانون.","عدم قيام المؤجر باعمال الصيانة والاصلاح للمأجور ضمن المده المحددة في عقد التأجير او ضمن مدة معقوله في حال عدم تحديد تلك المدة وذلك في الحالات التي يفرض فيها عقد التأجير او التشريعات النافذة على المؤجر الالتزام بالصيانة والاصلاح.","جميع ما ذكر صحيح."],"answer":3,"orig_answer":null,"law":"leasing","article":"20","status":"unverified","explanation":"قانون التأجير التمويلي غير متوفر في ملفات القوانين؛ المادة (20) تجيز الفسخ في جميع الحالات المذكورة (عدم التمكين من الانتفاع، عدم الصيانة، أي مخالفة جوهرية) ولم يتم التحقق من النص."},{"num":69,"type":"mcq","q":"أي من العبارات تعتبر غير صحيحة وفقاً لقانون المنافسة لسنة 2004.","o":["تحدد كافة اسعار السلع والخدمات في السوق وفقاً لقواعد السوق ومبادئ المنافسه الحرة.","يحظر على كل منتج او مستورد او تاجر او مقدم خدمه ان يفرض بصوره مباشر او غير مباشره حد أدنى لإسعار إعادة بيع سلعة او خدمه.","يحظر على اي مؤسسة إعادة بيع منتج على حالته بسعر أقل من سعر شرائه الحقيقي مضافاً اليه الضرائب والرسوم، ولا يشمل هذا الحظر المنتجات سريعة التلف والتنزيلات المرخص بها لاي بيع يتم لتصفية الاعمال او تجديد المخزون بإسعار أقل.","تسري احكام هذا القانون على جميع انشطة الانتاج والتجارة والخدمات في المملكة كما تنصرف احكامه الى اي انشطة إقتصادية تتم خارج المملكة وتترتب عليها آثار داخلها."],"answer":0,"orig_answer":null,"law":"competition","article":"4","status":"valid","explanation":"المادة (4): تتحدد أسعار السلع والخدمات وفق قواعد السوق باستثناء أسعار المواد الأساسية والخدمات المحددة بقانون والأسعار المحددة بقرار مجلس الوزراء، فلا يصح القول (كافة الأسعار)."},{"num":70,"type":"mcq","q":"إن الشركة المعفاة هي:","o":["يمكن للشركة المعفاة بعد تسديد الرسوم المقررة عليها ان تطرح أسهمها للاكتتاب العام في حالة إذا أقامت شركة مساهمة عامة شريطة الالتزام بالأنظمة والتعليمات الصادرة عن هيئة الأوراق المالية وقانون الشركات.","يحق للشركة المعفاة أن تمارس أعمالها داخل وخارج المملكة شريطة ان تقوم بدفع رسوم سنوية تعادل بما لا يقل عن (20%) من ايراداتها السنوية كإيرادات للخزينة العامة.","الشركة المعفاة هي شركة مساهمة عامة أو شركة توصية بالأسهم أو شركة محدودة المسؤولية أو الشركات المساهمة الخاصة التي تسجل في المملكة وتزاول أعمالها خارجها ويضاف إلى اسمها عبارة (شركة معفاة) ويحظر عليها طرح أسهمها للاكتتاب العام في المملكة .","الشركة المعفاة هي الشركة التي يمكن تسجيلها بأي نوع من أنواع الشركات ويضاف على اسمها عبارة (شركة معفاة)."],"answer":null,"orig_answer":2,"law":"companies","article":"211","status":"changed","explanation":"المادة (211) المعدلة (سارية 2023/11/11): الشركة المعفاة شركة مساهمة عامة أو محدودة المسؤولية أو مساهمة خاصة فقط (حذفت التوصية بالأسهم)، ويحظر عليها طرح أسهمها للاكتتاب في المملكة؛ فالخيار (ج) لم يعد مطابقاً تماماً."},{"num":71,"essay_num":1,"type":"essay","q":"السؤال الأول (علامة واحدة): يوجد أربع حالات التي يلتزم البنك بأي منها بتخفيض المخصص المرصود مقابل الائتمان غير العامل، أذكر اثنتين منها؟","law":"income","article":"6","status":"valid","model_answer":"- المادة (6/ج/1) من قانون ضريبة الدخل: يلتزم البنك بتخفيض المخصص الخاص المرصود مقابل الائتمان غير العامل في أي من الحالات:\n  1) تحويل الائتمان غير العامل إلى ائتمان عامل وفق قانون البنوك.\n  2) تحصيل قيمة الائتمان غير العامل.\n  3) شطب قيمة الائتمان باعتباره ديناً هالكاً.\n  4) أي حالة أخرى يحددها البنك المركزي.\n- المادة (6/ج/2): يظهر البنك قيمة التخفيض المقبول سابقاً ضريبياً في دخله الإجمالي في الفترة التي جرى فيها التخفيض."},{"num":72,"essay_num":2,"type":"essay","q":"السؤال الثاني (علامتان): الشركة الأردنية تعمل في مجال بيع السيارات والإطارات ومركزها الرئيسي في عمان ولديها فرع في العقبة ولديك المعلومات التالية:\nأ. بلغت مبيعات الشركة 800 الف دينار (300 الف مبيعات عمان و 500 الف مبيعات فرع العقبة).\nب. بلغت المصاريف الكلية للشركة 255,000 دينار موزعة كما يلي (البيان: المركز الرئيسي (عمان) / فرع العقبة):\n- الإستهلاكات: 48,000 / 51,000\n- م. بيع وتوزيع: 22,800 / 25,600\n- م. إدارية: 12,000 / 19,200\n- م. تمويل: 37,200 / 39,200\n- المجموع: 120,000 / 135,000\nج. تم رد مبلغ (6,000 دينار) من المصاريف من قبل المدقق الضريبي بسبب عدم التعزيز.\nالمطلوب: إحتساب قيمة المصاريف المشتركة الواجب ردها من مصاريف المركز الرئيسي في عمان حسب المادة (9) من التعليمات التنفيذية رقم (8) لسنة 2015 بسبب ان بعض المصاريف المشتركة لا يمكن فصلها.","law":"income","article":"","status":"unverified","model_answer":"- تقوم الفكرة (تعليمات تنفيذية رقم 8 لسنة 2015، المادة 9) على توزيع المصاريف المشتركة للمركز الرئيسي التي لا يمكن فصلها على الأنشطة بنسبة إيرادات كل نشاط إلى إجمالي الإيرادات، ورد حصة النشاط ذي المعاملة الضريبية المختلفة (فرع العقبة).\n- نسبة مبيعات فرع العقبة = 500,000 ÷ 800,000 = 62.5%.\n- مصاريف المركز الرئيسي المقبولة قبل التوزيع = 120,000 − 6,000 (المردودة لعدم التعزيز) = 114,000 دينار.\n- المصاريف المشتركة الواجب ردها من مصاريف عمان = 114,000 × 62.5% = 71,250 ديناراً (وإذا وزع الإجمالي قبل رد الـ6,000 تكون 75,000 دينار).\n- ملاحظة: نص التعليمات غير متوفر للتحقق من طريقة المعالجة الدقيقة."},{"num":73,"essay_num":3,"type":"essay","q":"السؤال الثالث (علامتان): بتاريخ 2022/1/1 بلغت شركة الشركة حد التسجيل في الشبكة العامة لضريبة المبيعات وقررت التسجيل ولدى جرد المستودعات تبين ما يلي: كلفة البضاعة في المستودع عند الجرد 100,000 دينار ولتقديم كشوف الجرد التفصيلية لدائرة ضريبة الدخل والمبيعات وبالرجوع الى فواتير الشراء تبين النتائج التالية (الكلفة – تاريخ الشراء – نسبة الضريبة – المستندات):\n- 15000 – 2021/1 – 16% – فواتير ضريبية رسمية\n- 15000 – 2020/1 – 16% – فواتير ضريبية رسمية\n- 15000 – 2019/1 – 16% – فواتير ضريبية رسمية\n- 15000 – 2018/1 – 16% – فواتير ضريبية رسمية\n- 15000 – 2017/1 – 16% – فواتير ضريبية رسمية\n- 15000 – 2016/1 – 16% – فواتير ضريبية رسمية\n- 10000 – 2015/1 – 16% – فواتير غير ضريبية\nالمطلوب: إحتساب الضريبة الواجب تخصيمها عند التسجيل؟","law":"sales","article":"19","status":"valid","model_answer":"- المادة (19/د): للمسجل أن يخصم ما سبق أن تحمله قبل التسجيل من ضريبة عامة على السلع التي في حوزته عند التسجيل بشرط إثباتها بفواتير ضريبية.\n- البضاعة المؤيدة بفواتير ضريبية رسمية (2016–2021): 6 × 15,000 = 90,000 دينار × 16% = 14,400 دينار.\n- البضاعة المشتراة في 2015 بفواتير غير ضريبية (10,000 دينار) لا تخصم ضريبتها.\n- الضريبة الواجب تخصيمها عند التسجيل = 14,400 دينار (مع مراعاة أي قيد زمني تفرضه التعليمات التنفيذية على قدم الفواتير)."},{"num":74,"essay_num":4,"type":"essay","q":"السؤال الرابع (أربع علامات): شركة الاحبة مسجلة في شبكة الضريبة العامة على المبيعات ومن ضمن فترة اقرار ضريبة المبيعات 11+12/2021 ظهرت في حسابات الشركة المعطيات التالية:\n- مشتريات بضاعة قيمتها 25,000 دينار بنسبة ضريبة 16%.\n- مشتريات بضاعة معفاة قيمتها 30,000 دينار.\n- شراء اثاث لاستعمال الشركة بمبلغ 5,000 دينار وضريبة مبيعات 800 دينار.\n- شراء قرطاسية بقيمة 1,000 دينار وضريبة مبيعات 160 دينار.\n- مصاريف ضيافة بالشركة بقيمة 100 دينار وضريبة مبيعات 16 دينار.\n- مشتريات بضاعة مستوردة بقيمة 15,000 دينار وقيمتها التخمينية 18,000 دينار وجمارك 5,000 دينار وضريبة مبيعات بنسبة 16%.\n- مبيعات بقيمة 22,000 دينار خاضعة بنسبة 16%.\n- مبيعات قيمتها 16,000 دينار معفاة.\n- مبيعات قيمتها 8,000 دينار لجهات معفاة.\n- حساب امانات ضريبة المبيعات مدين في بداية الفترة بقيمة 1,500 دينار.\nالمطلوب: إحتساب رصيد امانات ضريبة المبيعات في فترة الاقرار الضريبي 11+12/2021.","law":"sales","article":"19","status":"valid","model_answer":"- ضريبة المخرجات: مبيعات خاضعة 22,000 × 16% = 3,520 دينار؛ المبيعات المعفاة (16,000) والمبيعات للجهات المعفاة (8,000) لا تحتسب عليها ضريبة.\n- ضريبة المدخلات القابلة للخصم (المادة 19/ج):\n  • مشتريات بضاعة 25,000 × 16% = 4,000\n  • أثاث لاستعمال الشركة = 800\n  • قرطاسية = 160\n  • بضاعة مستوردة: (18,000 + 5,000 جمارك) × 16% = 3,680 (المادة 15/ج)\n  • المجموع = 8,640 دينار.\n- غير قابل للخصم: ضريبة الضيافة 16 دينار (الجدول رقم 4)، ولا ضريبة على المشتريات المعفاة.\n- رصيد الأمانات = 1,500 (رصيد مدين أول المدة) + 8,640 − 3,520 = 6,620 دينار رصيد مدين (قابل للتدوير/الرد وفق المادة 20/ج).\n- ملاحظة: إذا طبقت نسبة التخصيص بسبب وجود مبيعات معفاة تخفض الضريبة المشتركة القابلة للخصم بنسبة المبيعات الخاضعة إلى إجمالي المبيعات."},{"num":75,"essay_num":5,"type":"essay","q":"السؤال الخامس (علامتان): اذكر أربع حالات تنقضي شركة التضامن بموجبها؟","law":"companies","article":"32","status":"valid","model_answer":"- المادة (32) من قانون الشركات: تنقضي شركة التضامن في أي من الحالات:\n  1) اتفاق الشركاء جميعهم على حلها أو دمجها في شركة أخرى.\n  2) انتهاء مدتها الأصلية أو الممددة.\n  3) انتهاء الغاية التي أسست من أجلها.\n  4) بقاء شريك واحد فيها (مع مراعاة المادة 28/د).\n  5) تصفيتها وشطب تسجيلها وفق قانون الإعسار.\n  6) إشهار إعسار أحد الشركاء أو الحجر عليه ما لم يقرر الباقون الاستمرار.\n  7) فسخها بحكم قضائي.\n  8) شطب تسجيلها بقرار من المراقب."},{"num":76,"essay_num":6,"type":"essay","q":"السؤال السادس (علامتان): اذكر اربع بيانات واجب أن يتضمنها نظام الشركة ذات المسؤولية المحدودة؟","law":"companies","article":"57","status":"valid","model_answer":"- المادة (57/ج): يجب أن يتضمن نظام الشركة ذات المسؤولية المحدودة بيانات عقد التأسيس (الاسم والغايات والمركز الرئيسي، أسماء الشركاء وجنسياتهم وعناوينهم، رأس المال وحصة كل شريك، الحصص العينية وقيمتها) إضافة إلى:\n  1) طريقة إدارة الشركة وعدد أعضاء هيئة المديرين وصلاحياتها بما فيها سقف الاستدانة والرهن والكفالة.\n  2) شروط وإجراءات التنازل عن الحصص.\n  3) كيفية توزيع الأرباح والخسائر.\n  4) اجتماعات الهيئة العامة وهيئة المديرين ونصابها وإجراءات الدعوة.\n  5) قواعد وإجراءات تصفية الشركة."},{"num":77,"essay_num":7,"type":"essay","q":"السؤال السابع (علامتان): اذكر الحالات التي تصفى الشركة المساهمة العامة بسببها تصفية اختيارية؟","law":"companies","article":"259","status":"valid","model_answer":"- المادة (259): تصفى الشركة المساهمة العامة تصفية اختيارية في الحالات:\n  1) انتهاء المدة المعينة لها ما لم تقرر الهيئة العامة تمديدها.\n  2) إتمام الغاية التي تأسست من أجلها أو استحالة إتمامها أو انتفاؤها.\n  3) صدور قرار من الهيئة العامة (غير العادية) بفسخها وتصفيتها.\n  4) الحالات الأخرى التي ينص عليها نظام الشركة."},{"num":78,"essay_num":8,"type":"essay","q":"السؤال الثامن (علامتان): الاوراق التجارية هي اسناد قابلة للتحويل بمقتضى احكام قانون التجارة رقم 12 لسنة 1966 اذكرها مع تعريف كل واحدة منها؟","law":"other:قانون التجارة رقم 12 لسنة 1966","article":"","status":"unverified","model_answer":"- الأوراق التجارية (أسناد قابلة للتحويل) ثلاثة:\n  1) سند السحب (البوليصة/الكمبيالة): محرر يأمر فيه الساحب المسحوب عليه بأن يدفع مبلغاً معيناً لأمر شخص ثالث (المستفيد) في تاريخ معين أو قابل للتعيين أو بمجرد الاطلاع.\n  2) السند لأمر (السند الإذني): محرر يتعهد فيه محرره بأن يدفع مبلغاً معيناً لأمر شخص آخر في تاريخ معين أو قابل للتعيين أو بمجرد الاطلاع.\n  3) الشيك: محرر يأمر فيه الساحب المسحوب عليه (بنك) بأن يدفع لدى الاطلاع مبلغاً معيناً لأمر شخص معين أو لحامله.\n- (القانون غير متوفر للتحقق من الصياغة الحرفية)."},{"num":79,"essay_num":9,"type":"essay","q":"السؤال التاسع (علامتان): تتولى الهيئة العليا لتنظيم مهنة المحاسبة القانونية المهام والصلاحيات المنصوص عليها بالمادة 5 من القانون أذكرها؟","law":"accounting","article":"5","status":"valid","model_answer":"- المادة (5) من قانون تنظيم مهنة المحاسبة القانونية: تتولى الهيئة العليا:\n  1) اعتماد معايير المحاسبة ومعايير التدقيق بتنسيب من المجلس.\n  2) تشكيل لجنة ترخيص المهنة ووضع تعليمات عملها والامتحانات.\n  3) المصادقة على منح إجازة المزاولة بتنسيب لجنة الترخيص وإلغاؤها بتنسيب المجلس.\n  4) النظر في الاعتراضات على قرارات المجلس.\n  5) تشكيل اللجان اللازمة لمساعدتها.\n  6) إصدار التعليمات اللازمة لتنظيم عملها وتنفيذ القانون والأنظمة.\n  7) إعداد مشروعات التشريعات المتعلقة بالمهنة بالتنسيق مع المجلس.\n  8) اعتماد المعاهد المهنية للمحاسبين القانونيين."},{"num":80,"essay_num":10,"type":"essay","q":"السؤال العاشر (علامة واحدة): متى يتولى وكيل الاعسار إدارة أعمال المعسر؟","law":"insolvency","article":"17","status":"valid","model_answer":"- المادة (17/ب): إذا كان طلب إشهار الإعسار مقدماً من الدائنين أو المراقب تعلق صلاحيات المدين ويمارسها وكيل الإعسار في حدود تسيير الأعمال المعتادة.\n- المادة (17/ج،هـ): أو إذا قررت المحكمة بطلب الدائنين أو وكيل الإعسار ولأسباب مبررة وقف صلاحية المدين في إدارة ذمة الإعسار.\n- المادة (17/و): عندها يكون وكيل الإعسار مسؤولاً عن ضمان استمرار الأعمال المعتادة للمدين."},{"num":81,"essay_num":11,"type":"essay","q":"السؤال الحادي عشر (علامة واحدة): لأي رقابة يخضع وكيل الاعسار؟","law":"insolvency","article":"52","status":"valid","model_answer":"- المادة (52/أ): يخضع عمل وكيل الإعسار لإشراف المحكمة ورقابة الدائنين أو من يمثلهم (لجنة الدائنين – المادة 48/ب/1).\n- المادة (52/ب): للمحكمة ولجنة الدائنين تكليفه بتقديم معلومات أو تقارير عن سير الإجراءات."},{"num":82,"essay_num":12,"type":"essay","q":"السؤال الثاني عشر (علامة واحدة): يحق للمؤمن له او المستفيد من عقد التأمين الانتفاع من شرط الاختراق ولا يجوز لاي جهة الاعتراض على تفعيله فما هو شرط الاختراق؟","law":"insurance","article":"71","status":"valid","model_answer":"- المادة (71/ب) من قانون تنظيم أعمال التأمين: شرط الاختراق هو الشرط الوارد في عقد إعادة التأمين الذي يقضي بمسؤولية معيد التأمين في حدود حصته من الخسارة المعاد تأمينها لديه تجاه المؤمن له والمستفيد في الحالات التي يتعذر فيها على المؤمن الوفاء بالتزاماته (كتصفية شركة التأمين)، بحيث تنشأ علاقة مباشرة بين معيد التأمين والمؤمن له والمستفيد."},{"num":83,"essay_num":13,"type":"essay","q":"السؤال الثالث عشر (علامتان): على البنك المركزي أن يحتفظ بموجودات لا تقل قيمتها في أي وقت من الأوقات عن قيمة أوراق النقد المتداولة؛ اذكر اربع من هذه الموجودات؟ (المادة 31/ قانون البنك المركزي الأردني رقم (23) لسنة 1971 وتعديلاته)","law":"other:قانون البنك المركزي الأردني رقم 23 لسنة 1971","article":"31","status":"unverified","model_answer":"- المادة (31) من قانون البنك المركزي (غير متوفر للتحقق): يحتفظ البنك المركزي مقابل النقد المتداول بموجودات منها:\n  1) الذهب.\n  2) العملات الأجنبية والأرصدة لدى البنوك المركزية والبنوك في الخارج.\n  3) الأوراق المالية الأجنبية القابلة للتداول.\n  4) سندات وأذونات الخزينة الأردنية (الأوراق المالية الحكومية).\n  5) حقوق السحب الخاصة/الشريحة الاحتياطية لدى صندوق النقد الدولي."},{"num":84,"essay_num":14,"type":"essay","q":"السؤال الرابع عشر (علامتان): عدد شروط استحقاق المؤمن عليه راتب العجز الكلي الدائم وفقاً لأحكام قانون الضمان الاجتماعي؟","law":"social","article":"67","status":"valid","model_answer":"- المادة (67/أ) من قانون الضمان الاجتماعي: يستحق المؤمن عليه راتب اعتلال العجز الكلي الطبيعي الدائم بشرط:\n  1) انتهاء خدمته.\n  2) تقديم طلب تخصيص الراتب خلال ستة أشهر من انتهاء الخدمة.\n  3) أن لا تقل اشتراكاته الفعلية عن (60) اشتراكاً منها (24) اشتراكاً متصلاً.\n  4) ثبوت العجز بقرار من المرجع الطبي.\n- (67/ب): لا يستحق عن حالات العجز السابقة لشموله بالقانون."},{"num":85,"essay_num":15,"type":"essay","q":"السؤال الخامس عشر (علامة واحدة): عدد شروط استحقاق المؤمن عليه راتب الوفاة وفقاً لأحكام قانون الضمان الاجتماعي؟","law":"social","article":"66","status":"valid","model_answer":"- المادة (66/أ): يستحق راتب تقاعد الوفاة الطبيعية إذا:\n  1) وقعت الوفاة خلال خدمته المشمولة بأحكام القانون.\n  2) سدد ما لا يقل عن (24) اشتراكاً فعلياً منها (6) اشتراكات متصلة."},{"num":86,"essay_num":16,"type":"essay","q":"السؤال السادس عشر (علامة واحدة): ما هو تعريف المعتمد حسب نظام العضوية في شركة بورصة عمان؟","law":"securities","article":"2","status":"valid","model_answer":"- تعريف المعتمد (المادة 2 من قانون الأوراق المالية، وبمعناه في أنظمة بورصة عمان): الشخص الطبيعي الذي يكون عضواً في مجلس إدارة شركة خدمات مالية أو هيئة مديريها أو مديراً أو مسؤولاً إدارياً أو موظفاً فيها، أو من يشغل وضعاً مشابهاً أو يمارس صلاحيات مماثلة لدى وسيط مالي أو وسيط لحسابه أو أمين استثمار أو مدير استثمار أو مستشار مالي أو مدير إصدار، ولا يشمل الوظائف المكتبية والخدماتية غير المتعلقة بنشاط الأوراق المالية.\n- (نظام العضوية في بورصة عمان غير متوفر للتحقق من صياغته)."},{"num":87,"essay_num":17,"type":"essay","q":"السؤال السابع عشر (علامتان): اذكر اربع من الممارسات التي قد يقوم بها المرخص له أو المعتمد وتكون مخالفة لقانون الأوراق المالية؟","law":"securities","article":"56","status":"valid","model_answer":"- المادة (56) من قانون الأوراق المالية: يعتبر مخالفة قيام المرخص له أو المعتمد بأي مما يلي:\n  1) إساءة التصرف بأموال العملاء أو المساهمين بما في ذلك إساءة توظيفها أو استخدامها.\n  2) ممارسة الخداع والتضليل والأعمال المحظورة.\n  3) التأثير سلباً على المنافسة بالتلاعب بنسب العمولات أو بدل الخدمات أو الحد من الخدمات منفرداً أو بالتواطؤ.\n  4) التأثير أو محاولة التأثير سلباً على سوق رأس المال منفرداً أو بالتواطؤ مع الغير."}]},{"id":"2022-07","year":2022,"month":7,"label":"دورة تموز 2022","session":"تموز","src":"e0bd6145.json","questions":[{"num":1,"type":"essay","q":"يشترط لإعفاء دخل الشركة المعفاة المسجلة وفقاً لقانون الشركات ما يلي:\n- أن لا يكون رأسمالها وأموالها المستثمرة من المملكة.\n- أن لا يكون الدخل المتأتي لها قد نشأ كلياً أو جزئياً عن أموال أو ودائع من المملكة.\n- أن تزاول أعمالها خارج المملكة وأن لا تمارس أي نشاط داخل المملكة بما في ذلك إبرام العقود.\n- أن لا يتأتى لها أي دخل من مصادر الدخل الخاضعة للضريبة وفقاً للقانون.","law":"income","article":"4","status":"changed","model_answer":"- المادة (4/ج/3) من قانون ضريبة الدخل النافذ: يعفى دخل الشركة المعفاة المسجلة بموجب قانون الشركات المتأتي لها من مزاولة أعمالها خارج المملكة، باستثناء الدخول المتأتية لها من مصادر الدخل الخاضعة للضريبة بموجب أحكام القانون.\n- النص الحالي لم يعد يعدد شرطي (عدم كون رأس المال والأموال المستثمرة من المملكة) و(عدم نشوء الدخل عن أموال أو ودائع من المملكة) كما ورد في الصياغة المدونة؛ ويبقى الشرط الجوهري: مزاولة الأعمال خارج المملكة واستثناء الدخل من المصادر الخاضعة.\n- تعريف الشركة المعفاة: المادة (211) من قانون الشركات."},{"num":2,"type":"essay","q":"يحظر على مدقق الحسابات وعلى موظفيه المضاربة بأسهم الشركة التي يدقق حساباتها سواء جرى هذا التعامل بالأسهم بصورة مباشرة أو غير مباشرة، وذلك تحت طائلة عزله من العمل في تدقيق حسابات الشركة وتضمينه التعويض عن أي ضرر ترتب على مخالفته لأحكام هذه المادة.","law":"companies","article":"203","status":"valid","model_answer":"- المادة (203): يحظر على المدقق وموظفيه المضاربة بأسهم الشركة التي يدققها مباشرة أو غير مباشرة.\n- الجزاء: عزله من تدقيق حسابات الشركة وتضمينه التعويض عن أي ضرر."},{"num":3,"type":"essay","q":"تصفى الشركة المساهمة العامة تصفية اختيارية في أي من الحالات التالية:\nأ- بانتهاء المدة المعينة للشركة ما لم تقرر الهيئة العامة تمديدها.\nب- بإتمام أو انتفاء الغاية التي تأسست الشركة من أجلها أو باستحالة إتمام هذه الغاية أو انتفائها.\nج- بصدور قرار من الهيئة العامة للشركة بفسخها وتصفيتها.\nد- في الحالات الأخرى التي ينص عليها نظام الشركة.","law":"companies","article":"259","status":"valid","model_answer":"- المادة (259): حالات التصفية الاختيارية للمساهمة العامة: انتهاء المدة ما لم تمدد، إتمام الغاية أو انتفاؤها أو استحالتها، قرار الهيئة العامة بالفسخ والتصفية، الحالات الأخرى في نظام الشركة.\n- المادة (252/أ): التصفية الاختيارية تكون من الهيئة العامة غير العادية."},{"num":4,"type":"essay","q":"الشركاء الموصون: ويشاركون في رأس المال دون أن يحق لهم إدارة الشركة أو ممارسة أعمالها، ويكون كل منهم مسؤولاً عن ديون الشركة والالتزامات المترتبة عليها بمقدار حصته في رأس مال الشركة.","law":"companies","article":"41","status":"valid","model_answer":"- المادة (41/ب): الشركاء الموصون يشاركون في رأس المال دون حق الإدارة، ومسؤولية كل منهم بمقدار حصته.\n- المادة (41/أ): الشركاء المتضامنون يديرون الشركة ومسؤولون بالتضامن والتكافل في أموالهم الخاصة."},{"num":5,"type":"essay","q":"يكون رأسمال الشركة المساهمة الخاصة هو مجموع القيم الاسمية لأسهم الشركة على أن لا يقل رأس المال المكتتب به عن خمسين ألف دينار أردني.","law":"companies","article":"66 مكرر","status":"valid","model_answer":"- المادة (66 مكرر/أ): رأسمال المساهمة الخاصة مجموع القيم الاسمية للأسهم، وحد أدنى للمكتتب به (50,000) دينار.\n- (66 مكرر/ب): يحدد بالدينار الأردني."},{"num":6,"type":"essay","q":"أ- إذا ارتكبت الشركة المساهمة العامة أو شركة التوصية بالأسهم أو الشركة المحدودة المسؤولية أو المساهمة الخاصة مخالفة لأحكام هذا القانون تعاقب بغرامة لا تقل عن ألف دينار ولا تتجاوز عشرة آلاف دينار مع إبطال التصرف المخالف إذا رأت المحكمة وجهاً لذلك.\nب- إذا ظهر أن أياً من الشركات المنصوص عليها في الفقرة (أ) من هذه المادة لم تحفظ دفاتر حسابات منظمة قبل تصفيتها يعتبر مديرها ومدقق حساباتها قد ارتكب جرماً يعاقب عليه بالحبس مدة لا تقل عن شهر ولا تزيد على سنة.","law":"companies","article":"279","status":"changed","model_answer":"- المادة (279/أ) النافذة: الغرامة (1000–10000) دينار مع إبطال التصرف المخالف، وتسري على المساهمة العامة والمحدودة المسؤولية والمساهمة الخاصة فقط؛ لم تعد شركة التوصية بالأسهم مذكورة في النص الحالي.\n- (279/ب): عدم حفظ دفاتر منظمة قبل التصفية: حبس المدير والمدقق من شهر إلى سنة (دون تغيير)."},{"num":7,"type":"essay","q":"يعتبر مدقق الحسابات الذي يخالف أحكام هذا القانون بتقديم تقارير أو بيانات لا تتفق وواقع حسابات الشركة التي قام بتدقيقها أنه ارتكب جرماً ويعاقب عليه بالحبس مدة لا تقل عن ستة أشهر ولا تزيد على ثلاث سنوات أو بغرامة لا تقل عن ألف دينار أو بكلتا العقوبتين، ولا يحول ذلك دون تعرضه للعقوبات المسلكية المقررة في القوانين الخاصة بالمهنة المعمول بها.","law":"companies","article":"280","status":"valid","model_answer":"- المادة (280): الحبس من 6 أشهر إلى 3 سنوات أو غرامة لا تقل عن 1000 دينار أو كلتاهما، إضافة إلى العقوبات المسلكية."},{"num":8,"type":"essay","q":"ينشأ حق المساهم في الأرباح بصدور قرار الهيئة العامة بتوزيعها.","law":"companies","article":"191","status":"valid","model_answer":"- المادة (191/أ) للمساهمة العامة و(87 مكرر/ج) للمساهمة الخاصة: ينشأ الحق بصدور قرار الهيئة العامة بالتوزيع.\n- الحق في استيفاء الربح لمالك السهم بتاريخ اجتماع الهيئة العامة؛ الدفع خلال 45 يوماً (عامة) أو 60 يوماً (خاصة)."},{"num":9,"type":"essay","q":"الإعسار الوشيك: الحالة التي يتوقع فيها أن يفقد المدين القدرة المستقبلية على سداد ديونه عند استحقاقها خلال ستة أشهر رغم قدرته الحالية على سدادها.","law":"insolvency","article":"2","status":"valid","model_answer":"- المادة (2): تعريف الإعسار الوشيك: توقع فقدان القدرة المستقبلية على السداد خلال ستة أشهر رغم القدرة الحالية.\n- المادة (7/ب): لا تسري مدة الشهرين لتقديم الطلب على طلب إشهار الإعسار الوشيك."},{"num":10,"type":"essay","q":"تجتمع الهيئة العامة للدائنين بناء على دعوة وكيل الإعسار إما من تلقاء نفسه أو بناء على طلب لجنة الدائنين أو دائنين يمثلون (20%) على الأقل من إجمالي الديون.","law":"insolvency","article":"44","status":"valid","model_answer":"- المادة (44/أ): الدعوة من وكيل الإعسار من تلقاء نفسه أو بطلب لجنة الدائنين أو دائنين يمثلون 20% على الأقل من إجمالي الديون.\n- (44/ب): يجب دعوتها في كل الأحوال لمناقشة خطة إعادة التنظيم والتصويت عليها."},{"num":11,"type":"essay","q":"يجب على التاجر أن يحفظ الدفاتر بعد اختتامها مدة عشر سنوات.","law":"other:قانون التجارة","article":"","status":"unverified","model_answer":"- قانون التجارة رقم (12) لسنة 1966 (المادة 18 تقريباً): يحفظ التاجر الدفاتر بعد اختتامها مدة عشر سنوات، والمراسلات والبرقيات والفواتير المدة ذاتها."},{"num":12,"type":"essay","q":"يجب على كل تاجر أن ينظم على الأقل الدفاتر الثلاثة الآتية:\nأ- دفتر اليومية، ويجب أن يقيد فيه يوماً فيوماً جميع الأعمال التي تعود بوجه من الوجوه إلى عمله التجاري، وأن يقيد بالجملة شهراً فشهراً النفقات التي أنفقها على نفسه وأسرته.\nب- دفتر صور الرسائل، ويجب أن تنسخ فيه الرسائل والبرقيات التي يرسلها، كما يحفظ به ويرتب الرسائل أو البرقيات التي يتلقاها.\nج- دفتر الجرد والميزانية اللذان يجب تنظيمهما مرة على الأقل في كل سنة.","law":"other:قانون التجارة","article":"","status":"unverified","model_answer":"- قانون التجارة 1966 (المادة 16): الدفاتر الإلزامية: دفتر اليومية، دفتر صور الرسائل، دفتر الجرد والميزانية (مرة سنوياً على الأقل)."},{"num":13,"type":"essay","q":"تخضع الشركات المرخصة أو المسجلة بمقتضى قانون الشركات الساري المفعول إلى إجراءات التصفية والفسخ الواردة فيه، كما تخضع الشركات المدنية الأخرى إلى قواعد التصفية الواردة في القانون المدني.","law":"other:قانون التجارة","article":"","status":"unverified","model_answer":"- قانون التجارة 1966: الشركات المسجلة بموجب قانون الشركات تخضع لأحكام التصفية والفسخ فيه، والشركات المدنية الأخرى لقواعد القانون المدني.\n- مع مراعاة قانون الإعسار رقم (21) لسنة 2018 عند الإعسار."},{"num":14,"type":"essay","q":"سند السحب ويسمى أيضاً البوليصة أو السفتجة: وهو محرر مكتوب وفق شرائط مذكورة في القانون ويتضمن أمراً صادراً من شخص هو الساحب إلى شخص آخر هو المسحوب عليه بأن يدفع لأمر شخص ثالث هو المستفيد أو حامل السند مبلغاً معيناً بمجرد الاطلاع أو في ميعاد معين أو قابل للتعيين.","law":"other:قانون التجارة","article":"","status":"unverified","model_answer":"- قانون التجارة 1966 (المادة 123): سند السحب (البوليصة/السفتجة) ثلاثي الأطراف: ساحب، مسحوب عليه، مستفيد."},{"num":15,"type":"essay","q":"سند الأمر ويسمى أيضاً السند الإذني ومعروف باسم الكمبيالة: وهو محرر مكتوب وفق شرائط مذكورة في القانون ويتضمن تعهد محرره بدفع مبلغ معين بمجرد الاطلاع أو في ميعاد معين أو قابل للتعيين لأمر شخص آخر هو المستفيد أو حامل السند.","law":"other:قانون التجارة","article":"","status":"unverified","model_answer":"- قانون التجارة 1966 (المادة 123): سند الأمر (الكمبيالة) ثنائي الأطراف: محرر يتعهد بالدفع، ومستفيد."},{"num":16,"type":"essay","q":"يستحق المؤمن عليه راتب تقاعد الشيخوخة شريطة تحقق ما يلي:\n1- إكمال المؤمن عليه الذكر سن الستين والمؤمن عليها الأنثى سن الخامسة والخمسين.\n2- أن تكون اشتراكاته في هذا التأمين (180) اشتراكاً على الأقل منها (84) اشتراكاً فعلياً.","law":"social","article":"62","status":"valid","model_answer":"- المادة (62/أ): السن 60 للذكر و55 للأنثى، و180 اشتراكاً منها 84 فعلياً.\n- (62/ب): الاحتساب 2.5% لأول 1500 دينار من متوسط أجر آخر 36 اشتراكاً و2% للباقي."},{"num":17,"type":"essay","q":"لا تخضع الفئات التالية لأحكام هذا القانون:\n1- الأشخاص الذين يؤدون اشتراكات تقاعدية وفق أحكام قانون التقاعد المدني أو قانون التقاعد العسكري.\n2- الأشخاص غير الأردنيين العاملون لدى البعثات الإقليمية والدولية والبعثات السياسية أو العسكرية العربية والأجنبية العاملة في المملكة والملحقيات والمراكز الفنية والتعليمية التابعة لها.\n3- العمال الذين تكون علاقتهم بصاحب العمل غير منتظمة، وتعتبر العلاقة منتظمة وفقاً لما يلي:\nأ- للعامل في المياومة إذا عمل ستة عشر يوماً فأكثر في الشهر الواحد.\nب- للعامل بالساعة أو بالقطعة أو بالنقلة أو من في حكمهم إذا عمل ستة عشر يوماً فأكثر في الشهر الواحد بغض النظر عن عدد ساعات العمل أو القطع أو النقلات في اليوم الواحد.\nج- للعامل الذي يتقاضى أجراً شهرياً بغض النظر عن عدد أيام عمله في الشهر الواحد باستثناء الشهر الأول لالتحاقه بالعمل فيتم تطبيق مبدأ ستة عشر يوم عمل فأكثر في الشهر الواحد.","law":"social","article":"4","status":"valid","model_answer":"- المادة (4/ب): الفئات المستثناة: الخاضعون للتقاعد المدني/العسكري، غير الأردنيين العاملون لدى البعثات، العمال غير المنتظمين.\n- العلاقة منتظمة عند العمل 16 يوماً فأكثر شهرياً (المياومة/الساعة/القطعة)، وللأجر الشهري بغض النظر عن الأيام عدا الشهر الأول."},{"num":18,"type":"essay","q":"على الرغم من أي نص آخر، لا يصرف بدل التعطل عن العمل أو أي جزء منه في الحالات التالية:\nأ- للمؤمن عليه الأردني إذا أصبح رصيد حسابه الادخاري قبل مدة استحقاقه لبدل التعطل أو خلالها مديناً بأكثر من ثلاثة أضعاف متوسط الأجر الذي احتسبت الاشتراكات على أساسه خلال الستة وثلاثين اشتراكاً الأخيرة شريطة أن لا يكون تخلف المنشأة عن دفع الاشتراكات سبباً في هذا الرصيد المدين.\nب- للمؤمن عليه غير الأردني إذا لم يكن له رصيد دائن في حسابه الادخاري.","law":"social","article":"58","status":"valid","model_answer":"- المادة (58): لا يصرف بدل التعطل للأردني إذا صار رصيد حسابه الادخاري مديناً بأكثر من 3 أضعاف متوسط أجر آخر 36 اشتراكاً (ما لم يكن السبب تخلف المنشأة)، ولغير الأردني إذا لم يكن له رصيد دائن."},{"num":19,"type":"essay","q":"للمؤمن عليه أو لذويه الحق في إشعار المؤسسة بإصابة العمل خلال مدة لا تتجاوز أربعة أشهر من تاريخ وقوعها إذا لم تقم المنشأة بإشعار المؤسسة بها.","law":"social","article":"27","status":"valid","model_answer":"- المادة (27/د): مدة إشعار المؤمن عليه أو ذويه أربعة أشهر من تاريخ وقوع الإصابة إذا لم تشعر المنشأة.\n- (27/هـ): تتحمل المؤسسة رواتب الاعتلال وتقاعد الوفاة الإصابية ولو أشعرت بعد أربعة أشهر (مع مراعاة 27/ج)."},{"num":20,"type":"essay","q":"أ- على المنشأة أن تؤدي الاشتراكات المقتطعة من أجور المؤمن عليهم العاملين لديها والاشتراكات التي تؤديها لحسابهم إلى المؤسسة خلال الخمسة عشر يوماً الأولى من الشهر التالي للاستحقاق، وفي حالة تأخرها تدفع فائدة تأخير قدرها (واحد بالمائة) شهرياً عن أي من الاشتراكات التي تأخرت عن أدائها. (تم وقف العمل بأحكام هذه الفقرة بموجب أمر الدفاع رقم (1) لسنة 2020).\nب- تلتزم المنشأة بدفع غرامة قدرها (واحد بالمائة) من الاشتراكات المستحقة عن كل شهر تتأخر فيه عن تزويد المؤسسة بالبيانات الواردة في الفقرة (أ) من المادة (21) من هذا القانون.","law":"social","article":"22","status":"valid","model_answer":"- المادة (22/أ): أداء الاشتراكات خلال 15 يوماً من الشهر التالي، وفائدة تأخير 1% شهرياً (وقف أمر الدفاع رقم 1 لسنة 2020 كان مؤقتاً وانتهى بانتهاء العمل بقانون الدفاع).\n- (22/ب): غرامة 1% عن كل شهر تأخير في تزويد البيانات وفق المادة (21/أ).\n- (22/ج): غرامة 30% عند عدم الاقتطاع أو عدم الأداء على الأجور الحقيقية."},{"num":21,"type":"essay","q":"لا يعد تاجراً من قام بمعاملة تجارية عرضاً، إلا أن المعاملة المذكورة تكون خاضعة لأحكام قانون التجارة.","law":"other:قانون التجارة","article":"","status":"unverified","model_answer":"- قانون التجارة 1966 (المادة 10): من قام بعمل تجاري عرضاً لا يعد تاجراً، لكن المعاملة تخضع لأحكام قانون التجارة."},{"num":22,"type":"essay","q":"1- في المواد التجارية يستحق الوكيل الأجر في جميع الأحوال ما لم يكن هناك نص مخالف.\n2- وإذا لم يحدد هذا الأجر في الاتفاق فيعين بحسب تعريفة المهنة أو بحسب العرف أو الظرف.","law":"other:قانون التجارة","article":"","status":"unverified","model_answer":"- قانون التجارة 1966 (الوكالة التجارية): الوكالة التجارية مأجورة أصلاً ما لم يتفق على خلافه، ويحدد الأجر غير المتفق عليه بالتعريفة المهنية أو العرف أو الظروف."},{"num":23,"type":"essay","q":"الوكالة التجارية وإن احتوت على توكيل مطلق لا تجيز الأعمال غير التجارية إلا بنص صريح.","law":"other:قانون التجارة","article":"","status":"unverified","model_answer":"- قانون التجارة 1966: التوكيل المطلق في الوكالة التجارية يقتصر على الأعمال التجارية، والأعمال غير التجارية تحتاج نصاً صريحاً."},{"num":24,"type":"essay","q":"الوكيل الذي لم يتلق تعليمات إلا في شأن جزء من العمل يعد مطلق اليد في الجزء الباقي.","law":"other:قانون التجارة","article":"","status":"unverified","model_answer":"- قانون التجارة 1966: الوكيل مطلق اليد في الجزء الذي لم يتلق بشأنه تعليمات."},{"num":25,"type":"essay","q":"تتولى الهيئة العليا المصادقة على منح إجازة المزاولة بناء على تنسيب لجنة الترخيص، وإلغاء هذه الإجازة بناء على تنسيب المجلس.","law":"accounting","article":"5","status":"valid","model_answer":"- المادة (5/ج): المصادقة على منح الإجازة بتنسيب لجنة الترخيص، وإلغاؤها بتنسيب المجلس.\n- (5/ب): الهيئة العليا تشكل لجنة ترخيص المهنة."},{"num":26,"type":"essay","q":"عقد التأمين: اتفاق تلتزم بمقتضاه شركة التأمين أن تؤدي إلى المؤمن له أو إلى المستفيد عوضاً مالياً أو أي منفعة أخرى عند تحقق الخطر المؤمن منه أو حدوث الواقعة المحددة في العقد مقابل مبلغ محدد أو أقساط يؤديها المؤمن له إلى شركة التأمين.","law":"insurance","article":"2","status":"valid","model_answer":"- المادة (2) من قانون تنظيم أعمال التأمين رقم (12) لسنة 2021: تعريف عقد التأمين كما ورد (عوض مالي أو منفعة مقابل مبلغ محدد أو أقساط)."},{"num":27,"type":"essay","q":"تعتبر الأنشطة التالية من أنشطة التأجير وتخضع لأحكام هذا القانون:\nأ- عملية البيع وإعادة الاستئجار التي تتمثل بقيام المورد ببيع المال إلى المؤجر ومن ثم إعادة استئجاره من قبل المورد بموجب أحكام هذا القانون.\nب- التأجير اللاحق الذي يتمثل بإعادة تأجير المأجور من قبل المؤجر إلى مستأجر جديد بعد فسخ عقد التأجير مع مستأجر سابق.\nج- التأجير من الباطن الذي يتمثل بقيام المستأجر (المؤجر من الباطن) بموافقة خطية مسبقة من المؤجر بتأجير المأجور إلى شخص ثالث (المستأجر من الباطن) مقابل بدل إيجار.","law":"leasing","article":"","status":"unverified","model_answer":"- قانون التأجير التمويلي رقم (45) لسنة 2008 (المادة 4 تقريباً): من أنشطة التأجير: البيع وإعادة الاستئجار، التأجير اللاحق، التأجير من الباطن بموافقة خطية مسبقة من المؤجر.\n- لم يتوفر نص القانون الحالي للتحقق."},{"num":28,"type":"essay","q":"للمرخص له بالتمويل على الهامش تحديد حقوقه المتعلقة بالأوراق المالية الخاصة بأي من عملائه دون الرجوع إليه في أي من الحالات التالية:\n1- وفاة العميل.\n2- صدور قرار بتصفية العميل، أو شهر إفلاسه أو الحجر عليه.\n3- صدور أمر حجز عن سلطة مختصة على الأوراق المالية العائدة لعميله.","law":"securities","article":"55","status":"valid","model_answer":"- المادة (55/د) من قانون الأوراق المالية لسنة 2017: الحالات: وفاة العميل، تصفيته أو إفلاسه أو الحجر عليه، أمر حجز على أوراقه المالية.\n- (55/ج): للممول حق التقدم على سائر دائني العميل في الأوراق الممولة."},{"num":29,"type":"essay","q":"عرض التملك العام: أي عرض يقصد به شراء (40%) أو أكثر من الأوراق المالية العائدة إلى مصدر واحد، أو حيازتها عن طريق المبادلة.","law":"securities","article":"2","status":"valid","model_answer":"- المادة (2): عرض التملك العام = شراء 40% أو أكثر من أوراق مصدر واحد أو حيازتها بالمبادلة.\n- العرض العام: لأكثر من 30 شخصاً من الجمهور."},{"num":30,"type":"essay","q":"يصدر المجلس قراره بمنح الترخيص أو الاعتماد أو رفض أي منهما خلال ستين يوماً من تاريخ تقديم الطلب إليها مستكملاً الشروط والمتطلبات.","law":"securities","article":"48","status":"valid","model_answer":"- المادة (48/هـ): قرار المجلس بالترخيص أو الاعتماد أو الرفض خلال 60 يوماً من تقديم الطلب مستكملاً."},{"num":31,"type":"essay","q":"يتولى المجلس (مجلس مفوضي الهيئة) إعداد مشروعات القوانين والأنظمة المتعلقة بالأوراق المالية.","law":"securities","article":"12","status":"valid","model_answer":"- المادة (12/ق): من مهام المجلس إعداد مشروعات القوانين والأنظمة المتعلقة بالأوراق المالية."},{"num":32,"type":"essay","q":"يقوم البنك المركزي بالنيابة عن الحكومة أو المؤسسة العامة بما يلي:\n1- حفظ الودائع والحسابات.\n2- إدارة إصدارات الأوراق المالية الحكومية المطروحة للاكتتاب.\n3- دفع أية أموال في المملكة أو خارجها، وتحويلها وتحصيلها وقبولها كأمانة وفتح الاعتمادات المستندية.\n4- شراء الشيكات والأسناد والأوراق المالية والذهب والفضة والعملات الأجنبية وبيعها أو تحويلها أو قبولها كأمانة.\n5- القيام بأية خدمات مصرفية أخرى.","law":"other:قانون البنك المركزي الأردني","article":"","status":"unverified","model_answer":"- قانون البنك المركزي الأردني رقم (23) لسنة 1971: البنك المركزي بنك الحكومة ووكيلها المالي؛ يقوم نيابة عنها بالخدمات المصرفية المذكورة (حفظ الودائع، إدارة الإصدارات الحكومية، الدفع والتحويل وفتح الاعتمادات، شراء وبيع الشيكات والأسناد والذهب والعملات، وأي خدمات مصرفية أخرى)."},{"num":33,"type":"essay","q":"يقوم مجلس الوزراء بناء على تنسيب المجلس بتعيين مدققين خارجيين لتدقيق حسابات البنك المركزي وتصديق الميزانية السنوية العامة وحساب الأرباح والخسائر، ويحدد مجلس الوزراء أجور هؤلاء المدققين.","law":"other:قانون البنك المركزي الأردني","article":"","status":"unverified","model_answer":"- قانون البنك المركزي الأردني: تعيين المدققين الخارجيين وتحديد أجورهم من مجلس الوزراء بتنسيب مجلس إدارة البنك المركزي."},{"num":34,"type":"essay","q":"أ- تفرض غرامة على المكلف بدفع الرسم المقرر إذا تأخر عن دفعه في الموعد المحدد وعلى النحو التالي:\n1- (1%) من الرسم المستحق أو من مقدار النقص عما تم دفعه من الرسم عن الأسبوع الأول من التأخير وبحد أدنى مقداره دينار واحد.\n2- (50%) من الرسم أو مقدار النقص فيه في حال التأخير لمدة تزيد على سبعة أيام ولا تتجاوز ثلاثين يوماً وبحد أدنى مقداره دينار واحد.\n3- مثل الرسم المستحق أو مقدار النقص فيه إذا كان التأخير لمدة تزيد على ثلاثين يوماً ولا تتجاوز ستين يوماً وبحد أدنى مقداره دينار واحد.\n4- مثلا الرسم المستحق أو مقدار النقص فيه إذا زادت مدة التأخير لدفع الرسم على ستين يوماً وبحد أدنى مقداره دينار واحد.\nب- 1- تفرض على الموظف الذي أجاز المعاملة دون أن يكون الرسم مدفوعاً أو تم دفعه ناقصاً غرامة تعادل مقدار الرسوم غير المدفوعة أو الناقصة وبحد أدنى مقداره دينار واحد.\n2- تفرض على الموظف الذي لم يبطل الطوابع على المعاملة بالصورة التي حددها القانون غرامة تعادل مثل مقدار الرسم المقرر وبحد أدنى مقداره دينار واحد.","law":"stamp","article":"12","status":"valid","model_answer":"- المادة (12/أ): غرامات التأخير: 1% للأسبوع الأول، 50% (8–30 يوماً)، مثل الرسم (31–60 يوماً)، مثلا الرسم (أكثر من 60 يوماً)، وبحد أدنى دينار.\n- (12/ب): الموظف المجيز دون دفع: غرامة تعادل الرسم غير المدفوع؛ عدم إبطال الطوابع: مثل الرسم.\n- (12/ج): الإعفاء من الوزير حتى 10,000 دينار، ومجلس الوزراء فوق ذلك."},{"num":35,"type":"essay","q":"أ- للوزير أن يقرر إعادة الرسوم المستوفاة في أي من الحالات التالية:\n1- إذا تلفت الطوابع التي في حيازة أي شخص دون أي تقصير متعمد منه وكان التلف واقعاً بصورة يتعذر معها استعمالها.\n2- إذا ألصق المكلف طوابع أو دمغها بمبلغ يزيد على الرسم المستحق على المعاملة.\n3- إلغاء المعاملة الخاضعة لرسوم الطوابع.\nب- يحسم لحساب الخزينة ما نسبته (10%) من مقدار الرسوم التي يتم إعادتها وفقاً لأحكام الفقرة (أ) من هذه المادة.","law":"stamp","article":"16","status":"valid","model_answer":"- المادة (16/أ): حالات الإعادة: تلف الطوابع دون تقصير متعمد، الإلصاق أو الدمغ بأزيد من المستحق، إلغاء المعاملة.\n- (16/ب): يحسم 10% لحساب الخزينة من الرسوم المعادة."},{"num":36,"type":"essay","q":"إذا وقع خلاف في الرأي بين الديوان وإحدى الوزارات أو الدوائر يعرض موضوع الخلاف على مجلس الوزراء للفصل فيه، وعلى رئيس الديوان أن يضمن تقريره إلى مجلس النواب المسائل التي وقع الخلاف حولها.","law":"audit","article":"23","status":"valid","model_answer":"- المادة (23): يفصل مجلس الوزراء في الخلاف، ويضمن رئيس الديوان المسائل الخلافية في تقريره إلى مجلس النواب."},{"num":37,"type":"essay","q":"لا يجوز تفتيش مقر الهيئة إلا بأمر قضائي وبحضور المدعي العام المختص على أن يتم تبليغ الرئيس بذلك ودعوة من يمثل الهيئة لحضور التفتيش، ويعتبر باطلاً أي إجراء مخالف لذلك.","law":"integrity","article":"5","status":"valid","model_answer":"- المادة (5/ب): تفتيش مقر الهيئة بأمر قضائي وبحضور المدعي العام المختص مع تبليغ الرئيس ودعوة ممثل للهيئة، وإلا بطل الإجراء.\n- (5/أ): تمارس الهيئة مهامها بحرية واستقلال."}]},{"id":"2022-02","year":2022,"month":2,"label":"دورة شباط 2022","session":"شباط","src":"5d334b48.json","questions":[{"num":1,"type":"mcq","q":"يُعرف الدخل الخاضع للضريبة:","o":["ما تبقى من الدخل الصافي بعد تنزيل المصاريف المقبولة والخسارة المدورة من الفترات الضريبية السابقة والتبرعات والإعفاءات الشخصية على التوالي.","ما تبقى من الدخل الصافي بعد تنزيل المصاريف المقبولة والخسارة المدورة من الفترات الضريبية السابقة والإعفاءات الشخصية والتبرعات على التوالي.","الدخل الإجمالي بعد تنزيل المصاريف والخسارة المدورة من الفترات السابقة والتبرعات والإعفاءات.","الدخل الإجمالي بعد تنزيل المصاريف والخسارة المدورة من الفترات السابقة."],"answer":1,"orig_answer":null,"law":"income","article":"2","status":"valid","explanation":"المادة (2): الدخل الخاضع للضريبة ما يتبقى من الدخل الصافي بعد تنزيل الخسارة المدورة والإعفاءات الشخصية والتبرعات على التوالي، وهو الترتيب الوارد في (ب)."},{"num":2,"type":"mcq","q":"أي من العبارات التالية صحيحة حسب قانون ضريبة الدخل (الشركة المالية):","o":["الشركة المرخصة لممارسة الأعمال المصرفية في المملكة بما في ذلك شركة الصرافة وشركة التمويل وفقاً لقانون البنك.","الشركة المالية المعرفة وفقاً لقانون ضريبة الدخل بما في ذلك شركة الصرافة وشركة التمويل.","الشركة المالية المعرفة وفقاً لقانون البنك المركزي بما في ذلك شركة الصرافة وشركة التمويل.","الشركة المالية المعرفة وفقاً لقانون البنوك بما في ذلك شركة الصرافة وشركة التمويل."],"answer":3,"orig_answer":null,"law":"income","article":"2","status":"valid","explanation":"المادة (2): الشركة المالية هي الشركة المالية المعرفة وفقاً لقانون البنوك بما في ذلك شركة الصرافة وشركة التمويل."},{"num":3,"type":"mcq","q":"أي من العبارات التالية خطأ حسب قانون ضريبة الدخل:","o":["تستوفى الضريبة عن الدخل الخاضع للضريبة بنسبة 24% عن كل دينار لشركات توزيع الكهرباء وشركات تعدين المواد الأساسية وشركات التأمين وشركات إعادة التأمين وشركات الوساطة المالية والشركات المالية والأشخاص الاعتباريين الذين يمارسون أنشطة التأجير التمويلي.","تستوفى الضريبة عن الدخل الخاضع للضريبة بنسبة 35% عن كل دينار للبنوك.","تستوفى الضريبة عن الدخل الخاضع للضريبة بنسبة 24% عن كل دينار لجميع شركات الاتصالات.","تستوفى الضريبة عن الدخل الخاضع للضريبة بنسبة 20% عن كل دينار لجميع الأشخاص الاعتباريين باستثناء ما ورد في (أ+ج)."],"answer":2,"orig_answer":null,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ب/2): نسبة 24% تخص شركات الاتصالات الأساسية فقط وليس جميع شركات الاتصالات، لذا (ج) خطأ."},{"num":4,"type":"mcq","q":"الدخل التالي يخضع للضريبة باستثناء:","o":["الدخل الناجم عن التجارة الالكترونية للسلع والخدمات.","الدخل التالي لشركات رأس المال المغامر المعرفة والمسجلة وفق قانون الشركات.","الدخل الصافي الذي يتحقق للشخص المقيم من أي مصدر خارج المملكة شريطة أن يكون قد نشأ عن أموال أو ودائع من المملكة.","بدل الخدمة الذي يجنيه الشخص غير المقيم من المملكة والناشئ عن خدمة قدمها لأي شخص إذا تمت مزاولة العمل أو النشاط المتعلق بذلك اليد في المملكة أو إذا تم استخدام مخرجات هذه الخدمة داخلها."],"answer":1,"orig_answer":null,"law":"income","article":"4","status":"valid","explanation":"المادة (4/أ/6): يعفى الدخل المتأتي لشركات رأس المال المغامر المعرفة والمسجلة وفق قانون الشركات."},{"num":5,"type":"mcq","q":"حسب قانون ضريبة الدخل النشاط الزراعي يعني التالي باستثناء:","o":["تربية الأسماك والطيور والنحل بما في ذلك إنتاج البيض والعسل.","إنتاج المحاصيل والحبوب والخضروات والفواكه والنباتات والزهور والأشجار.","تربية وتجارة المواشي والأسماك والطيور.","لا شيء مما ذكر."],"answer":2,"orig_answer":null,"law":"income","article":"5","status":"valid","explanation":"المادة (5/ج): النشاط الزراعي يشمل إنتاج المحاصيل وتربية المواشي والأسماك والطيور والنحل، ولا يشمل تجارة المواشي."},{"num":6,"type":"mcq","q":"أرباح شركات إعادة التأمين غير العاملة في المملكة الناجمة في المملكة عن عقود التأمين التي تبرمها معها شركات التأمين العاملة في المملكة تخضع بنسبة:","o":["معفاة من ضريبة الدخل.","20%.","10%.","15%."],"answer":0,"orig_answer":null,"law":"income","article":"4","status":"valid","explanation":"المادة (4/أ/17): تعفى أرباح شركات إعادة التأمين غير العاملة في المملكة الناجمة عن عقود التأمين مع شركات التأمين العاملة فيها."},{"num":7,"type":"mcq","q":"حسب قانون ضريبة الدخل في حال تملك إحدى الشركات كلياً أو جزئياً نسبة لا تقل عن 10% من رأسمال شركة أخرى فلا يجوز تقاضي الضريبة عن أرباح الشركة المالكة للشركة المملوكة بنسبة تزيد على:","o":["20% من مقدار أرباحها في تلك الأرباح.","10% من مقدار أرباحها في تلك الأرباح.","15% من مقدار أرباحها في تلك الأرباح.","لا شيء مما ذكر."],"answer":1,"orig_answer":null,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ي): لا يجوز تقاضي الضريبة عن أرباح الشركة المالكة بنسبة تزيد على (10%) من مقدار أرباحها في تلك الأرباح."},{"num":8,"type":"mcq","q":"للتوصل إلى رصيد الضريبة المستحقة يجري تقاص ما نسبته ........ من ضريبة الأبنية والأراضي داخل مناطق أمانة عمان الكبرى والبلديات التي يدفعها المكلف في أي سنة عن العقارات المؤجرة التي تأتي منها دخل من ضريبة الدخل المستحقة عليه بمقتضى أحكام قانون ضريبة الدخل.","o":["100% على أن لا يتجاوز التقاص المسموح به مقدار الضريبة المستحقة على هذا الدخل عن تلك السنة ومع مراعاة نسبة هذا الدخل إلى الدخل الإجمالي للمكلف.","25% من مقدار الضريبة المستحقة على هذا الدخل عن تلك السنة ومع مراعاة نسبة هذا الدخل إلى الدخل الإجمالي للمكلف.","50% من مقدار الضريبة المستحقة على هذا الدخل عن تلك السنة ومع مراعاة نسبة هذا الدخل إلى الدخل الإجمالي للمكلف.","لا شيء مما ذكر."],"answer":0,"orig_answer":null,"law":"income","article":"18","status":"valid","explanation":"المادة (18/ب): يجري تقاص (100%) من ضريبة الأبنية والأراضي على ألا يتجاوز الضريبة المستحقة على هذا الدخل ومع مراعاة نسبته إلى الدخل الإجمالي."},{"num":9,"type":"mcq","q":"يلتزم المكلف الذي يمارس أنشطة أعمال وتجاوز دخله الإجمالي من هذه الأنشطة في الفترة الضريبية السابقة ........... بتوريد الدفعات النصف سنوية المقدمة على حساب الضريبة المستحقة على الدخل المتأتي من تلك الأنشطة وفق المواعيد المحددة:","o":["مليون دينار خلال النصف الأول من العام السابق.","مليون و500 ألف.","مليون دينار.","500 ألف دينار."],"answer":2,"orig_answer":null,"law":"income","article":"19","status":"valid","explanation":"المادة (19/ب): يلزم بالدفعات المقدمة من تجاوز دخله الإجمالي من أنشطة الأعمال في الفترة السابقة مليون دينار."},{"num":10,"type":"mcq","q":"يلتزم المكلف بتنظيم السجلات والبيانات المالية اللازمة لتحديد مقدار الضريبة المستحقة عليه شريطة أن تكون معدة وفق معايير المحاسبة الدولية ومدققة ومصادق عليها من محاسب قانوني وبالاحتفاظ بها لمدة أربع سنوات تبدأ من آخر أي تاريخ:","o":["تبليغ الإشعار بنتيجة التقدير الإداري.","إنهاء الفترة الضريبية التي تم تنظيم السجلات.","تقديم الإقرار الضريبي.","جميع ما ذكر."],"answer":3,"orig_answer":null,"law":"income","article":"23","status":"valid","explanation":"المادة (23/أ): الاحتفاظ أربع سنوات من آخر التواريخ: انتهاء الفترة الضريبية، تقديم الإقرار، تبليغ إشعار التقدير الإداري."},{"num":11,"type":"mcq","q":"يترتب على الشخص المرخص له مزاولة مهنة محاسب قانوني في المملكة أن يقدم لدائرة ضريبة الدخل والمبيعات بياناً بأسماء عملائه وعناوينهم خلال مدة لا تتجاوز ........... من السنة اللاحقة للسنة المالية:","o":["الشهر الثاني.","الشهر الأول.","الشهر الثالث.","الشهر الرابع مع الإقرار الضريبي."],"answer":2,"orig_answer":null,"law":"income","article":"25","status":"valid","explanation":"المادة (25): يقدم المحاسب القانوني بيان أسماء عملائه وعناوينهم خلال مدة لا تتجاوز نهاية الشهر الثالث من السنة اللاحقة."},{"num":12,"type":"mcq","q":"تصدر هيئة الاعتراض قراراً معللاً بشأن الاعتراض خلال ........ من تاريخ تقديم الاعتراض ولها تأييد القرار المعترض عليه أو تعديله سواءً بزيادة الضريبة أو تخفيضها أو إلغائها:","o":["مئة وعشرون يوماً.","تسعون يوماً.","ستون يوماً.","ثلاثون يوماً."],"answer":1,"orig_answer":null,"law":"income","article":"33","status":"valid","explanation":"المادة (33/ز): تصدر هيئة الاعتراض قرارها المعلل خلال تسعين يوماً من تاريخ تقديم الاعتراض."},{"num":13,"type":"mcq","q":"للمحكمة المختصة وفق المادة (46) من أحكام قانون ضريبة الدخل أن:","o":["أن تؤيد ما ورد في القرار المطعون فيه أو تخفض أو تلغي الضريبة والمبالغ الأخرى المقررة بموجبه.","أن تؤيد ما ورد في القرار المطعون فيه أو تخفض أو تزيد أو تلغي الضريبة والمبالغ الأخرى المقررة بموجبه.","أن تعيد القضية إلى مصدر القرار المطعون فيه لإعادة النظر فيه.","أ+ج."],"answer":3,"orig_answer":null,"law":"income","article":"46","status":"valid","explanation":"المادة (46/ب): للمحكمة تأييد القرار أو تخفيض الضريبة أو إلغاؤها (دون زيادة) ولها إعادة القضية لمصدر القرار لإعادة النظر."},{"num":14,"type":"mcq","q":"يعين أعضاء النيابة العامة الضريبية بقرار من:","o":["وزير العدل.","وزير المالية.","المجلس القضائي.","مدير عام ضريبة الدخل والمبيعات."],"answer":2,"orig_answer":null,"law":"income","article":"55","status":"valid","explanation":"المادة (55/ب): يعين أعضاء النيابة العامة الضريبية بقرار من المجلس القضائي."},{"num":15,"type":"mcq","q":"حسب قانون الضريبة العامة على المبيعات أي من العبارات التالية غير صحيحة:","o":["لا تخضع للضريبة السلع والخدمات المهربة.","لا يخضع للضريبة العامة على المبيعات بيع الأموال غير المنقولة.","تستحق الضريبة العامة والخاصة على السلع المستوردة في مرحلة التخليص عليها حسب نسبة الضريبة أو فئتها في تاريخ تسجيل البيان.","تستحق الضريبة على بيع الخدمة عند إصدار فاتورة ضريبية وعند تسلم بدل الخدمة كلياً أو جزئياً أيهما أسبق."],"answer":0,"orig_answer":null,"law":"sales","article":"12","status":"valid","explanation":"المادة (12): تخضع للضريبة السلع والخدمات المهربة حسب الفئات النافذة بتاريخ التهرب، فالعبارة (أ) غير صحيحة."},{"num":16,"type":"mcq","q":"الخدمة المستوردة هي:","o":["الخدمة المؤداة داخل وخارج المملكة من أشخاص مقيمين وغير مقيمين أو مؤسسة أجنبية وبغض النظر عن موقع فروعها.","الخدمة المؤداة من أشخاص غير مقيمين أو من شركات أو مؤسسات أجنبية لها فروع عاملة داخل المملكة.","الخدمة المؤداة من أشخاص مقيمين أو من شركات أو مؤسسات أجنبية ليس لها فروع عاملة داخل المملكة.","الخدمة المؤداة من أشخاص غير مقيمين أو من شركات أو مؤسسات أجنبية ليس لها فروع عاملة داخل المملكة."],"answer":null,"orig_answer":3,"law":"sales","article":"4 مكرر","status":"changed","explanation":"كان القانون يعرّف الخدمة المستوردة بأنها المؤداة من غير مقيمين أو مؤسسات أجنبية ليس لها فروع عاملة في المملكة (د)؛ ألغي هذا التعريف وحل محله مفهوم (استيراد الخدمات) وفق المادة (4 مكرر/هـ) المرتبط بمكان متلقي الخدمة."},{"num":17,"type":"mcq","q":"حسب قانون الضريبة العامة على المبيعات على مستورد الخدمة دفع الضريبة المستحقة عليها للدائرة:","o":["خلال ستة أشهر من تاريخ تلقي الخدمة أو أي جزء منها وذلك بحدود ما يتعلق بذلك الجزء.","خلال شهر واحد من دفع بدل الخدمة المستوردة أو أي جزء منه وذلك بحدود ما يتعلق بذلك الجزء.","عند إفراج السلطات الجمركية عن المادة التي قدمت بواسطتها تلك الخدمة.","جميع ما ذكر."],"answer":3,"orig_answer":null,"law":"sales","article":"26","status":"valid","explanation":"المادة (26/ج): يدفع مستورد الخدمة الضريبة عند أي من الحالات أيها أسبق: خلال شهر من دفع البدل، عند الإفراج الجمركي، خلال ستة أشهر من تلقي الخدمة."},{"num":18,"type":"mcq","q":"حسب تعليمات تحرير الفاتورة الضريبية لضريبة المبيعات يلتزم المسجل بإصدار الفاتورة الضريبية في حال تحقق واقعة البيع بتأدية الخدمة أو تسليم السلعة أو قبض الثمن ضمن التواريخ التالية ما عدا:","o":["مباشرة بعد تسليم السلعة أو تأدية الخدمة أو قبض الثمن إذا كان البائع يستخدم آلة النقد الذي يُعتبر شريط آلة النقد في هذه الحالة بمثابة الفاتورة.","في موعد أقصاه نهاية الشهر إذا كان البائع يستخدم سندات إخراج وبطاقة صنف.","خلال فترة أقصاها شهر من تاريخ انتهاء توريد الخدمة أو لدى قبض الثمن.","مباشرة بعد تسليم السلعة أو قبض الثمن إذا كان البائع لا يستخدم سندات إخراج وبطاقة صنف."],"answer":2,"orig_answer":null,"law":"sales","article":"18","status":"unverified","explanation":"من تعليمات تحرير الفاتورة الضريبية (غير واردة في نص القانون؛ المادة 18/أ تحيل للتعليمات). الإجابة الأرجح (ج) لاختلاف مدة الخدمات عن نص التعليمات؛ تحتاج تحققاً من التعليمات."},{"num":19,"type":"mcq","q":"حسب تعليمات تنظيم السجلات والمستندات في قانون ضريبة المبيعات أي من النصوص التالية غير صحيح:","o":["للمدير أن يلزم أي شخص غير مسجل عند بيعه لسلعة أو خدمة خاضعة للضريبة بإصدار فواتير ومسك سجلات وحسابات منتظمة لتسجيل عمليات البيع التي يقوم بها والاحتفاظ بتلك الفواتير والسجلات لمدة أربع سنوات تالية لتاريخ انتهاء السنة المالية التي صدرت أو نظمت بها.","للمدير أن يلزم أي شخص من أي فئة من الأشخاص من تلقاء نفسه أو بناء على طلب أي منهم بتنظيم سجلات ومستندات تبين مقدار مبيعات كل منهم وتراعي طبيعة عمل ونشاط هذه الجهات وله إعفاؤهم من تدقيقها وتصديقها من محاسب قانوني مرخص ومزاول لمهنة التدقيق.","يلتزم الشخص الطبيعي وشركة التضامن وشركة التوصية البسيطة ممن تزيد مبيعات أي منهم على 200,000 مئتي ألف دينار في السنة بتنظيم السجلات والمستندات وفق معايير المحاسبة الدولية ومصادق عليها من محاسب قانوني.","يلتزم الشخص الطبيعي وشركة التضامن ممن تزيد مبيعات أي منهم على 200,000 مئتي ألف دينار في السنة بتنظيم السجلات والمستندات وفق معايير المحاسبة الدولية ومصادق عليها من محاسب قانوني."],"answer":0,"orig_answer":null,"law":"sales","article":"18","status":"unverified","explanation":"المادة (18/ب) بنصها الحالي تحدد مدة احتفاظ غير المسجل بالفواتير والسجلات بخمس سنوات لا أربع، فالعبارة (أ) غير صحيحة وفق النص الحالي؛ أما (ج/د) فمن تعليمات تنظيم السجلات ولم يتم التحقق منها."},{"num":20,"type":"mcq","q":"حسب تعليمات تنظيم السجلات والمستندات في قانون ضريبة المبيعات على المكلف الذي يستخدم أجهزة الحاسوب في تنظيم سجلاته ومستنداته وبياناته المالية والتي تُعتبر هذه السجلات أصولية من الناحية المحاسبية عليه مراعاة التالي ما عدا:","o":["أن تكون هذه البيانات موثقة وتعكس حقيقة الوضع المالي للمكلف.","أن تتضمن البيانات المدخلة التوقيع الالكتروني لدخلها.","أن يسمح بإجراء التعديل والتغيير لمفردات البيانات المدخلة عند حدوث أي خطأ.","أن يحتفظ المكلف للمدة المقررة قانوناً بأصول المستندات والوثائق المعززة لها."],"answer":2,"orig_answer":null,"law":"sales","article":"","status":"unverified","explanation":"من تعليمات تنظيم السجلات: يشترط في السجلات المحوسبة ألا تسمح بتعديل أو تغيير البيانات المدخلة، لذا (ج) هي الاستثناء."},{"num":21,"type":"mcq","q":"شركة تمارس الاستيراد والشراء المحلي وبيع المواد التموينية والزيوت النباتية وعليه فالشركة ملزمة بالتسجيل في ضريبة المبيعات:","o":["عند بلوغ حد التسجيل أو أول عملية استيراد أيهما أسبق.","خلال 30 يوم من تاريخ أول استيراد.","منذ اليوم الأول للاستيراد.","عند حد التسجيل البالغ 75,000 خمسة وسبعون ألف دينار."],"answer":1,"orig_answer":null,"law":"sales","article":"13","status":"valid","explanation":"المادة (13/ب): يلتزم مستورد السلعة أو الخدمة الخاضعة بالتسجيل خلال ثلاثين يوماً من تاريخ أول استيراد مهما بلغ حجم مستورداته."},{"num":22,"type":"mcq","q":"أي من التالي صحيح فيما يتعلق بالشركة الدامجة الخلف القانوني للشركات المندمجة:","o":["تنتقل جميع حقوق والتزامات الشركات المندمجة إلى الشركة الدامجة أو الشركة الناتجة عن الاندماج حكماً بعد انتهاء إجراءات الدمج وتسجيل الشركة وفقاً لأحكام القانون وتُعتبر الشركة الدامجة أو الناتجة عن الاندماج خلفاً قانونياً للشركات المندمجة وتحل محلها في جميع حقوقها والتزاماتها.","تنتقل جميع حقوق والتزامات الشركات المندمجة إلى الشركة الدامجة أو الشركة الناتجة عن الاندماج وفقاً لعقد الاندماج الموقع حكماً، وذلك بعد قيام لجنة الاندماج بتقديم تقريرها إلى معالي الوزير وموافقة الوزير على ذلك.","تنتقل جميع حقوق والتزامات الشركات المندمجة إلى الشركة الدامجة أو الشركة الناتجة عن الاندماج، وذلك بموجب قرار الهيئة العامة للشركات الراغبة بالاندماج مباشرة وذلك بعد توقيع عقد الاندماج وتوريده إلى دائرة مراقبة الشركات وحصول الشركات المذكورة على شهادة بمضمون القرارات.","جميع ما ذكر صحيح."],"answer":0,"orig_answer":null,"law":"companies","article":"238","status":"valid","explanation":"المادة (238): تنتقل الحقوق والالتزامات حكماً بعد انتهاء إجراءات الدمج والتسجيل وتعتبر الدامجة أو الناتجة خلفاً قانونياً."},{"num":23,"type":"mcq","q":"أي من التالي يُعتبر صحيح فيما يتعلق بنفاذ قانون الشركات على الشركات القائمة وتوفيق أوضاعها:","o":["ألا يتوجب على الشركات القائمة والمسجلة قبل نفاذ هذا القانون توفيق أوضاعها وفق أحكام هذا القانون، وذلك لكون هذه الشركات مسجلة بموجب قوانين وأنظمة كانت نافذة سابقاً.","تعتبر جميع الشركات المسجلة بمقتضى القوانين المعمول بها قبل نفاذ هذا القانون قائمة وكأنها مسجلة وفق أحكامه، وعلى الشركات القائمة توفيق أوضاعها وإجراء التعديلات اللازمة على عقودها خلال مدة لا تتجاوز سنة واحدة من تاريخ نفاذ هذا القانون.","تُعتبر جميع الشركات المسجلة بمقتضى القوانين المعمول بها قبل نفاذ هذا القانون ملغاة ويتوجب تسجيلها وفق أحكام هذا القانون.","جميع ما ذكر صحيح."],"answer":1,"orig_answer":null,"law":"companies","article":"286","status":"valid","explanation":"المادة (286/ب): على الشركات القائمة توفيق أوضاعها خلال مدة لا تتجاوز سنة واحدة من تاريخ نفاذ القانون."},{"num":24,"type":"mcq","q":"أي من الجمل التالية يعتبر صحيح فيما يتعلق بالشركة المعفاة:","o":["يمكن للشركة المعفاة بعد تسديد الرسوم المقررة عليها أن تطرح أسهمها للاكتتاب العام في حالة إذا كانت شركة مساهمة عامة شريطة الالتزام بالأنظمة والتعليمات الصادرة عن هيئة الأوراق المالية وقانون الشركات.","يحق للشركة المعفاة أن تمارس أعمالها داخل وخارج المملكة شريطة أن تقوم بدفع رسوم سنوية تعادل ما لا يقل عن (20%) من إيراداتها السنوية كإيرادات للخزينة العامة.","الشركة المعفاة هي شركة مساهمة عامة أو شركة توصية بالأسهم أو شركة محدودة المسؤولية أو الشركات المساهمة الخاصة التي تسجل في المملكة وتزاول أعمالها خارجها ويضاف إلى اسمها عبارة (شركة معفاة) ويحظر عليها طرح أسهمها للاكتتاب العام في المملكة.","الشركة المعفاة هي الشركة التي يمكن تسجيلها بأي نوع من أنواع الشركات ويضاف على اسمها عبارة (شركة معفاة)."],"answer":null,"orig_answer":2,"law":"companies","article":"211","status":"changed","explanation":"المادة (211) بنصها الحالي: الشركة المعفاة شركة مساهمة عامة أو محدودة المسؤولية أو مساهمة خاصة (لم تعد تشمل التوصية بالأسهم) ويحظر عليها طرح أسهمها للاكتتاب في المملكة؛ لذا لا يطابق أي خيار النص تماماً."},{"num":25,"type":"mcq","q":"للوزير والمراقب اتخاذ الإجراءات المناسبة لمراقبة الشركات للتحقق من تقيدها بأحكام قانون الشركات والأحكام والعقود والأنظمة والقرارات، وتشمل الرقابة بشكل خاص ما يلي:","o":["التحقق من الخبرات العملية لمجلس الإدارة والإدارة التنفيذية ومدى ملائمة هذه الخبرات المتوفرة لديهم لقيام الشركة بتحقيق أهدافها وأهداف المساهمين.","فحص سجل المساهمين للتحقق من جنسياتهم وحصصهم أو مساهمتهم برأسمال الشركة ومدى ملائمة رأسمال الشركة للغايات التي تمارسها.","فحص حسابات الشركة وقيودها والتحقق من التزام الشركة بالغايات التي أسست من أجلها.","جميع ما ذكر صحيح."],"answer":2,"orig_answer":null,"law":"companies","article":"273","status":"valid","explanation":"المادة (273): تشمل الرقابة بشكل خاص فحص حسابات الشركة وقيودها والتأكد من التزامها بالغايات التي أسست من أجلها."},{"num":26,"type":"mcq","q":"تلتزم شركة التضامن بتعيين مدقق حسابات قانوني ينتخب بأكثرية الأعضاء إذا كان رأسمالها يبلغ:","o":["100,000 دينار أو أكثر.","75,000 دينار.","50,000 دينار.","10,000 دينار."],"answer":0,"orig_answer":null,"law":"companies","article":"24","status":"valid","explanation":"المادة (24/ب): تلتزم شركة التضامن التي يبلغ رأسمالها مئة ألف دينار أو أكثر بتعيين مدقق حسابات."},{"num":27,"type":"mcq","q":"لا يجوز للشركاء في شركة التضامن إخراج أي من الشركاء إلا:","o":["قرار من الوزير.","بقرار (75%) من حصص الشركاء.","بقرار من المحكمة بناء على طلب أي منهم.","بقرار من المراقب."],"answer":2,"orig_answer":null,"law":"companies","article":"23","status":"valid","explanation":"المادة (23): لا يجوز إخراج أي شريك إلا بقرار من المحكمة بناء على طلب أي من الشركاء."},{"num":28,"type":"mcq","q":"يحق لشركة التضامن أو التوصية البسيطة الاحتفاظ باسمها الأصلي في حال:","o":["تم تصفيتها ورغبت بالتسجيل كشركة ذات مسؤولية محدودة.","رغبت بالتحول إلى شركة ذات مسؤولية محدودة.","تم شطب تسجيلها ورغبت بالتسجيل كشركة ذات مسؤولية محدودة.","لا شيء مما ذكر."],"answer":1,"orig_answer":null,"law":"companies","article":"56","status":"valid","explanation":"المادة (56): يحق لشركة التضامن أو التوصية البسيطة الاحتفاظ باسمها الأصلي إذا رغبت بالتحول إلى ذات مسؤولية محدودة."},{"num":29,"type":"mcq","q":"إذا كان رأسمال الشركة ذات المسؤولية المحدودة أو جزء من حصصها عينية، فعلى مقدمي هذه الحصص المحافظة على هذه المقدمات وعدم التصرف بها إلى حين:","o":["تسليمها إلى الشركة وتسجيلها باسمها ونقل ملكيتها إليها.","بيعها وتوزيع حصيلة البيع على الشركاء مالكي هذه المقدمات العينية.","بيعها وإيداع حصيلة البيع في حسابات الشركة.","لا شيء مما ذكر."],"answer":0,"orig_answer":null,"law":"companies","article":"58","status":"valid","explanation":"المادة (58/ب): على مقدمي الحصص العينية تسليمها ونقل ملكيتها للشركة خلال ثلاثين يوماً من التسجيل."},{"num":30,"type":"mcq","q":"يشترط حضور مراقب عام الشركات اجتماع الهيئات العامة للشركات التالية:","o":["لا يشترط حضور مراقب عام الشركات لأي نوع من أنواع الشركات.","الشركات المساهمة العامة المحدودة.","الشركات المساهمة الخاصة والشركات المساهمة العامة المحدودة.","الشركات ذات المسؤولية المحدودة والمساهمة الخاصة والمساهمة العامة المحدودة."],"answer":1,"orig_answer":null,"law":"companies","article":"182","status":"valid","explanation":"المادة (182): يعتبر اجتماع الهيئة العامة للمساهمة العامة باطلاً إذا لم يحضره المراقب؛ ولا يدعى في ذات المسؤولية المحدودة والمساهمة الخاصة (64/هـ، 78 مكرر/هـ)."},{"num":31,"type":"mcq","q":"النسبة المئوية المحددة في قانون الشركات النافذ ليتقدم شركاء و/أو مساهمين بطلب تشكيل لجنة تدقيق على الشركة هي:","o":["(25%).","(20%).","(10%).","(15%)."],"answer":2,"orig_answer":null,"law":"companies","article":"275","status":"valid","explanation":"المادة (275/أ): لمساهمين يملكون ما لا يقل عن (10%) من رأس المال طلب إجراء تدقيق على أعمال الشركة."},{"num":32,"type":"mcq","q":"للشركة ذات المسؤولية المحدودة أن تخفض رأسمالها سنداً لحالة من الحالات التالية:","o":["إذا لحقت بها خسائر تزيد على (40%) من رأسمالها.","إذا زاد عن حاجتها أو إذا لحقت بها خسائر تزيد عن نصف رأسمالها أو إذا انسحب أحد الشركاء منها.","إذا زاد عن حاجتها أو إذا لحقت بها خسائر تزيد عن (25%) من رأسمالها.","إذا زاد عن حاجتها أو إذا لحقت بها خسائر تزيد عن نصف رأسمالها."],"answer":3,"orig_answer":null,"law":"companies","article":"68","status":"valid","explanation":"المادة (68/أ): للمحدودة المسؤولية تخفيض رأسمالها إذا زاد عن حاجتها أو لحقت بها خسائر تزيد على نصف رأسمالها."},{"num":33,"type":"mcq","q":"أي من الحالات التالية صحيحة فيما يتعلق برأسمال الشركة المساهمة الخاصة عند التأسيس:","o":["رأسمال الشركة المصرح به وفق لما يحدده المساهمين دون سقف أعلى وأن لا يقل رأسمال الشركة المكتتب به عن (50,000) دينار/ سهم.","لا يقل رأس المال المصرح به عن (10) مليون دينار/سهم، وأن لا يقل رأسمال الشركة المكتتب به عن (20,000) دينار/سهم.","رأسمال الشركة المصرح به وفق لما يحدده المساهمين، وأن لا يقل رأسمال الشركة المكتتب به عن (100,000) دينار/سهم.","لا يقل رأس المال المصرح به عن (10) مليون دينار/سهم، ورأس المال المكتتب به عن (100,000) دينار/سهم."],"answer":0,"orig_answer":null,"law":"companies","article":"66 مكرر","status":"valid","explanation":"المادة (66 مكرر/أ): لا يقل رأس المال المكتتب به للمساهمة الخاصة عن خمسين ألف دينار ولا حد أعلى للمصرح به."},{"num":34,"type":"mcq","q":"يتوجب على المساهمين في الشركة المساهمة الخاصة عقد اجتماع هيئة عامة تأسيسي من تاريخ صدور شهادة تسجيل الشركة من قبل المراقب خلال مدة:","o":["خلال (10) يوم (عشرة أيام).","خلال (30) يوم (شهر).","خلال (60) يوم (شهرين).","خلال (90) يوم (ثلاث أشهر)."],"answer":1,"orig_answer":null,"law":"companies","article":"71 مكرر","status":"valid","explanation":"المادة (71 مكرر): يعقد الاجتماع التأسيسي خلال شهر من تاريخ صدور شهادة التسجيل."},{"num":35,"type":"mcq","q":"يحظر على مدير عام الشركة المساهمة الخاصة وموظفيها تولي وظيفة في شركة أخرى ذات غايات مماثلة أو منافسة لأعمال الشركة سواء لحسابه أو لحساب الغير بأجر أو بدون أجر إلا بموافقة:","o":["لا يشترط موافقة أي جهة.","موافقة مجلس الإدارة.","موافقة الهيئة العامة غير العادية.","مراقب عام الشركات."],"answer":1,"orig_answer":null,"law":"companies","article":"74 مكرر","status":"valid","explanation":"المادة (74 مكرر/ب): يحظر على المدير العام وموظفي المساهمة الخاصة ذلك إلا بموافقة مجلس الإدارة."},{"num":36,"type":"mcq","q":"ما هي النسبة التي يتوجب على الشركة المساهمة الخاصة اقتطاعها من أرباحها السنوية لحساب الاحتياطي الإجباري، والنسبة التي لا يتجاوز مجموع ما يقتطع من رأس المال المكتتب به:","o":["(10%) سنوياً ولا يتجاوز مجموع ما يقتطع (25%) من رأس المال المكتتب به.","(15%) سنوياً ولا يتجاوز مجموع ما يقتطع (15%) من رأس المال المكتتب به.","(20%) سنوياً ولا يتجاوز مجموع ما يقتطع (25%) من رأس المال المكتتب به.","(25%) سنوياً ولا يتجاوز مجموع ما يقتطع (50%) من رأس المال المكتتب به."],"answer":0,"orig_answer":null,"law":"companies","article":"85 مكرر","status":"valid","explanation":"المادة (85 مكرر/أ): تقتطع (10%) سنوياً ولا يتجاوز مجموع ما يقتطع (25%) من رأس المال المكتتب به."},{"num":37,"type":"mcq","q":"من المهام التي تتولاها اللجنة الوطنية لمكافحة غسل الأموال وتمويل الإرهاب ما يلي باستثناء:","o":["تعيين محاسب قانوني لوحدة مكافحة غسل الأموال وتمويل الإرهاب وتحديد أتعابه.","تحليل أنماط جرائم غسل الأموال وتمويل الإرهاب وآلياتها وأساليبها وإعداد موجز عنها لنشرها.","متابعة المستجدات العالمية في مجال مكافحة غسل الأموال وتمويل الإرهاب وانتشار أسلحة الدمار الشامل واقتراح الإجراءات اللازمة بشأنها.","اعتماد إجراءات تقييم مخاطر غسل الأموال وتمويل الإرهاب وانتشار أسلحة الدمار الشامل في المملكة وتحديثها."],"answer":1,"orig_answer":null,"law":"aml","article":"6","status":"valid","explanation":"المادة (6/أ): من مهام اللجنة تعيين محاسب قانوني للوحدة ومتابعة المستجدات واعتماد تقييم المخاطر؛ أما تحليل الأنماط فليس من مهامها."},{"num":38,"type":"mcq","q":"تصدر المسكوكات التذكارية والخاصة بقرار من:","o":["محافظ البنك المركزي.","رئيس الوزراء.","مجلس إدارة البنك المركزي.","مجلس الوزراء."],"answer":3,"orig_answer":null,"law":"other:قانون البنك المركزي الأردني","article":"","status":"unverified","explanation":"من قانون البنك المركزي الأردني (غير مدرج)؛ الإجابة الأرجح مجلس الوزراء، تحتاج تحققاً."},{"num":39,"type":"mcq","q":"جميع هذه العبارات صحيحة فيما يتعلق بإشراف البنك المركزي على نظام المدفوعات الوطني باستثناء:","o":["يحدد البنك المركزي أسس الفصل بين أموال مقدمي خدمات الدفع وأموال العملاء بمقتضى تعليمات يصدرها لهذه الغاية.","تقبل المطالبة بعكس أو إلغاء أو إبطال أي تسديد أو تسوية تم إجراؤها نتيجة لتسييل الضمانات والتأمينات المشار إليها في هذه الفقرة.","للبنك المركزي أن يطلب الضمانات والتأمينات اللازمة لتغطية الالتزامات والاستحقاقات التي قد تترتب على مقدمي خدمات الدفع ومديري ومشغلي نظم الدفع أو المشتركين فيها.","للبنك المركزي تحديد أنظمة الدفع أو التقاص أو التسوية التي يتولى إدارتها."],"answer":1,"orig_answer":null,"law":"other:قانون البنك المركزي الأردني","article":"","status":"unverified","explanation":"من قانون البنك المركزي (نظام المدفوعات): لا تقبل المطالبة بعكس أو إلغاء أو إبطال أي تسديد أو تسوية تمت نتيجة تسييل الضمانات، فالعبارة (ب) خاطئة."},{"num":40,"type":"mcq","q":"على كل شخص يرغب في تسويق أو بيع أوراق مالية غير أردنية داخل المملكة الحصول على:","o":["موافقة المركز.","موافقة الهيئة المسبقة وفقاً للتعليمات الصادرة.","موافقة السوق المالي.","لا شيء مما ذكر."],"answer":1,"orig_answer":null,"law":"securities","article":"34","status":"valid","explanation":"المادة (34/د): يلزم الحصول على موافقة الهيئة المسبقة وفقاً للتعليمات لتسويق أو بيع أوراق مالية غير أردنية."},{"num":41,"type":"mcq","q":"تتبع هيئة الأوراق المالية إلى:","o":["رئيس هيئة الأوراق المالية.","رئاسة الوزراء.","رئيس الوزراء.","لا شيء مما ذكر."],"answer":2,"orig_answer":null,"law":"securities","article":"7","status":"valid","explanation":"المادة (7/ب): ترتبط هيئة الأوراق المالية برئيس الوزراء."},{"num":42,"type":"mcq","q":"وفق تعليمات حوكمة الشركات، فإنه يتولى إدارة الشركة مجلس إدارة يتكون من:","o":["ما لا يقل عن 5 ولا يزيد عن 12 عضواً.","ما لا يقل عن 4 ولا يزيد عن 12 عضواً.","ما لا يقل عن 5 ولا يزيد عن 13 عضواً.","ما لا يقل عن 3 ولا يزيد عن 15 عضواً."],"answer":2,"orig_answer":null,"law":"other:تعليمات حوكمة الشركات المساهمة المدرجة","article":"","status":"unverified","explanation":"تعليمات حوكمة الشركات المساهمة المدرجة لسنة 2017: يتولى إدارة الشركة مجلس لا يقل عن 5 ولا يزيد على 13 عضواً."},{"num":43,"type":"mcq","q":"يعتبر التأكد من استقلالية الأعضاء المستقلين في مجلس إدارة الشركات بشكل مستمر من مهام:","o":["لجنة الترشيحات والمكافآت.","لجنة المخاطر.","لجنة الحوكمة.","لجنة التدقيق."],"answer":0,"orig_answer":null,"law":"other:تعليمات حوكمة الشركات المساهمة المدرجة","article":"","status":"unverified","explanation":"تعليمات الحوكمة: تتولى لجنة الترشيحات والمكافآت التأكد بشكل مستمر من استقلالية الأعضاء المستقلين."},{"num":44,"type":"mcq","q":"اللجنة التي يجوز أن تضم في عضويتها أعضاء من الإدارة التنفيذية العليا هي:","o":["لجنة الترشيحات والمكافآت.","لجنة المخاطر.","لجنة الحوكمة.","لجنة التدقيق."],"answer":1,"orig_answer":null,"law":"other:تعليمات حوكمة الشركات المساهمة المدرجة","article":"","status":"unverified","explanation":"تعليمات الحوكمة: يجوز أن تضم لجنة إدارة المخاطر في عضويتها أعضاء من الإدارة التنفيذية العليا."},{"num":45,"type":"mcq","q":"لا يجوز لأي شخص أن يقوم بأي عرض عام للورقة المالية إلا من خلال:","o":["دراسة جدوى اقتصادية.","نشرة معلومات.","نشرة إصدار.","لا شيء مما ذكر."],"answer":2,"orig_answer":null,"law":"securities","article":"34","status":"valid","explanation":"المادة (34/أ/1): لا يجوز القيام بأي عرض عام إلا بتقديم نشرة إصدار إلى الهيئة."},{"num":46,"type":"mcq","q":"يشترط لاستحقاق المؤمن عليه الذي يعمل بإحدى المهن الخطيرة راتب التقاعد المبكر ما يلي:","o":["إكمال سن الخامسة والأربعين وأن تكون اشتراكاته قد بلغت على الأقل (216) اشتراكاً فعلياً للذكر و(180) للأنثى.","إكمال سن الخامسة والأربعين وأن تكون اشتراكاته قد بلغت على الأقل (252) اشتراكاً فعلياً للذكر و(216) للأنثى.","إكمال سن الخامسة والأربعين وأن تكون اشتراكاته قد بلغت على الأقل (240) اشتراكاً فعلياً للذكر و(204) للأنثى.","إكمال سن الخامسة والأربعين وأن تكون اشتراكاته قد بلغت على الأقل (228) اشتراكاً فعلياً للذكر و(192) للأنثى."],"answer":0,"orig_answer":null,"law":"social","article":"64","status":"valid","explanation":"المادة (64/ج/1): المهن الخطرة: (216) اشتراكاً فعلياً للذكر و(180) للأنثى مع إكمال سن الخامسة والأربعين."},{"num":47,"type":"mcq","q":"إذا نشأت من إصابة العمل وفاة المصاب فيستحق راتب تقاعد الوفاة الناشئة عن إصابة العمل بنسبة:","o":["( ) من أجره الذي اتخذ أساساً لتسديد اشتراكاته بتاريخ وقوع الإصابة. [النسبة غير مطبوعة في الورقة]","( ) من أجره الذي اتخذ أساساً لتسديد اشتراكاته بتاريخ وقوع الإصابة. [النسبة غير مطبوعة في الورقة]","( ) من أجره الذي اتخذ أساساً لتحديد اشتراكاته بتاريخ وقوع الإصابة. [النسبة غير مطبوعة في الورقة]","( ) من أجره الذي اتخذ أساساً لتسديد اشتراكاته بتاريخ وقوع الإصابة. [النسبة غير مطبوعة في الورقة]"],"answer":null,"orig_answer":null,"law":"social","article":"30","status":"valid","explanation":"المادة (30/أ): يستحق راتب تقاعد الوفاة الناشئة عن إصابة العمل بنسبة (75%) من الأجر الذي اتخذ أساساً لتسديد الاشتراكات بتاريخ وقوع الإصابة؛ النسب غير مطبوعة في خيارات الورقة."},{"num":48,"type":"mcq","q":"مؤمن عليه تم إيقاف شموله نتيجة ترك العمل ولديه فترات شمول بلغت (200) اشتراكاً جميعها في وزارة الزراعة:","o":["يستحق لبدل التعطل عن (4) أشهر.","يستحق لبدل التعطل عن (3) أشهر.","يستحق لبدل التعطل عن (6) أشهر.","لا شيء مما ذكر."],"answer":3,"orig_answer":null,"law":"social","article":"49","status":"valid","explanation":"المادة (49/ب): يستثنى من تأمين التعطل موظفو الدوائر الحكومية الذين قرر مجلس الوزراء استثناءهم، فموظف وزارة الزراعة لا يستحق بدل التعطل (لا شيء مما ذكر)."},{"num":49,"type":"mcq","q":"يشترط لاستحقاق المؤمن عليه الذكر لراتب تقاعد الشيخوخة:","o":["إكماله سن 60 بغض النظر عن 180 اشتراك.","وجود ما لا يقل عن 180 اشتراك بغض النظر عن السن.","إكماله سن ال 55 بغض النظر عن 180 اشتراك.","إكماله سن ال 60 بغض النظر عن عدد الاشتراكات."],"answer":null,"orig_answer":null,"law":"social","article":"62","status":"valid","explanation":"المادة (62/أ): يشترط إكمال الذكر سن الستين وأن تكون اشتراكاته (180) اشتراكاً منها (84) فعلياً معاً؛ لا يطابق أي خيار الشرطين مجتمعين."},{"num":50,"type":"mcq","q":"يشترط في المؤمن عليه الأردني الذي يرغب في الجمع بين راتب التقاعد المبكر وأجره من العمل المشمول بأحكام القانون ما يلي:","o":["أن يعود للشمول بأحكام القانون في حال عودته للعمل.","أن يكون قد انقطع عن العمل لمدة لا تقل عن 24 شهراً، وأن لا يعود للعمل في أي من المنشآت التي كان يعمل بها خلال الستة والثلاثين اشتراكاً الأخيرة.","أن لا يعود المؤمن عليه الذي يعمل بإحدى المهن الخطيرة، وتم تخصيص راتب التقاعد المبكر له إلى العمل بمهنة خطرة.","جميع ما ذكر صحيح."],"answer":3,"orig_answer":null,"law":"social","article":"85","status":"valid","explanation":"المادة (85/د/1): شروط الجمع: الانقطاع 24 شهراً، عدم العودة لمنشآت آخر 36 اشتراكاً، عدم العودة لمهنة خطرة، العودة للشمول."},{"num":51,"type":"mcq","q":"يجب على العامل إبلاغ المؤسسة بعدم قيام المنشأة بشموله بأحكام القانون خلال مدة لا تتجاوز:","o":["ستة أشهر من تاريخ تركه العمل.","خلال مدة لا تتجاوز ستة أشهر من تاريخ التقدم بطلب الحصول على أية منفعة تأمينية.","سنة من تاريخ تركه للعمل.","ستة أشهر من تاريخ التحاقه بالعمل."],"answer":0,"orig_answer":null,"law":"social","article":"92","status":"valid","explanation":"المادة (92/أ/1): يبلغ العامل المؤسسة بعدم شموله خلال مدة لا تتجاوز ستة أشهر من تاريخ انتهاء خدماته لدى المنشأة."},{"num":52,"type":"mcq","q":"في حال وقوع حادث عمل لمؤمن عليه يجب على المؤمن عليه أو ذويه إبلاغ المؤسسة بالحادث خلال مدة:","o":["أسبوعين من تاريخ وقوع الحادث.","أربعة أشهر من تاريخ وقوع الحادث.","أربعة عشر يوم عمل من تاريخ وقوع الحادث.","أربعة وعشرون ساعة من تاريخ وقوع الحادث."],"answer":1,"orig_answer":null,"law":"social","article":"27","status":"valid","explanation":"المادة (27/د): للمؤمن عليه أو ذويه إشعار المؤسسة بإصابة العمل خلال أربعة أشهر من وقوعها إذا لم تقم المنشأة بذلك."},{"num":53,"type":"mcq","q":"حسب قانون الاستثمار الساري المفعول إذا كان المشروع قد حصل على مزايا وإعفاءات من ضريبة الدخل بمقتضى التشريعات السابقة، ولم يكن قد باشر عمله أو إنتاجه الفعلي فيشترط لغاية تطبيق أحكام هذا القانون، والذي ينص على إعفاء المواد والآلات والتجهيزات وقطع الغيار للصيانة أن يباشر عمله أو الإنتاج الفعلي خلال:","o":["3 سنوات.","سنتين من تاريخ نفاذ القانون تحت طائلة فقدان الحق في المزايا والإعفاءات.","سنة.","6 شهور."],"answer":null,"orig_answer":null,"law":"investment","article":"","status":"obsolete","explanation":"السؤال مبني على الأحكام الانتقالية لقانون الاستثمار لسنة 2014 الذي ألغي بقانون البيئة الاستثمارية رقم (21) لسنة 2022، ولا يوجد حكم مماثل فيه."},{"num":54,"type":"mcq","q":"حسب قانون الطوابع الساري المفعول تفرض غرامة على المكلف بدفع الرسم المقرر إذا تأخر عن دفعه في الموعد المحدد، وعلى النحو التالي:","o":["مثل الرسم أو مقدار النقص في حال التأخر لمدة تزيد عن 30 يوم ولا تتجاوز 60 يوم وبحد أدنى دينار واحد.","1% عن الرسم المستحق أو النقص عما تم دفعه من الرسم عن الأسبوع الأول من التأخر وبحد أدنى دينار واحد.","50% من الرسم أو مقدار النقص في حال التأخر لمدة تزيد عن 7 أيام ولا تتجاوز 30 يوم وبحد أدنى دينار واحد.","جميع ما ذكر."],"answer":3,"orig_answer":null,"law":"stamp","article":"12","status":"valid","explanation":"المادة (12/أ): 1% عن الأسبوع الأول، 50% من 7 إلى 30 يوماً، مثل الرسم من 30 إلى 60 يوماً، مثلا الرسم بعد 60 يوماً؛ فجميع الخيارات صحيحة."},{"num":55,"type":"mcq","q":"حسب قانون ديوان المحاسبة الساري المفعول أي من العبارات التالية غير صحيحة:","o":["يكون ديوان المحاسبة مسؤولاً فيما يتعلق بالنفقات عن أسباب عدم صرف لكل أو بعض المخصصات التي رصدت للأعمال الجديدة.","يكون ديوان المحاسبة مسؤولاً فيما يتعلق بالنفقات عن أسباب عدم إصدار أوامر الصرف حسب الأصول الصحيحة ومن قبل الجهات المختصة.","يكون ديوان المحاسبة مسؤولاً عن تدقيق الواردات في معاملات شطب الواردات والإعفاء منها للتثبت من عدم إجراء شطب أو إعفاء في غير الحالات والأصول المنصوص عليها في القوانين والأنظمة.","يكون ديوان المحاسبة مسؤولاً عن تدقيق الواردات في معاملات بيع الأراضي والعقارات الأميرية وتأجيرها وتفويضها."],"answer":1,"orig_answer":null,"law":"audit","article":"9","status":"valid","explanation":"المادة (9/ج): يتثبت الديوان من أن إصدار أوامر الصرف تم حسب الأصول ومن الجهات المختصة، لا من أسباب عدم إصدارها؛ باقي العبارات وردت في المادتين (8) و(9)."},{"num":56,"type":"mcq","q":"حسب قانون المنافسة الساري المفعول، أي من العبارات التالية غير صحيحة:","o":["يسمح لكل منتج أو مستورد أو تاجر جملة أو مقدم خدمة أن يفرض بصورة مباشرة أو غير مباشرة حد أدنى لأسعار بيع سلعة أو خدمة.","تتحدد أسعار السلع والخدمات وفقاً لقواعد السوق ومبادئ المنافسة الحرة.","يحظر على أي مؤسسة إعادة بيع منتج على حالته بسعر أقل من سعر شرائه الحقيقي مضافاً إليه الضرائب والرسوم ولا يشمل هذا الحظر المنتجات سريعة التلف والتنزيلات المرخص بها لأي بيع يتم لتصفية الأعمال أو تحديد المخزون.","تسري أحكام هذا القانون على جميع أنشطة الإنتاج والتجارة والخدمات في المملكة كما ينصرف أحكامه إلى أي أنشطة اقتصادية تتم خارج المملكة وتترتب عليها آثار داخلها."],"answer":0,"orig_answer":null,"law":"competition","article":"8","status":"valid","explanation":"المادة (8/أ/1): يحظر على المنتج أو المستورد أو تاجر الجملة أو مقدم الخدمة فرض حد أدنى لأسعار إعادة البيع."},{"num":57,"type":"mcq","q":"تلتزم الجهات المبينة أدناه بالإجراءات المنصوص عليها في قانون مكافحة غسل الأموال والأنظمة والتعليمات والقرارات الصادرة بمقتضى أي منها:","o":["المحامون والمحاسبون القانونيون.","في المؤسسات المالية وتشمل البنوك وشركات الصرافة والأشخاص والشركات التي تخضع لرقابة وترخيص هيئة الأوراق المالية وشركات التأمين ووكلائهم ووسطاء التأمين.","شركات التأجير التمويلي.","جميع ما ذكر."],"answer":3,"orig_answer":null,"law":"aml","article":"14","status":"valid","explanation":"المادة (14/أ): تشمل الجهات الملزمة المؤسسات المالية (بنوك، صرافة، شركات الأوراق المالية والتأمين، التأجير التمويلي) والمحامين والمحاسبين القانونيين."},{"num":58,"type":"mcq","q":"يتولى مجلس هيئة مكافحة الفساد المهام التالية ما عدا:","o":["الشكاوي والتنظيمات القابلة للطعن الإداري والمنظورة أمام جهة قضائية أو صدرت أحكام قضائية فيها.","اتخاذ القرارات اللازمة بخصوص قضايا الفساد بما في ذلك إحالتها إلى الجهات القضائية المختصة.","التعاون والتنسيق مع الجهات المحلية والإقليمية والدولية المتماثلة لعمل الهيئة.","وضع السياسات العامة للهيئة وإقرار الخطط والبرامج اللازمة لتنفيذها."],"answer":0,"orig_answer":null,"law":"integrity","article":"8","status":"valid","explanation":"المادة (8/أ): الشكاوى المنظورة أمام القضاء ليست من مهام المجلس؛ أما اتخاذ قرارات قضايا الفساد والتعاون والتنسيق ووضع السياسة العامة فمن مهامه."},{"num":59,"type":"mcq","q":"أي من التالي لا يُعتبر دليلاً على الإعسار الفعلي:","o":["صدور قرار من المحكمة يقضي بالاعتراف بإجراءات إعسار أجنبية رئيسية.","إذا كان المدين شخصاً طبيعياً غير واضح أو مجهول الإقامة أو أنه أغلق مركز المصالح الرئيسية له إذا كان شخصاً اعتبارياً.","إذا هرب المدين أمواله أو باعها بغبن فاحش.","إلقاء الحجز التنفيذي على جزء من أموال المدين."],"answer":3,"orig_answer":null,"law":"insolvency","article":"10","status":"valid","explanation":"المادة (10/ج/2): الدليل هو إلقاء الحجز التنفيذي على كامل أموال المدين لا على جزء منها."},{"num":60,"type":"mcq","q":"إذا صدر قرار بتجريد المدين من صلاحية إدارة ذمة الإعسار والتصرف فيها، فيحل محل المدين سواء بصفته مدعياً أو مدعى عليه في إجراءات قضائية مقابلة قبل إشهار الإعسار أي من التالي:","o":["لجنة من ممثلي العاملين لدى المدين.","وكيل الإعسار.","لجنة من دائني المدين.","محامي المدين للحفاظ على حقوق المدين."],"answer":1,"orig_answer":null,"law":"insolvency","article":"17","status":"valid","explanation":"المادة (17/هـ): يحل وكيل الإعسار محل المدين مدعياً أو مدعى عليه في الإجراءات القضائية المقامة قبل إشهار الإعسار."},{"num":61,"type":"mcq","q":"تجتمع الهيئة العامة للدائنين بناء على دعوة وكيل الإعسار إما من تلقاء نفسه أو بناء على طلب لجنة الدائنين أو دائنين يمثلون:","o":["10% على الأقل من إجمالي الديون.","20% على الأقل من إجمالي الديون.","30% على الأقل من إجمالي الديون.","50% على الأقل من إجمالي الديون."],"answer":1,"orig_answer":null,"law":"insolvency","article":"44","status":"valid","explanation":"المادة (44/أ): بناء على طلب لجنة الدائنين أو دائنين يمثلون (20%) على الأقل من إجمالي الديون."},{"num":62,"type":"mcq","q":"أي من الجهات التالية غير ملزمة بتعيين محاسب قانوني مسجل في سجل المحاسبين القانونيين المزاولين لغايات تدقيق حساباتها:","o":["النقابات والجمعيات التي تؤسس بمقتضى التشريعات المعمول بها.","شركات التضامن التي يقل رأسمالها أو حجم مبيعاتها السنوية على مائة ألف دينار.","شركات التوصية بالأسهم.","الشركات المساهمة العامة والشركات المساهمة الخاصة وذات المسؤولية المحدودة."],"answer":1,"orig_answer":null,"law":"accounting","article":"30","status":"valid","explanation":"المادة (30/أ/2): تلتزم شركات التضامن والتوصية البسيطة التي يزيد رأسمالها أو مبيعاتها على مئة ألف دينار، فالتي يقل رأسمالها غير ملزمة."},{"num":63,"type":"mcq","q":"يتم بقرار من المجلس نقل اسم المحاسب القانوني من سجل المزاولين إلى سجل غير المزاولين في أي من الأسباب والحالات التالية ما عدا:","o":["إذا تم التنسيب من لجنة التأديب.","إذا لم يسدد الالتزامات المالية المترتبة عليه للجمعية لمدة تزيد عن سنتين.","إذا مارس عملاً عدا العمل في المهنة.","بناء على طلبه."],"answer":0,"orig_answer":null,"law":"accounting","article":"","status":"unverified","explanation":"من نظام مزاولة المهنة/النظام الداخلي للجمعية (غير وارد في القانون)؛ الإجابة الأرجح (أ) لأن التأديب يتم بقرار اللجنة التأديبية وفق المادة (36)."},{"num":64,"type":"mcq","q":"يحظر على المحاسب القانوني المزاول لأعمال التدقيق أو المحاسبة القيام بأي مما يلي عدا:","o":["المتاجرة بالأسهم والسندات.","القيام بالدعاية لنفسه بأي وسيلة من وسائل الإعلان بطريقة تسيء للمهنة.","تدقيق حسابات أي شركة يكون شريكاً أو مساهماً فيها.","احتراف التجارة أو الصناعة أو العمل في أي مهنة أخرى."],"answer":0,"orig_answer":null,"law":"accounting","article":"","status":"unverified","explanation":"من قواعد سلوك المهنة (المادة 27 تحيل إليها): المتاجرة بالأسهم والسندات غير محظورة بينما الدعاية وتدقيق شركة يكون شريكاً فيها واحتراف التجارة محظورة."},{"num":65,"type":"mcq","q":"تستوفى رسوم طوابع على المبالغ الواردة في معاملات الشراء المباشر أو التلزيم أو استدراج العروض أو العطاءات التي تقوم بها أي وزارة أو دائرة حكومية أو مؤسسة رسمية أو مؤسسة عامة أو شركة مساهمة عامة ومعاملات البيع التي تتم من قبل أي من هذه الجهات فيما عدا العمليات المتعلقة بمبيعات الشركات المساهمة العامة بنسبة:","o":["(0.001) واحد بالألف.","(0.003) ثلاثة بالألف.","(0.006) ستة بالألف.","لا شيء مما ذكر."],"answer":2,"orig_answer":null,"law":"stamp","article":"","status":"unverified","explanation":"من جدول رسوم الطوابع الملحق بالقانون (غير مدرج في النص المتاح): ستة بالألف على معاملات الشراء والعطاءات الحكومية."},{"num":66,"type":"mcq","q":"تخضع الأهلية التجارية لأحكام:","o":["العرف العام.","العرف التجاري.","القانون المدني.","قانون التجارة."],"answer":2,"orig_answer":null,"law":"other:قانون التجارة","article":"","status":"unverified","explanation":"قانون التجارة لسنة 1966: تخضع الأهلية التجارية لأحكام القانون المدني."},{"num":67,"type":"mcq","q":"يجب على التاجر أن يحفظ الدفاتر التجارية بعد اختتامها مدة:","o":["مدة سنة واحدة.","مدة عشر سنوات.","مدة 5 سنوات.","مدة 4 سنوات."],"answer":1,"orig_answer":null,"law":"other:قانون التجارة","article":"","status":"unverified","explanation":"قانون التجارة: يجب حفظ الدفاتر التجارية مدة عشر سنوات بعد اختتامها."},{"num":68,"type":"mcq","q":"أي من العبارات التالية غير صحيحة حسب قانون التجارة:","o":["لحامل السند، حق الرجوع على مظهريه وساحبه وغيرهم من الملتزمين به قبل الاستحقاق في حالة إفلاس ساحب السند المشروط عدم تقديمه للقبول.","ليس لحامل السند حق الرجوع على مظهريه وساحبه وغيرهم من الملتزمين به قبل الاستحقاق في حال الحجز على أمواله حجزاً غير مجد.","لحامل السند حق الرجوع على مظهريه وساحبه وغيرهم من الملتزمين به قبل الاستحقاق في حالة الامتناع عن القبول كلياً أو جزئياً.","لا شيء مما ذكر."],"answer":1,"orig_answer":null,"law":"other:قانون التجارة","article":"","status":"unverified","explanation":"قانون التجارة: لحامل السند الرجوع قبل الاستحقاق في حالة الحجز على أموال المسحوب عليه حجزاً غير مجد، فالعبارة (ب) خاطئة."},{"num":69,"type":"mcq","q":"تسقط بالتقادم كل دعوى ناشئة عن سند السحب تجاه قابله بمضي:","o":["10 سنوات من تاريخ الاستحقاق.","5 سنوات من تاريخ الاستحقاق.","4 سنوات من تاريخ الاستحقاق.","3 سنوات من تاريخ الاستحقاق."],"answer":1,"orig_answer":null,"law":"other:قانون التجارة","article":"","status":"unverified","explanation":"قانون التجارة: تسقط الدعاوى الناشئة عن سند السحب تجاه قابله بمضي خمس سنوات من تاريخ الاستحقاق."},{"num":70,"type":"mcq","q":"حسب قانون التجارة، أي من العبارات التالية تعتبر صحيحة:","o":["إذا اشتغل الموظفون والقضاة الممنوعون من الاتجار قانوناً بالمعاملات التجارية فتشملهم الأحكام القانونية المتعلقة بالصلح الواقي والإفلاس.","يعد العرف الخاص والعرف المحلي مرجحين على العرف العام.","لا يعد تاجراً من قام بمعاملة تجارية عرضاً إلا أن المعاملة المذكورة تكون خاضعة لأحكام قانون التجارة.","جميع ما ذكر."],"answer":3,"orig_answer":null,"law":"other:قانون التجارة","article":"","status":"unverified","explanation":"قانون التجارة: جميع العبارات صحيحة (شمول الممنوعين من الاتجار بالإفلاس والصلح الواقي، ترجيح العرف الخاص والمحلي، خضوع المعاملة العرضية لقانون التجارة)."},{"num":71,"type":"essay","q":"السؤال الأول (علامتان): السيد ماهر موظف متقاعد ويتقاضى راتب من الضمان الاجتماعي وقدره 3,000 دينار شهرياً ويقتطع منه 25 دينار شهرياً ضريبة دخل، ويعمل براتب شهري وقدره 2,000 دينار ولديه عقار مؤجر بقيمة 10,000 دينار سنوياً، ويدفع مسقفات على العقار المؤجر 100 دينار سنوياً ولديه وديعة بالبنك أرباحها السنوية 4,000 دينار يقتطع منها ضريبة دخل 200 دينار. إذا علمت أن السيد ماهر متزوج وزوجته لا تعمل ولديه ولدان في الجامعة القسط السنوي لكل طالب 2,000 دينار. المطلوب: احتساب ضريبة الدخل التي تستحق عليه عن العام 2021.","law":"income","article":"4, 9, 11, 12, 18","status":"valid","model_answer":"- الراتب التقاعدي: يعفى أول 2,500 دينار شهرياً (م4/أ/14) فالخاضع (3,000-2,500)×12 = 6,000 دينار.\n- الراتب من الوظيفة: 2,000×12 = 24,000 دينار.\n- الإيجار: 10,000 دينار (المسقفات لا تنزل من الدخل بل تقاص من الضريبة م18/ب).\n- فوائد الوديعة: الاقتطاع 5% (200 دينار) ضريبة قطعية للشخص الطبيعي فلا تدخل في الدخل (م12/أ/2 و12/ج).\n- الدخل الإجمالي = 40,000 دينار.\n- الإعفاءات (م9): شخصي 9,000 + معالين 9,000 + نفقات تعليم/علاج: 1,000 للمكلف + 1,000 للزوجة + 1,000 لكل ولد (2,000) = 22,000 (ضمن سقف 23,000).\n- الدخل الخاضع = 18,000 دينار.\n- الضريبة (م11/أ): 5,000×5% = 250، 5,000×10% = 500، 5,000×15% = 750، 3,000×20% = 600 = 2,100 دينار (لا مساهمة وطنية لأن الدخل أقل من 200,000).\n- يطرح: تقاص المسقفات 100 (لا تتجاوز ضريبة الإيجار 2,100×10,000/40,000 = 525) والمقتطع من التقاعد 25×12 = 300.\n- الضريبة المستحقة الواجبة الدفع = 2,100 - 100 - 300 = 1,700 دينار (مع افتراض عدم اقتطاع ضريبة من الراتب الوظيفي)."},{"num":72,"type":"essay","q":"السؤال الثاني (علامتان): أذكر البيانات الواجب توافرها في الفاتورة الضريبية التي يحررها المسجل في الشبكة العامة للضريبة على المبيعات عند بيع سلعة أو خدمة خاضعة للضريبة لأي شخص أو جهة.","law":"sales","article":"18","status":"unverified","model_answer":"- المادة (18/أ) تلزم المسجل بتحرير فاتورة ضريبية وفق التعليمات التنفيذية، ومن أبرز بياناتها:\n- اسم البائع المسجل وعنوانه ورقم تسجيله الضريبي.\n- الرقم المتسلسل للفاتورة وتاريخ إصدارها.\n- اسم المشتري وعنوانه ورقمه الضريبي إن كان مسجلاً.\n- وصف السلعة أو الخدمة وكميتها وسعر الوحدة وقيمتها.\n- نسبة الضريبة العامة/الخاصة ومقدارها.\n- القيمة الإجمالية شاملة الضريبة، وأي خصومات.\n- (حالياً تصدر الفاتورة عبر نظام الفوترة الوطني الإلكتروني وفق التعليمات)."},{"num":73,"type":"essay","q":"السؤال الثالث (علامتان): عدد الشروط الواجب توافرها لاعتبار الخدمة مصدرة خارج المملكة حسب التعليمات في قانون الضريبة العامة على المبيعات.","law":"sales","article":"4 مكرر","status":"unverified","model_answer":"- وفق تعليمات تصدير الخدمات (غير واردة في نص القانون):\n- أن تقدم الخدمة لشخص غير مقيم ليس له مكان عمل أو منشأة ثابتة في المملكة.\n- أن تستهلك الخدمة أو يستفاد منها خارج المملكة.\n- أن يتم قبض بدلها بعملة أجنبية محولة من الخارج (أو وفق ما تحدده التعليمات).\n- أن تكون موثقة بعقد/فاتورة ومستندات تثبت التصدير.\n- حالياً: تعتبر الخدمة موردة داخل المنطقة الضريبية إذا أداها مورد يمارس عمله أو له منشأة ثابتة أو عنوان دائم فيها (م4 مكرر/ج)، ويحدد استيراد الخدمات وفق (م4 مكرر/هـ)."},{"num":74,"type":"essay","q":"السؤال الرابع (علامتان): شخص يمارس نشاط تأجير السيارات السياحية والذي يصنف من الأنشطة الخدمية الخاضعة للضريبة وكانت إيراداته الشهرية كما يأتي: 1-2018 = 2,000 دينار، 2-2018 = 1,000، 3-2018 = 2,500، 4-2018 = 2,500، 5-2018 = 2,000، 6-2018 = 1,000، 7-2018 = 2,000، 8-2018 = 3,000، 9-2018 = 5,000، 10-2018 = 500، 11-2018 = 2,000، 12-2018 = 5,000، 1-2019 = 7,000، 2-2019 = 5,500، 3-2019 = 4,000، 4-2019 = 3,000 دينار. مجموع المبيعات لغاية شهر 12-2018 = 25,000 دينار. المطلوب: من خلال البيانات أعلاه متى يتوجب على الشخص التسجيل في ضريبة المبيعات؟","law":"sales","article":"13, 14","status":"valid","model_answer":"- حد التسجيل لمقدمي الخدمات (30,000) دينار وفق نظام حد التسجيل الصادر بمقتضى المادة (14/أ).\n- المادة (13/أ): يلتزم بالتسجيل عند أسبق التواريخ: نهاية 12 شهراً متتالية تبلغ فيها المبيعات حد التسجيل، أو نهاية 11 شهراً يتبين فيها أن المبيعات قد تبلغ الحد خلالها والشهر اللاحق.\n- المبيعات المتراكمة لنهاية 12-2018 = 25,000 (حسب الورقة) أي أقل من الحد.\n- الفترة المتحركة 2-2018 إلى 1-2019 = 25,000 - 2,000 + 7,000 = 30,000 دينار = حد التسجيل.\n- إذن يلتزم بالتسجيل بنهاية شهر 1-2019 (ويقدم طلب التسجيل خلال المدة المحددة بالتعليمات)، وإذا توقع ذلك مسبقاً فبنهاية الأحد عشر شهراً (12-2018) وفق البند (3)."},{"num":75,"type":"essay","q":"السؤال الخامس (علامتان): الشركة (س) شركة تجارية ذات مسؤولية محدودة مسجلة في المملكة الأردنية الهاشمية تقوم بشراء بضائع من مصنع مقره في الولايات المتحدة الأمريكية وتقوم بتحويل ثمن تلك البضائع من حسابها لدى البنوك الأردنية، وتقوم ببيع تلك البضائع لشركة أردنية (ص) شريطة ورود البوالص باسم الشركة (ص)، والتي تقوم بعملية التخليص ودفع الرسوم الجمركية المطلوبة. المطلوب: 1- تحديد مدى خضوع الشركة (س) لضريبة الدخل والمساهمة الوطنية وشرائح الضريبة. 2- تحديد مدى خضوع الشركة (س) لضريبة المبيعات وحد التسجيل.","law":"income","article":"3, 11; sales 4 مكرر, 13","status":"valid","model_answer":"1) ضريبة الدخل:\n- الشركة (س) شخص اعتباري مقيم مسجل في المملكة وتمارس نشاطها التجاري (الشراء والبيع والتحويل) من داخل المملكة، فأرباحها دخل متحقق في المملكة خاضع للضريبة (م3).\n- تخضع بنسبة (20%) من الدخل الخاضع (م11/ب/1) دون شرائح (الشرائح للشخص الطبيعي فقط م11/أ).\n- وتدفع مساهمة وطنية (1%) من الدخل الخاضع لباقي الأشخاص الاعتباريين (م11/و/1/هـ).\n2) ضريبة المبيعات:\n- السلع تشحن من الخارج وتصل باسم (ص) التي تخلص عليها، فالتوريد يتم والسلع خارج المنطقة الضريبية (م4 مكرر/أ) ولا تعتبر (س) مستورداً؛ لذا لا تستحق على (س) ضريبة مبيعات على هذه المبيعات ولا تحتسب ضمن حد التسجيل (75,000 للسلع).\n- المستورد هو (ص) وتستحق الضريبة عليه عند التخليص (م9/د، 26/ب) ويلتزم بالتسجيل خلال 30 يوماً من أول استيراد (م13/ب)."},{"num":76,"type":"essay","q":"السؤال السادس (علامة واحدة): على دائرة الجمارك العامة ضبط النقد والأدوات القابلة للتداول لحاملها في حالات محددة اذكرها؟","law":"aml","article":"24","status":"valid","model_answer":"- المادة (24/أ): تضبط دائرة الجمارك النقد والأدوات القابلة للتداول لحاملها في الحالات:\n1. الاشتباه بارتباطها بغسل الأموال أو الجريمة الأصلية المرتبطة بها أو تمويل الإرهاب.\n2. الإقرار الكاذب بإعطاء المعلومات.\n3. عدم قيام الشخص بتقديم الإقرار."},{"num":77,"type":"essay","q":"السؤال السابع (علامة واحدة): استناداً لقانون الأوراق المالية، عرّف التمويل على الهامش.","law":"securities","article":"55","status":"valid","model_answer":"- المادة (55/ب): التمويل على الهامش هو قيام الوسيط المالي بتمويل نسبة من قيمة الأوراق المالية التي يقوم بشرائها لعميله وفق التعليمات والقرارات الصادرة عن الهيئة وبموجب اتفاقية تنظم العلاقة بينهما."},{"num":78,"type":"essay","q":"السؤال الثامن (علامة ونصف): استناداً لقانون الأوراق المالية، عدّد الحالات التي يقوم المرخص له بالتمويل على الهامش بتحديد حقوقه.","law":"securities","article":"55","status":"valid","model_answer":"- المادة (55/د): للمرخص له تحديد حقوقه دون الرجوع للعميل في الحالات:\n1. وفاة العميل.\n2. صدور قرار بتصفية العميل أو شهر إفلاسه أو الحجر عليه.\n3. صدور أمر حجز عن سلطة مختصة على الأوراق المالية العائدة لعميله."},{"num":79,"type":"essay","q":"السؤال التاسع (علامتان): اذكر الأعمال الواجب أن يقوم بها مصفي شركة التضامن عند البدء في عمله؟","law":"companies","article":"37","status":"valid","model_answer":"- المادة (37/أ): على المصفي أن يبدأ عمله بـ:\n- الإعلان عن تصفية الشركة على الموقع الإلكتروني للدائرة.\n- إعداد قائمة بموجودات الشركة ومطلوباتها.\n- تحديد وتسوية ما للشركة من حقوق على الغير وما عليها من التزامات.\n- لا يتنازل عن الأموال أو يتصرف بها إلا بموافقة جميع الشركاء أو إذن المحكمة، ولا يمارس عملاً جديداً إلا لإتمام عمل سابق (37/ب)."},{"num":80,"type":"essay","q":"السؤال العاشر (علامتان): اذكر تعريف شركة المحاسبة [كذا في الورقة، والمقصود شركة المحاصة] وبيان فيما إذا تتمتع بالشخصية الاعتبارية وبيان فيما إذا كانت تخضع لأحكام وإجراءات التسجيل والترخيص؟","law":"companies","article":"49","status":"valid","model_answer":"- المادة (49/أ): شركة المحاصة شركة تجارية تنعقد بين شخصين أو أكثر يمارس أعمالها شريك ظاهر يتعامل مع الغير بحيث تقتصر الشركة على العلاقة الخاصة بين الشركاء، ويجوز إثباتها بجميع طرق الإثبات.\n- المادة (49/ب): لا تتمتع بالشخصية الاعتبارية ولا تخضع لأحكام وإجراءات التسجيل والترخيص."},{"num":81,"type":"essay","q":"السؤال الحادي عشر (علامة ونصف): اذكر شكل إدارة الشركة ذات المسؤولية المحدودة وعدّد أعضاء هيئة مديريها ومدة الإدارة؟","law":"companies","article":"60","status":"valid","model_answer":"- المادة (60/أ): يتولى إدارتها مدير أو هيئة مديرين من الشركاء أو غيرهم.\n- عدد أعضاء هيئة المديرين لا يقل عن اثنين ولا يزيد على سبعة.\n- مدة الإدارة أربع سنوات ويجوز أن ينص النظام على مدة أقل، وتنتخب الهيئة رئيساً ونائباً والمفوضين بالتوقيع."},{"num":82,"type":"essay","q":"السؤال الثاني عشر (علامتان): اذكر أربع من البرامج التي قدمتها المؤسسة العامة للضمان الاجتماعي خلال جائحة كورونا للمؤمن عليهم والمنشآت.","law":"social","article":"","status":"unverified","model_answer":"- برامج صدرت بأوامر الدفاع لا بنصوص القانون، ومنها:\n- برنامج تضامن (1 و2) لدعم العمالة غير المنظمة.\n- برنامج مساند (1 و2 و3) لصرف جزء من الرصيد الادخاري لتأمين التعطل وسلف على حساب التعطل.\n- برنامج حماية لدعم عمال المنشآت المتضررة.\n- برنامج استدامة (واستدامة++) لدعم أجور العاملين في القطاعات الأكثر تضرراً.\n- برنامج تمكين اقتصادي (1 و2) وتخفيض اشتراكات الشمول وتأجيل اشتراكات المنشآت."},{"num":83,"type":"essay","q":"السؤال الثالث عشر (علامة واحدة): عرّف عقد التأمين.","law":"insurance","article":"2","status":"valid","model_answer":"- المادة (2): عقد التأمين اتفاق تلتزم بمقتضاه شركة التأمين أن تؤدي إلى المؤمن له أو إلى المستفيد عوضاً مالياً أو أي منفعة أخرى عند تحقق الخطر المؤمن منه أو حدوث الواقعة المحددة في العقد مقابل مبلغ محدد أو أقساط يؤديها المؤمن له إلى شركة التأمين."},{"num":84,"type":"essay","q":"السؤال الرابع عشر (علامتان): يكون العقد عقد تأجير تمويلي إذا تحقق الشرطان التاليان، وبغض النظر عن شموله أو عدم شموله لخيار الشراء، اذكرهما:","law":"leasing","article":"3","status":"valid","model_answer":"- المادة (3/أ):\n1. أن يكون تملك المؤجر للمأجور من المورد بهدف تأجيره بموجب عقد التأجير.\n2. أن يلتزم المؤجر بتمكين المستأجر من الانتفاع بالمأجور مقابل بدل الإيجار."},{"num":85,"type":"essay","q":"السؤال الخامس عشر (علامة واحدة): عرّف الإعسار الوشيك.","law":"insolvency","article":"2","status":"valid","model_answer":"- المادة (2): الإعسار الوشيك هو الحالة التي يتوقع فيها أن يفقد المدين القدرة المستقبلية على سداد ديونه عند استحقاقها خلال ستة أشهر رغم قدرته الحالية على سدادها."},{"num":86,"type":"essay","q":"السؤال السادس عشر (علامتان): لا تسري أحكام قانون الإعسار على عدة جهات، عدّد أربعاً منها:","law":"insolvency","article":"3","status":"valid","model_answer":"- المادة (3/ب): لا يسري القانون على:\n1. البنوك.\n2. شركات التأمين.\n3. الجمعيات والنوادي ما لم يقرر مجلس الوزراء إخضاعها.\n4. الأشخاص الطبيعيين الخاضعين للقانون المدني (عدا أصحاب المهن المسجلين).\n5. الوزارات والدوائر الحكومية والمؤسسات الرسمية العامة والمؤسسات العامة.\n6. البلديات."},{"num":87,"type":"essay","q":"السؤال السابع عشر (علامة واحدة): أذكر هدفين من أهداف قانون تنظيم مهنة المحاسبة القانونية:","law":"accounting","article":"3","status":"valid","model_answer":"- المادة (3): من أهداف القانون:\n- تنظيم مزاولة المهنة والارتقاء بها.\n- ضمان الالتزام بمعايير المحاسبة والتدقيق المعتمدة بما يحمي الاقتصاد الوطني.\n- الارتقاء بالمستوى العلمي والمهني للمحاسبين القانونيين.\n- تأكيد الالتزام بقواعد سلوك المهنة وآدابها.\n- تعزيز دور المحاسب القانوني وحيدته واستقلاليته."},{"num":88,"type":"essay","q":"السؤال الثامن عشر (علامة واحدة): توقع اللجنة التأديبية عقوبات إذا كان المخالف محاسباً قانونياً، عدّد هذه العقوبات؟","law":"accounting","article":"36","status":"valid","model_answer":"- المادة (36/أ):\n1. التنبيه.\n2. الإنذار الخطي.\n3. تعليق التسجيل وإيقاف العمل بإجازة المزاولة لمدة لا تزيد على سنتين.\n4. إلغاء إجازة المزاولة وشطب اسم المحاسب القانوني نهائياً من سجل المزاولين."},{"num":89,"type":"essay","q":"السؤال التاسع عشر: عرّف: أ. سند السحب. ب. سند الأمر.","law":"other:قانون التجارة","article":"","status":"unverified","model_answer":"- قانون التجارة لسنة 1966 (غير مدرج):\n- سند السحب (الكمبيالة): محرر مكتوب وفق شكل معين يتضمن أمراً من الساحب إلى المسحوب عليه بأن يدفع لأمر شخص ثالث (المستفيد) مبلغاً معيناً في تاريخ معين أو قابل للتعيين أو بمجرد الاطلاع.\n- سند الأمر (السند لأمر): محرر مكتوب وفق شكل معين يتعهد بمقتضاه محرره بأن يدفع مبلغاً معيناً في تاريخ معين أو قابل للتعيين أو لدى الاطلاع لأمر شخص آخر هو المستفيد."}]},{"id":"2022-9a07502e","year":2022,"month":0,"label":"أسئلة متوقعة — الناظر","session":"أسئلة متوقعة — الناظر","src":"9a07502e.json","questions":[{"num":1,"type":"essay","q":"بينت المادة (259) من قانون الشركات الحالات الأربع التي يمكن للشركة المساهمة العامة أن تصفى بموجبها تصفية اختيارية. المطلوب: اذكر ثلاثة منها؟","law":"companies","article":"259","status":"valid","model_answer":"المادة (259): تصفى الشركة المساهمة العامة تصفية اختيارية في أي من الحالات:\n- بانتهاء المدة المعينة للشركة ما لم تقرر الهيئة العامة تمديدها.\n- بإتمام أو انتفاء الغاية التي تأسست من أجلها أو باستحالة إتمامها.\n- بصدور قرار من الهيئة العامة بفسخها وتصفيتها.\n- في الحالات الأخرى التي ينص عليها نظام الشركة."},{"num":2,"type":"essay","q":"تنقضي شركة التضامن في أي من الحالات التالية: (اذكرها) — 1- باتفاق الشركاء جميعهم على حل الشركة أو دمجها في شركة أخرى. 2- بانتهاء المدة المحددة للشركة سواء أكانت المدة الأصلية لها أو التي مددت إليها باتفاق جميع الشركاء. بانتهاء الغاية التي أسست من أجلها. 3- ببقاء شريك واحد فيها، مع مراعاة ما ورد في الفقرة (د) من المادة (28) من هذا القانون. 4- بإشهار إفلاس الشركة، وفي هذه الحالة يترتب على إفلاس الشركة إفلاس الشركاء. 5- بإشهار إفلاس أحد الشركاء فيها أو بالحجر عليه، ما لم يقرر باقي الشركاء جميعهم استمرار الشركة بينهم وفقاً لعقد الشركة. 6- بفسخ الشركة بحكم قضائي. 7- بشطب تسجيل الشركة بقرار من المراقب بمقتضى أحكام هذا القانون.","law":"companies","article":"32","status":"changed","model_answer":"المادة (32) بعد التعديل: تنقضي شركة التضامن:\n- باتفاق الشركاء جميعهم على حلها أو دمجها.\n- بانتهاء مدتها الأصلية أو الممددة باتفاق جميع الشركاء.\n- بانتهاء الغاية التي أسست من أجلها.\n- ببقاء شريك واحد فيها مع مراعاة المادة (28/د).\n- بتصفية الشركة وشطب تسجيلها وفقاً لأحكام قانون الإعسار (بدلاً من «إشهار إفلاس الشركة وإفلاس الشركاء»).\n- بإشهار إعسار أحد الشركاء وخضوعه للتصفية وفق قانون الإعسار أو بالحجر عليه، ما لم يقرر باقي الشركاء الاستمرار (بدلاً من «إشهار إفلاس أحد الشركاء»).\n- بفسخ الشركة بحكم قضائي.\n- بشطب تسجيلها بقرار من المراقب.\nالتغيير: حلّت أحكام الإعسار محل الإفلاس."},{"num":3,"type":"essay","q":"يتولى إدارة الشركة (ذات المسؤولية المحدودة) مدير أو هيئة مديرين لا يقل عدد أعضائها عن اثنين ولا يزيد على سبعة سواء كانوا من الشركاء أو من غيرهم وذلك وفقاً لما ينص عليه النظام الأساسي للشركة لمدة أربع سنوات ويجوز أن ينص النظام على مدة أقل من ذلك وتنتخب هيئة المديرين رئيساً لها ونائباً له والمفوضين بالتوقيع عن الشركة.","law":"companies","article":"60","status":"valid","model_answer":"المادة (60/أ): مدير أو هيئة مديرين من 2 إلى 7 أعضاء (من الشركاء أو غيرهم) لمدة أربع سنوات ويجوز للنظام النص على مدة أقل؛ وتنتخب الهيئة رئيساً ونائباً والمفوضين بالتوقيع."},{"num":4,"type":"essay","q":"يكون لمدير الشركة ذات المسؤولية المحدودة أو لهيئة المديرين فيها الصلاحيات الكاملة في إدارة الشركة في الحدود التي يبينها نظامها. وتعتبر الأعمال والتصرفات التي يقوم بها أو يمارسها المدير أو هيئة المديرين باسم الشركة ملزمة لها في مواجهة الغير الذي يتعامل مع الشركة بحسن نية بغض النظر عن أي قيد يرد في نظام الشركة أو عقد تأسيسها. يعد الغير الذي يتعامل مع الشركة حسن النية ما لم يثبت غير ذلك على أنه لا يلزم ذلك الغير بالتحقق من وجود أي قيد على صلاحيات المدير أو هيئة المديرين على سلطتهم في إلزام الشركة بموجب عقدها أو نظامها.","law":"companies","article":"60","status":"valid","model_answer":"المادة (60/ب، ج):\n- للمدير/هيئة المديرين الصلاحيات الكاملة في الإدارة ضمن حدود النظام، وتصرفاتهم باسم الشركة ملزمة لها تجاه الغير حسن النية رغم أي قيد في النظام أو عقد التأسيس.\n- يفترض حسن نية الغير ما لم يثبت العكس، ولا يلزم بالتحقق من القيود على صلاحيات المدير."},{"num":5,"type":"essay","q":"تلتزم شركة التضامن التي يبلغ رأسمالها مائة ألف دينار أو أكثر بتعيين مدقق حسابات قانوني ينتخب بأكثرية الشركاء.","law":"companies","article":"24","status":"valid","model_answer":"المادة (24/ب): شركة التضامن التي يبلغ رأسمالها 100,000 دينار فأكثر تلتزم بتعيين مدقق حسابات قانوني ينتخب بأكثرية الشركاء (وتلتزم بمسك دفاتر محاسبية منظمة إذا بلغ رأسمالها 10,000 دينار فأكثر – 24/أ)."},{"num":6,"type":"essay","q":"يكون نصاب الاجتماع غير العادي للهيئة العامة للشركة ذات المسؤولية المحدودة قانونياً بحضور عدد من الشركاء يمثلون (75%) من الحصص المكونة لرأسمال الشركة على الأقل أصالة ووكالة، ما لم ينص نظام الشركة على أغلبية أعلى وإذا لم يتوفر النصاب خلال ساعة من الوقت المحدد لبدء الاجتماع فيؤجل الاجتماع إلى موعد آخر خلال عشرة أيام من التاريخ المحدد للاجتماع الأول ويعاد تبليغ الشركاء الذين لم يحضروا ويكون النصاب في الاجتماع الثاني قانونياً بحضور (50%) على الأقل من الحصص المكونة لرأسمال الشركة أصالة ووكالة ما لم ينص نظام الشركة على أغلبية أعلى، وإذا لم يتوفر هذا النصاب يلغى الاجتماع مهما كانت أسباب الدعوة إليه.","law":"companies","article":"65","status":"valid","model_answer":"المادة (65/ب): النصاب 75% من الحصص أصالة ووكالة؛ إن لم يتوفر خلال ساعة يؤجل خلال 10 أيام ويكون النصاب في الاجتماع الثاني 50% على الأقل، وإلا يلغى الاجتماع. (للمقارنة: الاجتماع العادي أكثر من نصف رأس المال، والثاني خلال 15 يوماً بمن حضر – 65/أ)."},{"num":7,"type":"essay","q":"أ- يقدم مجلس إدارة الشركة المساهمة العامة طلب تخفيض رأس مالها المكتتب به إلى المراقب مع الأسباب الموجبة له بعد أن تقرر الهيئة العامة للشركة الموافقة على التخفيض بأكثرية لا تقل عن (75%) خمسة وسبعين بالمائة من الأسهم الممثلة في اجتماعها غير العادي الذي تعقده لهذه الغاية، وترفق بالطلب قائمة بأسماء دائني الشركة ومقدار دين كل منهم وعنوانه وبيان بموجودات الشركة والتزاماتها، على أن تكون قائمة الدائنين للشركة وبيان موجوداتها والتزاماتها مصدقة من مدقق حساباتها.\nب- يبلغ المراقب الدائنين الواردة أسماؤهم في القائمة المقدمة من قبل الشركة إشعاراً يتضمن قرار هيئتها العامة بتخفيض رأس مال الشركة المكتتب به وينشر الإشعار في صحيفتين يوميتين محليتين على نفقة الشركة، ولكل دائن أن يقدم إلى المراقب خلال مدة لا تزيد على ثلاثين يوماً من تاريخ نشر الإشعار لآخر مرة اعتراضاً خطياً على تخفيض رأس مال الشركة، فإذا لم يتمكن المراقب من تسوية الاعتراضات التي قدمت إليه خلال ثلاثين يوماً من تاريخ انتهاء المدة المحددة لتقديمها فيحق لأصحابها مراجعة المحكمة بشأن ما ورد في اعتراضاتهم خلال ثلاثين يوماً من تاريخ انتهاء المدة التي منحت للمراقب لتسويتها وترد أي دعوى تقدم بعد هذه المدة.\nج- إذا تبلغ المراقب إشعاراً خطياً من المحكمة بإقامة أي دعوى لديها خلال المدة المنصوص عليها في الفقرة (ب) من هذه المادة بالطعن في تخفيض رأس مال الشركة المكتتب به، فيترتب عليه أن يوقف إجراءات التخفيض إلى أن يصدر قرار المحكمة في الدعوى ويكتسب الدرجة القطعية، على أن تعتبر الدعوى في هذه الحالة من الدعاوى ذات الصفة المستعجلة بمقتضى أحكام قانون أصول المحاكمات المدنية المعمول به.\nد- إذا لم تقدم أي دعوى إلى المحكمة بالطعن في قرار الهيئة العامة للشركة المساهمة العامة بتخفيض رأس مالها المكتتب به أو أقيمت دعوى وردتها المحكمة واكتسب الحكم الدرجة القطعية فيترتب على المراقب متابعة النظر في تخفيض رأس مال الشركة، وأن يرفع تنسيبه بشأنه إلى الوزير ليصدر القرار الذي يراه مناسباً فيه فإذا قرر الموافقة عليه تم تسجيله ونشره من قبل المراقب على نفقة الشركة وفقاً للإجراءات المنصوص عليها في هذا القانون وبحيث يحل رأس المال المخفض للشركة حكماً محل رأس مالها المدرج في عقد تأسيسها ونظامها.\nهـ- لا تشترط موافقة المراقب والدائنين على تخفيض الجزء غير المكتتب به من رأس المال المصرح به.","law":"companies","article":"115","status":"valid","model_answer":"المادة (115):\n- قرار الهيئة العامة غير العادية بأكثرية لا تقل عن 75% من الأسهم الممثلة، ويرفق بالطلب قائمة الدائنين وبيان الموجودات والالتزامات مصدقة من المدقق.\n- يبلغ المراقب الدائنين وينشر في صحيفتين؛ اعتراض الدائن خلال 30 يوماً من آخر نشر؛ للمراقب 30 يوماً للتسوية؛ ثم 30 يوماً لمراجعة المحكمة.\n- رفع الدعوى يوقف إجراءات التخفيض حتى الحكم القطعي (دعوى مستعجلة).\n- عند عدم الطعن أو رده: تنسيب المراقب للوزير، والتسجيل والنشر على نفقة الشركة.\n- لا تشترط موافقة المراقب والدائنين لتخفيض الجزء غير المكتتب به من رأس المال المصرح به."},{"num":8,"type":"mcq","q":"وفقاً لقانون ضريبة الدخل فإن نسبة الضريبة لقطاع التأجير التمويلي لسنة 2019 ب:","o":["24% ضريبة دخل ونسبة 1% لحساب المساهمة الوطنية.","24% ضريبة دخل ونسبة 4% لحساب المساهمة الوطنية.","24% ضريبة دخل ونسبة 3% لحساب المساهمة الوطنية.","20% ضريبة دخل ونسبة 1% لحساب المساهمة الوطنية."],"answer":1,"orig_answer":1,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ب/2): 24% للأشخاص الاعتباريين الذين يمارسون أنشطة التأجير التمويلي، والمادة (11/و/1/ج): 4% من الدخل الخاضع لحساب المساهمة الوطنية."},{"num":9,"type":"mcq","q":"تملك شركة س 70% من أسهم شركة ص، بتاريخ 2020/1/1 حصلت شركة ص على قرض من شركة س لتمويل أنشطتها، قيمة القرض 1,200,000 دينار وبفائدة 3%، بلغ رأس المال المدفوع لشركة ص 100,000 دينار، ومتوسط حقوق الملكية 200,000 دينار، أن مصروف الفائدة المقبول تنزيله ضريبياً لشركة ص لسنة 2020:","o":["10,800 دينار.","18,000 دينار.","36,000 دينار.","لا شيء مما ذكر."],"answer":1,"orig_answer":1,"law":"income","article":"6","status":"valid","explanation":"المادة (6/ب/2): فوائد الأشخاص ذوي العلاقة تنزل بحدود نسبة 3:1 للدين إلى رأس المال المدفوع أو متوسط حقوق الملكية أيهما أكبر: (3×200,000 ÷ 1,200,000) × 36,000 = 18,000 دينار."},{"num":10,"type":"mcq","q":"بتاريخ 01/03/2021 أعلنت شركة الشرق لتجارة السيارات عن أسماء الفائزين بجوائزها السنوية، وهي عبارة عن 3 سيارات قيمة كل منها 20,000 دينار بهذا التاريخ، وتم تسليم السيارات للفائزين بتاريخ 2020/12/01؛ حيث كان السعر السوقي بتاريخ التسليم 19,000 دينار لكل سيارة. ضريبة الدخل الواجب اقتطاعها وتوريدها من الشركة مقابل هذه الجوائز:","o":["5,700 دينار.","9,000 دينار.","6,000 دينار.","8,550 دينار."],"answer":3,"orig_answer":3,"law":"income","article":"12","status":"valid","explanation":"المادة (12/أ/3): يقتطع 15% من الجوائز التي تزيد قيمة كل منها على ألف دينار كضريبة قطعية، والدخل العيني يقيّم بسعر السوق بتاريخ الاستحقاق (3/ب): 19,000×3×15% = 8,550 دينار (حسب حل المُعِد؛ تواريخ السؤال كما وردت في الأصل)."},{"num":11,"type":"mcq","q":"شخص غير أردني وغير مقيم بالأردن له دخل من عقار مؤجر بقيمة 30,000، وهو معيل لعائلته المقيمة في الأردن، فإن ضريبة الدخل المستحقة عليه عام 2000 [كذا في الأصل، والمقصود غالباً 2020] هي:","o":["2,750 دينار.","750 دينار.","1,050 دينار.","5,000 دينار."],"answer":3,"orig_answer":3,"law":"income","article":"11","status":"valid","explanation":"الإعفاءات في المادة (9/أ) للشخص الطبيعي المقيم، والمادة (9/د) تمنح إعفاء المعالين لغير المقيم الأردني فقط؛ فلا إعفاء له. الضريبة حسب الشرائح (11/أ): 250+500+750+1000+2,500 = 5,000 دينار."},{"num":12,"type":"mcq","q":"أظهرت قائمة الدخل لشركة الصلب والحديد الصناعية لسنة 2020 صافي دخل 500,000 دينار، وظهر في قائمة الدخل مصاريف إدارية وعمومية 100,000 دينار، وأرباح واستثمارات في شركات محلية 40,000 دينار، إن ضريبة الدخل المستحقة على الشركة:","o":["76,500 دينار.","81,600 دينار.","66,000 دينار.","88,000 دينار."],"answer":1,"orig_answer":1,"law":"income","article":"11","status":"valid","explanation":"حسب حل المُعِد: يضاف 25% من توزيعات الأرباح المعفاة (4/أ/8) كمصاريف غير مقبولة: 500,000+10,000 = 510,000 × 20% (11/ب/1) = 102,000، ويخفض 20% للنشاط الصناعي لسنة 2020 (11/ج/1) = 81,600 دينار."},{"num":13,"type":"essay","q":"أبرمت شركة الاتحاد عقد تأمين على المباني التي تملكها مع شركة ما وراء البحار للتأمين ولمدة سنة كاملة يبدأ العقد بتاريخ 2020/9/29 وينتهي بتاريخ 2021/9/28، حيث بلغت قيمة عقد التأمين 50,000 دينار، وقامت شركة التأمين بإعادة تأمين 75% من قيمة العقد لدى شركة زيورخ السويسرية. المطلوب احتساب قيمة مخصص الأقساط غير المكتسبة الواجب تنزيله في 2020/12/31؟","law":"income","article":"6","status":"valid","model_answer":"- المادة (6/د): تنزل مخصصات شركات التأمين المتعلقة بالأقساط غير المكتسبة، ويضاف ما نُزّل منها إلى دخل الفترة التالية.\n- المخصص = ((قيمة العقد − حصة معيدي التأمين) ÷ 365) × الأيام المتبقية في الفترة التالية.\n- = ((50,000 − 37,500) ÷ 365) × 271 يوماً (من 2021/1/1 حتى 2021/9/28) ≈ 9,281 دينار."},{"num":14,"type":"essay","q":"تلغى صفة الدين غير العامل لجميع حسابات العميل لدى البنك الواحد إذا تضمنت حسابات العميل وحسابات كفيله ديناً عاملاً لدى البنك نفسه ولا تعتبر المخصصات المتعلقة بحسابات العميل من المصاريف المقبولة ضريبياً.","law":"income","article":"6","status":"unverified","model_answer":"- المادة (6/ج): تنزل مخصصات البنوك وفق قانون البنوك، ويلتزم البنك بتخفيض المخصص الخاص للائتمان غير العامل عند تحويله إلى ائتمان عامل أو تحصيله أو شطبه، ويظهر التخفيض في دخله الإجمالي.\n- القاعدة الواردة (إلغاء صفة الدين غير العامل إذا تضمنت حسابات العميل أو كفيله ديناً عاملاً) مصدرها النظام/التعليمات التنفيذية وليست نصاً في القانون."},{"num":15,"type":"essay","q":"تتولى الهيئة العليا المهام والصلاحيات التالية: 1- اعتماد معايير المحاسبة ومعايير تدقيق الحسابات الواجبة التطبيق بناء على تنسيب المجلس. 2- تشكيل لجنة ترخيص المهنة ووضع التعليمات اللازمة لتنظيم عملها وتحديد صلاحياتها وكيفية إجراء الامتحانات وسائر الأمور المتعلقة بها. 3- المصادقة على منح إجازة المزاولة بناء على تنسيب لجنة الترخيص وإلغاء هذه الإجازة بناء على تنسيب المجلس. 4- النظر في الاعتراضات المقدمة على قرارات المجلس. 5- تشكيل اللجان اللازمة لمساعدة الهيئة العليا على القيام بمهامها وتحديد صلاحياتها. 6- إصدار التعليمات المتعلقة بتنظيم عملها والتعليمات اللازمة لتنفيذ أحكام هذا القانون والأنظمة الصادرة بمقتضاه. 7- إعداد مشروعات التشريعات المتعلقة بالمهنة بالتعاون والتنسيق مع المجلس. 8- اعتماد المعاهد المهنية للمحاسبين القانونيين أو ما يماثلها.","law":"accounting","article":"5","status":"valid","model_answer":"المادة (5): مهام الهيئة العليا: اعتماد معايير المحاسبة والتدقيق بتنسيب المجلس؛ تشكيل لجنة الترخيص ووضع تعليماتها والامتحانات؛ المصادقة على منح إجازة المزاولة (بتنسيب لجنة الترخيص) وإلغائها (بتنسيب المجلس)؛ النظر في الاعتراضات على قرارات المجلس؛ تشكيل اللجان؛ إصدار التعليمات؛ إعداد مشروعات التشريعات بالتنسيق مع المجلس؛ اعتماد المعاهد المهنية."},{"num":16,"type":"mcq","q":"يشترط للاستفادة من بدل إجازة الأمومة:","o":["أن تكون المؤمن عليها مشمولة بأحكام القانون لمدة لا تقل عن (9) أشهر قبل الولادة.","أن تكون المؤمن عليها مشمولة بأحكام القانون لمدة لا تقل عن (6) أشهر قبل الولادة.","أن تكون المؤمن عليها مشمولة بأحكام القانون لمدة لا تقل عن (12) شهراً قبل الولادة.","لا شيء مما ذكر."],"answer":1,"orig_answer":1,"law":"social","article":"44","status":"valid","explanation":"المادة (44/أ): أن تكون مشمولة بتأمين الأمومة خلال الأشهر الستة الأخيرة التي تسبق استحقاقها إجازة الأمومة، وأن تثبت الولادة بشهادة رسمية."},{"num":17,"type":"essay","q":"يستحق المؤمن عليه راتب اعتلال العجز الكلي الطبيعي الدائم أو راتب اعتلال العجز الجزئي الطبيعي الدائم شريطة تحقق ما يلي: 1- انتهاء خدمته. 2- أن يتقدم بطلب تخصيص راتب الاعتلال خلال مدة لا تتجاوز ستة أشهر من تاريخ انتهاء الخدمة. 3- أن لا تقل اشتراكاته الفعلية عن (60) اشتراكاً منها (24) اشتراكاً متصلاً. 4- ثبوت حالة العجز بقرار من المرجع الطبي.","law":"social","article":"67","status":"valid","model_answer":"المادة (67/أ): انتهاء الخدمة؛ تقديم الطلب خلال 6 أشهر من انتهاء الخدمة؛ اشتراكات فعلية لا تقل عن 60 منها 24 متصلة؛ ثبوت العجز بقرار المرجع الطبي."},{"num":18,"type":"essay","q":"يستحق المؤمن عليه راتب تقاعد الوفاة الطبيعية إذا وقعت الوفاة خلال خدمته المشمولة بأحكام هذا القانون شريطة أن يكون قد سدد ما لا يقل عن (24) اشتراكاً فعلياً منها (6) اشتراكات متصلة.","law":"social","article":"66","status":"valid","model_answer":"المادة (66/أ): 24 اشتراكاً فعلياً منها 6 متصلة إذا وقعت الوفاة خلال الخدمة؛ والراتب 50% من متوسط أجر آخر 12 اشتراكاً (66/ب)."},{"num":19,"type":"essay","q":"يقصد بشرط الاختراق الشرط الوارد في عقد إعادة التأمين والذي يقضي بمسؤولية معيد التأمين في حدود حصته من الخسارة المعاد تأمينها لديه تجاه المؤمن له والمستفيد في الحالات التي يتعذر على المؤمن الوفاء بالتزاماته تجاه المؤمن له أو المستفيد كتصفية شركة التأمين وبحيث تنشأ علاقة مباشرة بين معيد التأمين والمؤمن له والمستفيد.","law":"insurance","article":"71","status":"valid","model_answer":"المادة (71/ب): التعريف كما ورد؛ و(71/أ): يحق للمؤمن له أو المستفيد الانتفاع من شرط الاختراق ولا يجوز لأي جهة الاعتراض على تفعيله."},{"num":20,"type":"essay","q":"- يخضع عمل وكيل الإعسار لإشراف المحكمة ورقابة الدائنين أو من يمثلهم في الحدود المبينة في هذا القانون.\n- للمحكمة وللجنة الدائنين، من وقت لآخر أن تكلف وكيل الإعسار بتزويدها بمعلومات محددة أو بتقديم تقرير عن سير إجراءات الإعسار وإدارة ذمة الإعسار.","law":"insolvency","article":"52","status":"valid","model_answer":"المادة (52/أ، ب): إشراف المحكمة ورقابة الدائنين على وكيل الإعسار، وللمحكمة ولجنة الدائنين تكليفه بتقديم معلومات أو تقارير عن سير الإجراءات وإدارة ذمة الإعسار."},{"num":21,"type":"mcq","q":"لا يجوز لأي شخص طلب شراء أوراق مالية أو مبادلتها بهدف تملك ما يزيد عن النسب التالية من الأوراق المالية المصدرة من مصدر عام إلا عن طريق عرض تملك عام وفقاً للتعليمات التي يصدرها المجلس:","o":["(33.3%).","(51%).","(40%).","(50%)."],"answer":2,"orig_answer":2,"law":"securities","article":"45","status":"valid","explanation":"المادة (45/أ): لا يجوز طلب شراء أو مبادلة أوراق مالية بهدف تملك (40%) أو أكثر من أوراق مصدر عام إلا بعرض تملك عام وفقاً لنظام يصدر لهذه الغاية (النص الحالي «40% أو أكثر» و«نظام» بدل «تعليمات»؛ الإجابة لم تتغير)."},{"num":22,"type":"essay","q":"المعتمد: الشخص الطبيعي الذي يكون عضواً في مجلس إدارة شركة خدمات مالية أو هيئة مديريها أو مديراً أو مسؤولاً إدارياً أو موظفاً فيها، أو ممن يشغل وضعاً مشابهاً في الشركة أو يمارس صلاحيات مماثلة لدى وسيط مالي أو وسيط لحسابه أو أمين استثمار أو مدير استثمار أو مستشار مالي أو مدير إصدار أو شركة خدمات مالية ولا يشمل ذلك المستخدمين في الوظائف المكتبية والخدمات وتلك التي لا علاقة لها بالنشاط المتعلق بالأوراق المالية.","law":"securities","article":"2","status":"valid","model_answer":"المادة (2): تعريف المعتمد كما ورد — شخص طبيعي (عضو مجلس/هيئة مديرين، مدير، مسؤول إداري، موظف أو من في حكمهم) لدى شركة خدمات مالية أو وسيط أو أمين/مدير استثمار أو مستشار مالي أو مدير إصدار، ويستثنى موظفو الوظائف المكتبية والخدماتية وغير المتعلقة بنشاط الأوراق المالية."},{"num":23,"type":"essay","q":"يعتبر مخالفة لأحكام هذا القانون قيام المرخص له أو المعتمد بأي مما يلي:\nأ- إساءة التصرف بأموال العملاء أو المساهمين بما في ذلك إساءة توظيفها أو استخدامها.\nب- ممارسة الخداع والتضليل والأعمال المحظورة.\nج- التأثير سلباً على المنافسة وذلك بالتلاعب بنسب العمولات أو ببدل الخدمات التي يتقاضاها أي منهما من العملاء أو الحد من الخدمات المقدمة سواء كان ذلك بشكل منفرد أو بالتواطؤ مع الغير.\nد- التأثير سلباً أو محاولة التأثير سلباً وبأي شكل من الأشكال على سوق رأس المال سواء كان ذلك بشكل منفرد أو بالتواطؤ مع الغير.","law":"securities","article":"56","status":"valid","model_answer":"المادة (56): إساءة التصرف بأموال العملاء/المساهمين؛ الخداع والتضليل والأعمال المحظورة؛ التأثير سلباً على المنافسة بالتلاعب بالعمولات أو بدل الخدمات أو الحد منها؛ التأثير أو محاولة التأثير سلباً على سوق رأس المال منفرداً أو بالتواطؤ."},{"num":24,"type":"essay","q":"أ- على كل مصدر أن يقدم إلى الهيئة، ووفقاً للتعليمات التي يصدرها المجلس، التقارير الدورية المبينة أدناه وأن يقوم بنشرها:\n1- تقريراً سنوياً، يتضمن البيانات المالية مدققة من مدقق حسابات قانوني خلال تسعين يوماً من تاريخ انتهاء سنته المالية.\n2- تقرير ربع سنوي يقدم خلال ثلاثين يوماً من تاريخ انتهاء الربع المعني مراجعاً من مدقق حسابات قانوني.\n3- تقريراً عن نتائج أعماله الأولية بعد قيام مدقق حسابات قانوني بإجراء عملية المراجعة الأولية لها، وذلك خلال خمسة وأربعين يوماً من انتهاء سنته المالية حداً أعلى.\n4- تقريراً يتعلق بانتخاب مجلس الإدارة وأي تغيير في تشكيلة أو هوية أي من أعضائه.","law":"securities","article":"43","status":"valid","model_answer":"المادة (43/أ): سنوي مدقق خلال 90 يوماً؛ ربع سنوي مراجَع خلال 30 يوماً؛ نتائج أولية مراجعة خلال 45 يوماً حداً أعلى؛ تقرير عن انتخاب مجلس الإدارة وأي تغيير فيه. و(43/د): بيان علني فوري بأي معلومة جوهرية."},{"num":25,"type":"essay","q":"أ- يتخذ الصندوق أحد الشكلين التاليين:\n1- الصندوق المفتوح وهو صندوق ذو رأسمال متغير تتم زيادة رأسماله من خلال طرح وحدات استثمارية جديدة ويتم تخفيض رأسماله من خلال استرداد وحداته الاستثمارية خلال الفترة المحددة في نظامه الأساسي ونشرة إصداره.\n2- الصندوق المغلق وهو صندوق ذو رأسمال ثابت تتم زيادة رأسماله وتخفيضه وفقاً لأحكام هذا النظام ونظامه الأساسي ونشرة إصداره.\nب- يتكون رأسمال الصندوق من مجموع القيم الاسمية لوحداته الاستثمارية عند التأسيس المحددة في النظام الأساسي للصندوق ونشرة إصداره، ويقسم إلى وحدات استثمارية متساوية في الحقوق تسدد قيمتها نقداً دفعة واحدة عند الاكتتاب بها، وتكون مسؤولية حملة الوحدات الاستثمارية محدودة بمقدار مساهمتهم في رأسمال الصندوق.\nج- يكون لكل وحدة استثمارية صوت واحد في اجتماعات الهيئة العامة للصندوق.\nد- يشترط أن لا يقل رأسمال الصندوق عند التأسيس عن مليوني دينار أردني أو ما يعادل ذلك من العملات الأجنبية الأخرى.\nهـ- يشترط أن لا تقل نسبة مساهمة مدير الاستثمار والشركات الحليفة له عن (5%) وأن لا تتجاوز (25%) من رأسمال الصندوق عند التأسيس، ولا يجوز التصرف في مساهمته ومساهمة الشركات الحليفة له قبل مضي سنتين من تاريخ منح الصندوق حق الشروع بالعمل، على أن لا تقل نسبة مساهمته والشركات الحليفة له في أي وقت بعد التأسيس عن (5%) من رأسماله.","law":"other:نظام صناديق الاستثمار المشترك","article":"","status":"unverified","model_answer":"- مصدر النص نظام صناديق الاستثمار المشترك (غير متوفر نصه هنا)؛ وقانون الأوراق المالية (المادتان 94، 95) يميز بين الصندوق المفتوح (يصدر وحداته ويستردها على أساس صافي قيمة الأصول) والمغلق (له التحول إلى مفتوح إذا نص نظامه على ذلك).\n- النقاط المتوقعة: الشكلان (مفتوح متغير رأس المال / مغلق ثابت)؛ وحدات متساوية تسدد نقداً دفعة واحدة؛ صوت لكل وحدة؛ حد أدنى لرأس المال مليونا دينار (الفقرة المظللة في الأصل)؛ مساهمة مدير الاستثمار وحلفائه 5%–25% عند التأسيس، وحظر التصرف بها سنتين، ولا تقل بعدها عن 5%."},{"num":26,"type":"essay","q":"مدير الاستثمار: الشخص الذي يمارس إدارة محافظ الأوراق المالية لحساب الغير بما في ذلك إدارة صندوق الاستثمار المشترك.","law":"securities","article":"2","status":"valid","model_answer":"المادة (2): مدير الاستثمار هو الشخص الذي يمارس إدارة محافظ الأوراق المالية لحساب الغير بما في ذلك إدارة صندوق الاستثمار المشترك."},{"num":27,"type":"mcq","q":"أي من العبارات التالية لا يعتبر صحيحاً بموجب قانون التجارة رقم (12) لعام 1966:","o":["إذا اشتغل الموظفون والقضاة الممنوعون من الاتجار قانوناً بالمعاملات التجارية فتشملهم الأحكام القانونية المتعلقة بالصلح الواقي من الإفلاس.","إذا اشتغل الموظفون والقضاة الممنوعون من الاتجار قانوناً بالمعاملات التجارية فتشملهم الأحكام القانونية المتعلقة بالصلح الواقي من الإفلاس.","لا تعد الدولة ودوائرها ذات شخصية اعتبارية من التجار وإن قامت بمعاملات تجارية.","يعد تاجراً كل من أعلن في الصحف أو النشرات أو أية واسطة أخرى عن المحل الذي أسسه وفتحه للاشتغال بالأعمال التجارية."],"answer":1,"orig_answer":1,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","explanation":"الخياران (أ) و(ب) متطابقان في الأصل (خطأ في الورقة) والمظلل هو (ب). العبارة غير الصحيحة: الموظفون والقضاة الممنوعون من الاتجار إذا اشتغلوا بالتجارة تطبق عليهم أحكام الإفلاس ولا يستفيدون من الصلح الواقي — قانون التجارة 1966 غير متوفر للتحقق."},{"num":28,"type":"mcq","q":"جميع الأمور التالية صحيحة بخصوص الوكالة التجارية حسب قانون التجارة باستثناء:","o":["الوكيل الذي لم يتلق تعليمات إلا في شأن جزء من العمل يعد مطلق اليد في الجزء الباقي.","في المواد التجارية يستحق الوكيل الأجر في جميع الأحوال ما لم يكن هنالك نص مخالف.","الوكالة التجارية إن احتوت على توكيل مطلق تجيز الأعمال غير التجارية وإن لم يرد نص.","تكون الوكالة تجارية عندما تختص بمعاملات تجارية."],"answer":2,"orig_answer":2,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","explanation":"حسب الورقة (الخيار المظلل ج): الوكالة التجارية المطلقة لا تجيز الأعمال غير التجارية إلا بنص صريح — من أحكام الوكالة في قانون التجارة 1966، غير متوفر للتحقق."},{"num":29,"type":"essay","q":"الأوراق التجارية هي أسناد قابلة للتداول بمقتضى أحكام هذا القانون وتشتمل على ما يلي:\nأ- سند السحب ويسمى أيضاً البوليصة أو السفتجة وهو محرر مكتوب وفق شرائط مذكورة في القانون ويتضمن أمراً صادراً من شخص هو الساحب إلى شخص آخر هو المسحوب عليه بأن يدفع لأمر شخص ثالث هو المستفيد أو حامل السند مبلغاً معيناً بمجرد الاطلاع أو في ميعاد معين أو قابل للتعيين.\nب- سند الأمر ويسمى أيضاً السند الإذني ومعروف باسم الكمبيالة وهو محرر مكتوب وفق شرائط مذكورة في القانون ويتضمن تعهد محرره بدفع مبلغ معين بمجرد الاطلاع أو في ميعاد معين أو قابل للتعيين لأمر شخص آخر هو المستفيد أو حامل السند.\nج- الشيك وهو محرر مكتوب وفق شرائط مذكورة في القانون ويتضمن أمراً صادراً من شخص هو الساحب إلى شخص آخر يكون معرفاً وهو المسحوب عليه بأن يدفع لشخص ثالث أو لأمره أو لحامل الشيك - وهو المستفيد - مبلغاً معيناً بمجرد الاطلاع على الشيك.\nد- السند لحامله أو القابل للانتقال بالتظهير.","law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","model_answer":"الأوراق التجارية: سند السحب (البوليصة/السفتجة): أمر من الساحب للمسحوب عليه بالدفع للمستفيد؛ سند الأمر (الكمبيالة): تعهد من المحرر بالدفع؛ الشيك: أمر بالدفع بمجرد الاطلاع؛ السند لحامله أو القابل للتظهير. (قانون التجارة 1966 – غير متوفر للتحقق)."},{"num":30,"type":"essay","q":"أ- يحتفظ البنك المركزي باحتياطي عام يقيد فيه 20% (عشرون بالمئة) من الربح الصافي للبنك المركزي في كل سنة مالية ويدفع الباقي أي (ثمانون بالمئة) من الربح الصافي للحكومة.\nب- تدفع جميع الأرباح الصافية للحكومة عندما يزيد مقدار الاحتياطي العام على مثلي رأس المال.","law":"other:قانون البنك المركزي الأردني","article":"","status":"unverified","model_answer":"من قانون البنك المركزي الأردني (غير متوفر هنا): يقيد 20% من صافي الربح السنوي في الاحتياطي العام ويدفع 80% للحكومة؛ وتدفع كامل الأرباح الصافية للحكومة إذا زاد الاحتياطي العام على مثلي رأس المال."},{"num":31,"type":"mcq","q":"وفقاً لقانون ضريبة المبيعات، يجوز للمدير أو المدقق حسب مقتضى الحال أن يصحح الأخطاء الحسابية التي تقع في القرارات عن طريق السهو العرضي:","o":["من تلقاء نفسه أو بناء على طلب المكلف ولا تكون إجراءات التصحيح خاضعة للطعن.","بناء على طلب المكلف وتكون إجراءات التصحيح خاضعة للطعن.","من تلقاء نفسه أو بناء على طلب المكلف وتكون إجراءات التصحيح خاضعة للطعن.","من تلقاء نفسه وتكون إجراءات التصحيح خاضعة للطعن."],"answer":0,"orig_answer":0,"law":"sales","article":"71","status":"valid","explanation":"المادة (71): للمدير أو الموظف المفوض أو المدقق في أي وقت تصحيح الأخطاء الكتابية والحسابية من تلقاء ذاته أو بناء على طلب المكلف ولا تكون إجراءات التصحيح خاضعة للطعن."},{"num":32,"type":"mcq","q":"وفقاً لقانون ضريبة المبيعات يتحمل المحاسب القانوني المسؤولية عن المصادقة على بيانات مالية تخالف معايير المحاسبة الدولية والأنظمة النافذة بسبب إهمال جسيم منه، ويعاقب وفقاً للقانون:","o":["لا تقل عن مقدار الضريبة ولا تزيد عن مثلي الضريبة أو بغرامة جزئية لا تقل عن 200 دينار ولا تزيد عن 500 دينار أو بكلتا العقوبتين.","لا يقل عن مثلي مقدار الضريبة ولا يزيد عن مثلي مقدار الضريبة أو بالحبس لمدة لا تقل عن ثلاثة أشهر ولا تزيد عن ستة أشهر.","لا تقل عن مثلي مقدار الضريبة ولا يزيد عن ثلاثة أمثالها وبغرامة جزئية لا تقل عن 200 دينار ولا تزيد عن 500 دينار.","لا يقل عن مثلي مقدار الضريبة ولا يزيد عن ثلاثة أمثالها وبغرامة جزئية لا تقل عن مئتي دينار ولا تزيد عن ألف دينار."],"answer":3,"orig_answer":3,"law":"sales","article":"67","status":"valid","explanation":"المادة (67): يعتبر المحاسب القانوني مرتكباً جرماً ويعاقب بعقوبة المادة (31): تعويض مدني لا يقل عن مثلي الضريبة ولا يزيد على ثلاثة أمثالها وغرامة جزائية 200–1,000 دينار."},{"num":33,"type":"mcq","q":"شركة قامت باستيراد خدمة بتاريخ 31-1-2022 وقامت بتسديد قيمة الخدمة بتاريخ 10-4-2022 وقامت بدفع ضريبة المبيعات بتاريخ 25-4-2022 فيترتب عليها:","o":["لا يترتب عليه غرامة الشركة.","يترتب على الشركة غرامة 0.4% عن كل أسبوع بعد نهاية شهر 2.","يترتب على الشركة غرامة 0.4% عن كل أسبوع بعد نهاية شهر 2، وغرامة مثل الضريبة.","يترتب على الشركة غرامة 0.4% عن كل أسبوع بعد نهاية شهر 2 وغرامة مثلي الضريبة."],"answer":0,"orig_answer":0,"law":"sales","article":"26","status":"valid","explanation":"المادة (26/ج): تدفع ضريبة الخدمة المستوردة أيهما أسبق: خلال شهر من دفع البدل (2022/5/10) أو خلال 6 أشهر من تلقيها (2022/7/31)؛ الأسبق 2022/5/10 والدفع تم في 2022/4/25 فلا غرامة."},{"num":34,"type":"essay","q":"قامت الشركة المتميزة بتاريخ 2022/1/1 بالتسجيل بشبكة المكلفين بالضريبة العامة على المبيعات وكان لديها بضاعة بتاريخ التسجيل بواقع 50,000 دينار مفصلة على النحو التالي:\nبضاعة خاضعة لنسبة 16% بواقع 35,000 دينار مشتراه بموجب فواتير ضريبية وتواريخها على النحو التالي:\n(رقم الفاتورة | تاريخ الفاتورة | قيمة الفاتورة شاملة الضريبة): 105 | 2015/1/1 | 15,000 ؛ 1234 | 2018/6/1 | 10,000 ؛ 117 | 2020/9/1 | 4,000 ؛ 2333 | 2021/11/1 | 6,000.\nبضاعة خاضعة لنسبة 4% بواقع 15,000 دينار مشتراه بموجب فواتير غير ضريبية.\nالمطلوب: احتساب قيمة الضريبة المقبول خصمها ضمن أول إقرار ضريبي تقديمه من قبل الشركة؟","law":"sales","article":"19","status":"valid","model_answer":"- المادة (19/د): للمسجل خصم ما سبق تحمله قبل التسجيل من ضريبة عامة على السلع التي في حوزته عند التسجيل (وتفاصيل الخصم في التعليمات).\n- بضاعة بفواتير ضريبية (حسب حل المُعِد تُرصّد 100%): 35,000 ÷ 1.16 = 30,172.41 × 16% = 4,827.585 دينار.\n- بضاعة 4% مشتراة من غير مسجلين بفواتير غير ضريبية: يرصد 50% من الضريبة المفترضة: 15,000 × 4% = 600 × 50% = 300 دينار.\n- المقبول خصمه في أول إقرار = 4,827.585 + 300 = 5,127.585 دينار."},{"num":35,"type":"essay","q":"احسب مبلغ ضريبة المبيعات للفترة 11+12 للعام 2022 إذا علمت أن بيانات الفترة كانت كما يلي:\nمشتريات خاضعة لنسبة 16% بواقع 20,000 دينار\nمستوردات خاضعة لنسبة 16% بواقع 15,000 دينار (تم إعادة تخمين البضاعة بقيمة 18,000 دينار)\nمصاريف الضيافة 1,160 شاملة الضريبة 16%\nمصاريف القرطاسية 116 دينار شاملة الضريبة 16%\nمبيعات معفاة بواقع 10,000 دينار\nمبيعات لجهات معفاة بواقع 30,000 دينار\nمبيعات خاضعة لنسبة 16% بواقع 50,000 دينار\nعلماً بأن الرصيد المدور من الفترة السابقة هو 1,500 دينار؟","law":"sales","article":"19","status":"unverified","model_answer":"حسب حل المُعِد:\n- ضريبة المخرجات: 50,000 × 16% = 8,000.\n- ضريبة المدخلات: مشتريات 3,200 + مستوردات (على القيمة المعاد تخمينها 18,000) 2,880 + قرطاسية 16 = 6,096؛ ضريبة الضيافة (160) غير قابلة للخصم (الجدول رقم 4 – المادة 19/ج).\n- ضريبة غير قابلة للخصم بالتناسب: السلع المعفاة (10,000/90,000)×16 = 1.777؛ الجهات المعفاة (30,000/90,000)×6,096 = 2,032.\n- الرصيد: 8,000 + 2,033.777 − (1,500 + 3,200 + 2,880 + 16) = 2,437.777 دينار لصالح الدائرة.\n- ملاحظة: أساس التوزيع النسبي للمدخلات مصدره التعليمات التنفيذية وليس نص القانون، وطريقة المُعِد في احتساب حصة السلع المعفاة (على القرطاسية فقط) محل نظر."}]}]};
